  SUBROUTINE AXSET(hk1, t1, rt1, a1, hk2, t2, rt2, a2, acrit, idampv, ax&
&   , ax_hk1, ax_t1, ax_rt1, ax_a1, ax_hk2, ax_t2, ax_rt2, ax_a2)
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    REAL :: a1, a2, acrit, ax, ax_a1, ax_a2, ax_hk1, ax_hk2, ax_rt1, &
&   ax_rt2, ax_t1, ax_t2, hk1, hk2, rt1, rt2, t1, t2
    INTEGER :: idampv
! intent (in) A1, A2, Acrit, Idampv
! intent (out) Ax, Ax_a1, Ax_a2, Ax_hk1, Ax_hk2, Ax_rt1, Ax_rt2, Ax_t1, Ax_t2
!
! Local variables
!
    REAL :: arg, ax1, ax1_hk1, ax1_rt1, ax1_t1, ax2, ax2_hk2, ax2_rt2, &
&   ax2_t2, axa, axa_ax1, axa_ax2, axsq, dax, dax_a1, dax_a2, dax_t1, &
&   dax_t2, exn, exn_a1, exn_a2
    INTRINSIC SQRT
    INTRINSIC MIN
    INTRINSIC EXP
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!----------------------------------------------------------
!     Returns average amplification AX over interval 1..2
!----------------------------------------------------------
!
!C==========================
!C---- 1st-order -- based on "1" quantities only
!      CALL DAMPL( HK1, T1, RT1, AX1, AX1_HK1, AX1_T1, AX1_RT1 )
!      AX2_HK2 = 0.0
!      AX2_T2  = 0.0
!      AX2_RT2 = 0.0
!C
!      AX1_A1 = 0.0
!      AX2_A2 = 0.0
!C
!      AX     = AX1
!      AX_AX1 = 1.0
!      AX_AX2 = 0.0
!C
!      ARG = MIN( 20.0*(ACRIT-A1) , 20.0 )
!      EXN    = EXP(-ARG)
!      EXN_A1 = 20.0*EXN
!      EXN_A2 = 0.
!C
!      DAX    = EXN   * 0.0004/T1
!      DAX_A1 = EXN_A1* 0.0004/T1
!      DAX_A2 = 0.
!      DAX_T1 = -DAX/T1
!      DAX_T2 = 0.
!
!==========================
!---- 2nd-order
    IF (idampv .EQ. 0) THEN
      CALL DAMPL(hk1, t1, rt1, ax1, ax1_hk1, ax1_t1, ax1_rt1)
      CALL DAMPL(hk2, t2, rt2, ax2, ax2_hk2, ax2_t2, ax2_rt2)
    ELSE
      CALL DAMPL2(hk1, t1, rt1, ax1, ax1_hk1, ax1_t1, ax1_rt1)
      CALL DAMPL2(hk2, t2, rt2, ax2, ax2_hk2, ax2_t2, ax2_rt2)
    END IF
!
!C---- simple-average version
!      AXA = 0.5*(AX1 + AX2)
!      IF(AXA .LE. 0.0) THEN
!       AXA = 0.0
!       AXA_AX1 = 0.0
!       AXA_AX2 = 0.0
!      ELSE
!       AXA_AX1 = 0.5
!       AXA_AX2 = 0.5
!      ENDIF
!
!---- rms-average version (seems a little better on coarse grids)
    axsq = 0.5*(ax1**2+ax2**2)
    IF (axsq .LE. 0.0) THEN
      axa = 0.0
      axa_ax1 = 0.0
      axa_ax2 = 0.0
    ELSE
      axa = SQRT(axsq)
      axa_ax1 = 0.5*ax1/axa
      axa_ax2 = 0.5*ax2/axa
    END IF
    IF (20.0*(acrit-0.5*(a1+a2)) .GT. 20.0) THEN
      arg = 20.0
    ELSE
      arg = 20.0*(acrit-0.5*(a1+a2))
    END IF
    IF (arg .LE. 0.0) THEN
      exn = 1.0
!C      EXN_AC = 0.
      exn_a1 = 0.
      exn_a2 = 0.
    ELSE
      exn = EXP(-arg)
!C      EXN_AC = -20.0    *EXN
      exn_a1 = 20.0*0.5*exn
      exn_a2 = 20.0*0.5*exn
    END IF
!
    dax = exn*0.002/(t1+t2)
!C     DAX_AC = EXN_AC * 0.002/(T1+T2)
    dax_a1 = exn_a1*0.002/(t1+t2)
    dax_a2 = exn_a2*0.002/(t1+t2)
    dax_t1 = -(dax/(t1+t2))
    dax_t2 = -(dax/(t1+t2))
!
!
!        DAX    = 0.
!        DAX_A1 = 0.
!        DAX_A2 = 0.
!        DAX_AC = 0.
!        DAX_T1 = 0.
!        DAX_T2 = 0.
!==========================
!
    ax = axa + dax
!
    ax_hk1 = axa_ax1*ax1_hk1
    ax_t1 = axa_ax1*ax1_t1 + dax_t1
    ax_rt1 = axa_ax1*ax1_rt1
    ax_a1 = dax_a1
!
    ax_hk2 = axa_ax2*ax2_hk2
    ax_t2 = axa_ax2*ax2_t2 + dax_t2
    ax_rt2 = axa_ax2*ax2_rt2
    ax_a2 = dax_a2
  END SUBROUTINE AXSET

