&   tt_x2b, utb, ut_a1b, ut_a2b, ut_u1b, ut_u2b, ut_x1b, ut_x2b, wf1b, &
&   wf1_a1b, wf1_a2b, wf1_x1b, wf1_x2b, wf2b, wf2_a1b, wf2_a2b
    REAL, SAVE :: daeps
    INTEGER :: icom, itam
    REAL :: wf2_x1, wf2_x2, wf2_xf, xt_a2, z_a1, z_a2, z_ax, z_d1, z_d2&
&   , z_ms, z_re, z_t1, z_t2, z_u1, z_u2, z_x1, z_x2, z_xf
    REAL :: wf2_x1b, wf2_x2b, xt_a2b, z_a1b, z_a2b, z_axb, z_d1b, z_d2b&
