      IF (sfa .LT. sfx) THEN
        CALL PUSHREAL8(wf2)
        wf2 = sfa
        wf2_a1 = sfa_a1
        CALL PUSHREAL8(wf2_a2)
        wf2_a2 = sfa_a2
        wf2_x1 = 0.
        wf2_x2 = 0.
        CALL PUSHCONTROL1B(0)
      ELSE
        CALL PUSHREAL8(wf2)
        wf2 = sfx
        wf2_a1 = 0.
        CALL PUSHREAL8(wf2_a2)
        wf2_a2 = 0.
        wf2_x1 = sfx_x1
        wf2_x2 = sfx_x2
        CALL PUSHCONTROL1B(1)
