!C---- 1st-order (based on "1" quantites only, for testing)
!      WF2    = 0.0
!      WF2_A1 = 0.0
!      WF2_A2 = 0.0
!      WF2_X1 = 0.0
!      WF2_X2 = 0.0
!      WF2_XF = 0.0
!=====================
!
      CALL PUSHREAL8(wf1)
      wf1 = 1.0 - wf2
      wf1_a1 = -wf2_a1
      CALL PUSHREAL8(wf1_a2)
      wf1_a2 = -wf2_a2
      wf1_x1 = -wf2_x1
      wf1_x2 = -wf2_x2
!
!---- interpolate BL variables to XT
      CALL PUSHREAL8(xt)
      xt = x1*wf1 + x2*wf2
      CALL PUSHREAL8(tt)
      tt = t1*wf1 + t2*wf2
      dt = d1*wf1 + d2*wf2
      ut = u1*wf1 + u2*wf2
!
      CALL PUSHREAL8(xt_a2)
      xt_a2 = x1*wf1_a2 + x2*wf2_a2
      CALL PUSHREAL8(tt_a2)
      tt_a2 = t1*wf1_a2 + t2*wf2_a2
      CALL PUSHREAL8(dt_a2)
      dt_a2 = d1*wf1_a2 + d2*wf2_a2
      CALL PUSHREAL8(ut_a2)
      ut_a2 = u1*wf1_a2 + u2*wf2_a2
!
!---- temporarily set "2" variables from "T" for BLKIN
      CALL PUSHREAL8(t2)
      t2 = tt
      CALL PUSHREAL8(d2)
      d2 = dt
      CALL PUSHREAL8(u2)
      u2 = ut
!
!---- calculate laminar secondary "T" variables HKT, RTT
      CALL PUSHREAL8(hk2)
      CALL PUSHREAL8(rt2)
      CALL BLKIN()
!
      CALL PUSHREAL8(hkt)
      hkt = hk2
      CALL PUSHREAL8(hkt_tt)
      hkt_tt = hk2_t2
      CALL PUSHREAL8(hkt_dt)
      hkt_dt = hk2_d2
      CALL PUSHREAL8(hkt_ut)
      hkt_ut = hk2_u2
      hkt_ms = hk2_ms
!
      CALL PUSHREAL8(rtt)
      rtt = rt2
      CALL PUSHREAL8(rtt_tt)
      rtt_tt = rt2_t2
      CALL PUSHREAL8(rtt_ut)
      rtt_ut = rt2_u2
      rtt_ms = rt2_ms
      rtt_re = rt2_re
!
!---- restore clobbered "2" variables, except for AMPL2
      amsave = ampl2
      CALL PUSHREAL8(ampl2)
      CALL PUSHREAL8(u2)
      CALL PUSHREAL8(x2)
      CALL PUSHREAL8(cf2)
      CALL PUSHREAL8(d2)
      CALL PUSHREAL8(t2)
      CALL BLC_RESTORE2()
      ampl2 = amsave
!
!---- calculate amplification rate AX over current X1-XT interval
      CALL AXSET_FWD(hk1, t1, rt1, ampl1, hkt, tt, rtt, amplt, amcrit, &
&              idampv, ax, ax_hk1, ax_t1, ax_rt1, ax_a1, ax_hkt, ax_tt, &
&              ax_rtt, ax_at)
!
!---- punch out early if there is no amplification here
      IF (ax .LE. 0.0) THEN
        GOTO 110
      ELSE
!
!---- set sensitivity of AX(A2)
        CALL PUSHREAL8(ax_a2)
        ax_a2 = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_a2 + ax_hkt*&
&         hkt_dt*dt_a2 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_a2 + ax_at*&
&         amplt_a2
!
!---- residual for implicit AMPL2 definition (amplification equation)
        CALL PUSHREAL8(res)
        res = ampl2 - ampl1 - ax*(x2-x1)
        CALL PUSHREAL8(res_a2)
        res_a2 = 1.0 - ax_a2*(x2-x1)
!
        CALL PUSHREAL8(da2)
        da2 = -(res/res_a2)
!
        CALL PUSHREAL8(rlx)
        rlx = 1.0
        dxt = xt_a2*da2
        IF (dxt/(x2-x1) .GE. 0.) THEN
          abs0 = dxt/(x2-x1)
        ELSE
          abs0 = -(dxt/(x2-x1))
        END IF
!
        IF (rlx*abs0 .GT. 0.05) THEN
          IF ((x2-x1)/dxt .GE. 0.) THEN
            abs1 = (x2-x1)/dxt
            CALL PUSHCONTROL1B(0)
          ELSE
            abs1 = -((x2-x1)/dxt)
            CALL PUSHCONTROL1B(1)
          END IF
          rlx = 0.05*abs1
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        IF (da2 .GE. 0.) THEN
          abs2 = da2
        ELSE
          abs2 = -da2
        END IF
        IF (rlx*abs2 .GT. 1.0) THEN
          IF (1.0/da2 .GE. 0.) THEN
            abs3 = 1.0/da2
            CALL PUSHCONTROL1B(0)
          ELSE
            abs3 = -(1.0/da2)
            CALL PUSHCONTROL1B(1)
          END IF
          rlx = 1.0*abs3
          CALL PUSHCONTROL1B(1)
        ELSE
          CALL PUSHCONTROL1B(0)
        END IF
        IF (da2 .GE. 0.) THEN
          abs4 = da2
        ELSE
          abs4 = -da2
        END IF
!
!---- check if converged
        IF (abs4 .LT. daeps) THEN
          GOTO 120
        ELSE
!
          ampl2r = ampl2
          amcritr = amcrit
! if ((AMPl2>AMCrit .and. AMPl2 + rlx * da2<AMCrit) .or. (AMPl2<AMCrit .and. AMPl2 + rlx * da2>AMCrit)) then
          IF ((ampl2r .GT. amcritr .AND. ampl2r + rlx*da2 .LT. amcritr) &
&             .OR. (ampl2r .LT. amcritr .AND. ampl2r + rlx*da2 .GT. &
&             amcritr)) THEN
!------ limited Newton step so AMPL2 doesn't step across AMCRIT either way
            ampl2 = amcrit
            CALL PUSHCONTROL1B(1)
          ELSE
!------ regular Newton step
            ampl2 = ampl2 + rlx*da2
            CALL PUSHCONTROL1B(0)
          END IF
          ad_count = ad_count + 1
        END IF
      END IF
    END DO
    CALL PUSHCONTROL2B(0)
    CALL PUSHINTEGER4(ad_count)
! Check if ANY of these printed variables contain NaN's. If they do, convergence will never be reached.
! if (X1 /= X1 .or. XT /= XT .or. X2 /= X2 .or. AMPl1 /= AMPl1 .or. &
! amplt /= amplt .or. AMPl2 /= AMPl2 .or. ax /= ax .or. da2 /= da2) then
! trchek2 = .false.
! if (abort_on_nan) return
! end if
    x1r = x1
    x2r = x2
    result1 = EPSILON(x1r)
    result2 = EPSILON(x1r)
    result3 = EPSILON(xt)
    result4 = EPSILON(xt)
    result5 = EPSILON(x2r)
    result6 = EPSILON(x2r)
    result7 = EPSILON(amplt)
    result8 = EPSILON(amplt)
    result9 = EPSILON(ax)
    result10 = EPSILON(ax)
    result11 = EPSILON(da2)
    result12 = EPSILON(da2)
    IF ((((((((.NOT.(x1r .GE. x1r - result1 .AND. x1r .LE. x1r + result2&
&       )) .OR. (.NOT.(xt .GE. xt - result3 .AND. xt .LE. xt + result4))&
&       ) .OR. (.NOT.(x2r .GE. x2r - result5 .AND. x2r .LE. x2r + &
&       result6))) .OR. ampl1 .NE. ampl1) .OR. (.NOT.(amplt .GE. amplt -&
&       result7 .AND. amplt .LE. amplt + result8))) .OR. ampl2 .NE. &
&       ampl2) .OR. (.NOT.(ax .GE. ax - result9 .AND. ax .LE. ax + &
&       result10))) .OR. (.NOT.(da2 .GE. da2 - result11 .AND. da2 .LE. &
&       da2 + result12))) THEN
      IF (abort_on_nan) THEN
        hkt_msb = 0.0_8
        dt_a2b = 0.0_8
        ax_a1b = 0.0_8
        ax_rt1b = 0.0_8
        wf2_a1b = 0.0_8
        rtt_ttb = 0.0_8
        hkt_ttb = 0.0_8
        hkt_dtb = 0.0_8
        wf1_a1b = 0.0_8
        ax_hk1b = 0.0_8
        axb = 0.0_8
        xt_a2b = 0.0_8
        wf2_x1b = 0.0_8
        wf2_x2b = 0.0_8
        wf1_x1b = 0.0_8
        wf1_x2b = 0.0_8
        rtt_reb = 0.0_8
        tt_a2b = 0.0_8
        rtt_utb = 0.0_8
        hkt_utb = 0.0_8
        ax_ttb = 0.0_8
        ut_a2b = 0.0_8
        wf1b = 0.0_8
        wf2b = 0.0_8
        ax_atb = 0.0_8
        ax_rttb = 0.0_8
        ax_hktb = 0.0_8
        ax_t1b = 0.0_8
        rtt_msb = 0.0_8
        GOTO 130
      ELSE
        CALL PUSHCONTROL2B(1)
      END IF
    ELSE
      CALL PUSHCONTROL2B(2)
    END IF
! 
!
!
!
!---- test for free or forced transition
! 100  TRFree = AMPl2>=AMCrit
    ampl2r = ampl2
    amcritr = amcrit
    GOTO 100
 110 CALL PUSHCONTROL2B(1)
    CALL PUSHINTEGER4(ad_count)
    CALL PUSHCONTROL2B(0)
    GOTO 100
 120 CALL PUSHCONTROL2B(2)
    CALL PUSHINTEGER4(ad_count)
    CALL PUSHCONTROL2B(0)
 100 IF (ampl2r .GE. amcritr) THEN
      trfree = .true.
    ELSE
      trfree = .false.
    END IF
    xiforcr = xiforc
    x1r = x1
    x2r = x2
! TRForc = XIForc>X1 .and. XIForc<=X2
    trforc = xiforcr .GT. x1r .AND. xiforcr .LE. x2r
!
!---- set transition interval flag
    CALL PUSHBOOLEAN(tran)
    tran = trforc .OR. trfree
!
    IF (abort_on_nan .AND. (.NOT.tran)) THEN
      hkt_msb = 0.0_8
      dt_a2b = 0.0_8
      ax_a1b = 0.0_8
      ax_rt1b = 0.0_8
      wf2_a1b = 0.0_8
      rtt_ttb = 0.0_8
      hkt_ttb = 0.0_8
      hkt_dtb = 0.0_8
      wf1_a1b = 0.0_8
      ax_hk1b = 0.0_8
      axb = 0.0_8
      xt_a2b = 0.0_8
      wf2_x1b = 0.0_8
      wf2_x2b = 0.0_8
      wf1_x1b = 0.0_8
      wf1_x2b = 0.0_8
      rtt_reb = 0.0_8
      tt_a2b = 0.0_8
      rtt_utb = 0.0_8
      hkt_utb = 0.0_8
      ax_ttb = 0.0_8
      ut_a2b = 0.0_8
      wf1b = 0.0_8
      wf2b = 0.0_8
      ax_atb = 0.0_8
      ax_rttb = 0.0_8
      ax_hktb = 0.0_8
      ax_t1b = 0.0_8
      rtt_msb = 0.0_8
    ELSE
!
!---- resolve if both forced and free transition
      IF (trfree .AND. trforc) trforc = xiforc .LT. xt
!
      IF (trforc) THEN
        xiforcb = xiforcb + xtb
        xtb = 0.0_8
        hkt_msb = 0.0_8
        dt_a2b = 0.0_8
        ax_a1b = 0.0_8
        ax_rt1b = 0.0_8
        wf2_a1b = 0.0_8
        rtt_ttb = 0.0_8
        hkt_ttb = 0.0_8
        hkt_dtb = 0.0_8
        wf1_a1b = 0.0_8
        ax_hk1b = 0.0_8
        axb = 0.0_8
        xt_a2b = 0.0_8
        wf2_x1b = 0.0_8
        wf2_x2b = 0.0_8
        wf1_x1b = 0.0_8
        wf1_x2b = 0.0_8
        rtt_reb = 0.0_8
        tt_a2b = 0.0_8
        rtt_utb = 0.0_8
        hkt_utb = 0.0_8
        ax_ttb = 0.0_8
        ut_a2b = 0.0_8
        wf1b = 0.0_8
        wf2b = 0.0_8
        ax_atb = 0.0_8
        ax_rttb = 0.0_8
        ax_hktb = 0.0_8
        ax_t1b = 0.0_8
        rtt_msb = 0.0_8
      ELSE
!
!---- free transition ... set sensitivities of XT
!
!---- XT( X1 X2 A1 A2 XF ),  TT( T1 T2 A1 A2 X1 X2 XF),   DT( ...
!C    XT    = X1*WF1    + X2*WF2
!C    TT    = T1*WF1    + T2*WF2
!C    DT    = D1*WF1    + D2*WF2
!C    UT    = U1*WF1    + U2*WF2
!
        tt_t1 = wf1
        dt_d1 = wf1
        ut_u1 = wf1
!
        tt_t2 = wf2
        dt_d2 = wf2
        ut_u2 = wf2
!
        tt_a1 = t1*wf1_a1 + t2*wf2_a1
        dt_a1 = d1*wf1_a1 + d2*wf2_a1
        ut_a1 = u1*wf1_a1 + u2*wf2_a1
!
!C    XT_A2 = X1*WF1_A2 + X2*WF2_A2
!C    TT_A2 = T1*WF1_A2 + T2*WF2_A2
!C    DT_A2 = D1*WF1_A2 + D2*WF2_A2
!C    UT_A2 = U1*WF1_A2 + U2*WF2_A2
!
        tt_x1 = t1*wf1_x1 + t2*wf2_x1
        dt_x1 = d1*wf1_x1 + d2*wf2_x1
        ut_x1 = u1*wf1_x1 + u2*wf2_x1
!
        tt_x2 = t1*wf1_x2 + t2*wf2_x2
        dt_x2 = d1*wf1_x2 + d2*wf2_x2
        ut_x2 = u1*wf1_x2 + u2*wf2_x2
!
!
!---- at this point, AX = AX( HK1, T1, RT1, A1, HKT, TT, RTT, AT )
!
!---- set sensitivities of AX( T1 D1 U1 A1 T2 D2 U2 A2 MS RE )
        ax_t1 = ax_hk1*hk1_t1 + ax_t1 + ax_rt1*rt1_t1 + (ax_hkt*hkt_tt+&
&         ax_tt+ax_rtt*rtt_tt)*tt_t1
        ax_d1 = ax_hk1*hk1_d1 + ax_hkt*hkt_dt*dt_d1
        ax_u1 = ax_hk1*hk1_u1 + ax_rt1*rt1_u1 + (ax_hkt*hkt_ut+ax_rtt*&
&         rtt_ut)*ut_u1
        ax_a1 = ax_a1 + (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_a1 + &
&         ax_hkt*hkt_dt*dt_a1 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_a1
        ax_x1 = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_x1 + ax_hkt*&
&         hkt_dt*dt_x1 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_x1
!
        ax_t2 = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_t2
        ax_d2 = ax_hkt*hkt_dt*dt_d2
        ax_u2 = (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_u2
        CALL PUSHREAL8(ax_a2)
        ax_a2 = ax_at*amplt_a2 + (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*&
&         tt_a2 + ax_hkt*hkt_dt*dt_a2 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*&
&         ut_a2
        ax_x2 = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_x2 + ax_hkt*&
&         hkt_dt*dt_x2 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_x2
!
!
        ax_ms = ax_hkt*hkt_ms + ax_rtt*rtt_ms + ax_hk1*hk1_ms + ax_rt1*&
&         rt1_ms
        ax_re = ax_rtt*rtt_re + ax_rt1*rt1_re
!
!
!---- set sensitivities of residual RES
!CC   RES  = AMPL2 - AMPL1 - AX*(X2-X1)
        z_ax = -(x2-x1)
!
        z_a1 = z_ax*ax_a1 - 1.0
        z_t1 = z_ax*ax_t1
        z_d1 = z_ax*ax_d1
        z_u1 = z_ax*ax_u1
        z_x1 = z_ax*ax_x1 + ax
!
        z_a2 = z_ax*ax_a2 + 1.0
        z_t2 = z_ax*ax_t2
        z_d2 = z_ax*ax_d2
        z_u2 = z_ax*ax_u2
        z_x2 = z_ax*ax_x2 - ax
!
        z_ms = z_ax*ax_ms
        z_re = z_ax*ax_re
!
!---- set sensitivities of XT, with RES being stationary for A2 constraint
        tempb0 = -(xt_reb/z_a2)
        xt_a2b = z_re*tempb0
        z_reb = xt_a2*tempb0
        z_a2b = -(xt_a2*z_re*tempb0/z_a2)
        tempb0 = -(xt_msb/z_a2)
        xt_a2b = xt_a2b + z_ms*tempb0
        z_msb = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_ms*tempb0/z_a2
        tempb0 = -(xt_x2b/z_a2)
        xt_a2b = xt_a2b + z_x2*tempb0
        z_x2b = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_x2*tempb0/z_a2
        tempb0 = -(xt_u2b/z_a2)
        xt_a2b = xt_a2b + z_u2*tempb0
        z_u2b = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_u2*tempb0/z_a2
        tempb0 = -(xt_d2b/z_a2)
        xt_a2b = xt_a2b + z_d2*tempb0
        z_d2b = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_d2*tempb0/z_a2
        tempb0 = -(xt_t2b/z_a2)
        xt_a2b = xt_a2b + z_t2*tempb0
        z_t2b = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_t2*tempb0/z_a2
        tempb0 = -(xt_x1b/z_a2)
        xt_a2b = xt_a2b + z_x1*tempb0
        z_x1b = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_x1*tempb0/z_a2
        tempb0 = -(xt_u1b/z_a2)
        xt_a2b = xt_a2b + z_u1*tempb0
        z_u1b = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_u1*tempb0/z_a2
        tempb0 = -(xt_d1b/z_a2)
        xt_a2b = xt_a2b + z_d1*tempb0
        z_d1b = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_d1*tempb0/z_a2
        tempb0 = -(xt_t1b/z_a2)
        xt_a2b = xt_a2b + z_t1*tempb0
        z_t1b = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_t1*tempb0/z_a2
        tempb0 = -(xt_a1b/z_a2)
        xt_a2b = xt_a2b + z_a1*tempb0
        z_a1b = xt_a2*tempb0
        z_a2b = z_a2b - xt_a2*z_a1*tempb0/z_a2
        z_axb = ax_re*z_reb + ax_ms*z_msb + ax_x2*z_x2b + ax_u2*z_u2b + &
&         ax_d2*z_d2b + ax_t2*z_t2b + ax_a2*z_a2b + ax_x1*z_x1b + ax_u1*&
&         z_u1b + ax_d1*z_d1b + ax_t1*z_t1b + ax_a1*z_a1b
        ax_reb = z_ax*z_reb
        ax_msb = z_ax*z_msb
        ax_x2b = z_ax*z_x2b
        axb = z_x1b - z_x2b
        ax_u2b = z_ax*z_u2b
        ax_d2b = z_ax*z_d2b
        ax_t2b = z_ax*z_t2b
        ax_a2b = z_ax*z_a2b
        ax_x1b = z_ax*z_x1b
        ax_u1b = z_ax*z_u1b
        ax_d1b = z_ax*z_d1b
        ax_t1b = z_ax*z_t1b
        ax_a1b = z_ax*z_a1b
        x1b = x1b + z_axb + wf1_x2*xt_x2b + wf1_x1*xt_x1b + wf1_a1*&
&         xt_a1b
        x2b = x2b + wf2_x2*xt_x2b - z_axb + wf2_x1*xt_x1b + wf2_a1*&
&         xt_a1b
        rtt_reb = ax_rtt*ax_reb
        ax_rt1b = rt1_re*ax_reb + rt1_ms*ax_msb + rt1_u1*ax_u1b + rt1_t1&
&         *ax_t1b
        rt1_reb = rt1_reb + ax_rt1*ax_reb
        hkt_msb = ax_hkt*ax_msb
        rtt_msb = ax_rtt*ax_msb
        ax_hk1b = hk1_ms*ax_msb + hk1_u1*ax_u1b + hk1_d1*ax_d1b + hk1_t1&
&         *ax_t1b
        hk1_msb = hk1_msb + ax_hk1*ax_msb
        rt1_msb = rt1_msb + ax_rt1*ax_msb
        tempb0 = tt_x2*ax_x2b
        tt_x2b = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*ax_x2b
        hkt_dtb = ax_hkt*dt_x2*ax_x2b + ax_hkt*dt_a2*ax_a2b + ax_hkt*&
&         dt_d2*ax_d2b + ax_hkt*dt_x1*ax_x1b + ax_hkt*dt_a1*ax_a1b + &
&         ax_hkt*dt_d1*ax_d1b
        dt_x2b = ax_hkt*hkt_dt*ax_x2b
        tempb = ut_x2*ax_x2b
        ax_rttb = rtt_re*ax_reb + rtt_ms*ax_msb + rtt_ut*tempb + rtt_tt*&
&         tempb0
        ax_hktb = hkt_ms*ax_msb + hkt_dt*dt_x2*ax_x2b + hkt_ut*tempb + &
&         hkt_tt*tempb0
        ut_x2b = (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ax_x2b
        hkt_utb = ax_hkt*tempb
        rtt_utb = ax_rtt*tempb
        hkt_ttb = ax_hkt*tempb0
        ax_ttb = tempb0
        rtt_ttb = ax_rtt*tempb0
        CALL POPREAL8(ax_a2)
        ax_atb = amplt_a2*ax_a2b
        tempb0 = tt_a2*ax_a2b
        tt_a2b = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*ax_a2b
        dt_a2b = ax_hkt*hkt_dt*ax_a2b
        tempb = ut_a2*ax_a2b
        ax_hktb = ax_hktb + hkt_dt*dt_a2*ax_a2b + hkt_ut*tempb + hkt_tt*&
&         tempb0
        ut_a2b = (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ax_a2b
        hkt_utb = hkt_utb + ax_hkt*tempb
        ax_rttb = ax_rttb + rtt_ut*tempb + rtt_tt*tempb0
        rtt_utb = rtt_utb + ax_rtt*tempb
        hkt_ttb = hkt_ttb + ax_hkt*tempb0
        ax_ttb = ax_ttb + tempb0
        rtt_ttb = rtt_ttb + ax_rtt*tempb0
        tempb0 = ut_u2*ax_u2b
        ut_u2b = (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ax_u2b
        ax_hktb = ax_hktb + hkt_ut*tempb0
        ax_rttb = ax_rttb + rtt_ut*tempb0
        dt_d2b = ax_hkt*hkt_dt*ax_d2b
        tt_t2b = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*ax_t2b
        tt_x1b = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*ax_x1b
        dt_x1b = ax_hkt*hkt_dt*ax_x1b
        tempb = ut_x1*ax_x1b
        hkt_utb = hkt_utb + ax_hkt*tempb0 + ax_hkt*tempb
        rtt_utb = rtt_utb + ax_rtt*tempb0 + ax_rtt*tempb
        tempb0 = tt_t2*ax_t2b
        ax_hktb = ax_hktb + hkt_dt*dt_d2*ax_d2b + hkt_tt*tempb0
        hkt_ttb = hkt_ttb + ax_hkt*tempb0
        ax_ttb = ax_ttb + tempb0
        ax_rttb = ax_rttb + rtt_tt*tempb0
        rtt_ttb = rtt_ttb + ax_rtt*tempb0
        tempb0 = tt_x1*ax_x1b
        ax_hktb = ax_hktb + hkt_dt*dt_x1*ax_x1b + hkt_ut*tempb + hkt_tt*&
&         tempb0
        ut_x1b = (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ax_x1b
        ax_rttb = ax_rttb + rtt_ut*tempb + rtt_tt*tempb0
        hkt_ttb = hkt_ttb + ax_hkt*tempb0
        ax_ttb = ax_ttb + tempb0
        rtt_ttb = rtt_ttb + ax_rtt*tempb0
        tempb0 = tt_a1*ax_a1b
        tt_a1b = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*ax_a1b
        dt_a1b = ax_hkt*hkt_dt*ax_a1b
        tempb = ut_a1*ax_a1b
        ax_hktb = ax_hktb + hkt_dt*dt_a1*ax_a1b + hkt_ut*tempb + hkt_tt*&
&         tempb0
        ut_a1b = (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ax_a1b
        ax_rttb = ax_rttb + rtt_ut*tempb + rtt_tt*tempb0
        hkt_ttb = hkt_ttb + ax_hkt*tempb0
        ax_ttb = ax_ttb + tempb0
        rtt_ttb = rtt_ttb + ax_rtt*tempb0
        hk1_u1b = hk1_u1b + ax_hk1*ax_u1b
        rt1_u1b = rt1_u1b + ax_rt1*ax_u1b
        tempb0 = ut_u1*ax_u1b
        hkt_utb = hkt_utb + ax_hkt*tempb + ax_hkt*tempb0
        rtt_utb = rtt_utb + ax_rtt*tempb + ax_rtt*tempb0
        ut_u1b = (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ax_u1b
        ax_hktb = ax_hktb + hkt_ut*tempb0
        ax_rttb = ax_rttb + rtt_ut*tempb0
        hk1_d1b = hk1_d1b + ax_hk1*ax_d1b
        dt_d1b = ax_hkt*hkt_dt*ax_d1b
        hk1_t1b = hk1_t1b + ax_hk1*ax_t1b
        rt1_t1b = rt1_t1b + ax_rt1*ax_t1b
        tempb0 = tt_t1*ax_t1b
        ax_hktb = ax_hktb + hkt_dt*dt_d1*ax_d1b + hkt_tt*tempb0
        tt_t1b = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*ax_t1b
        hkt_ttb = hkt_ttb + ax_hkt*tempb0
        ax_ttb = ax_ttb + tempb0
        ax_rttb = ax_rttb + rtt_tt*tempb0
        rtt_ttb = rtt_ttb + ax_rtt*tempb0
        u1b = u1b + wf1_x2*ut_x2b + wf1_x1*ut_x1b + wf1_a1*ut_a1b
        wf1_x2b = u1*ut_x2b + d1*dt_x2b + t1*tt_x2b + x1*xt_x2b
        u2b = u2b + wf2_x2*ut_x2b + wf2_x1*ut_x1b + wf2_a1*ut_a1b
        wf2_x2b = u2*ut_x2b + d2*dt_x2b + t2*tt_x2b + x2*xt_x2b
        d1b = d1b + wf1_x2*dt_x2b + wf1_x1*dt_x1b + wf1_a1*dt_a1b
        d2b = d2b + wf2_x2*dt_x2b + wf2_x1*dt_x1b + wf2_a1*dt_a1b
        t1b = t1b + wf1_x2*tt_x2b + wf1_x1*tt_x1b + wf1_a1*tt_a1b
        t2b = t2b + wf2_x2*tt_x2b + wf2_x1*tt_x1b + wf2_a1*tt_a1b
        wf1_x1b = u1*ut_x1b + d1*dt_x1b + t1*tt_x1b + x1*xt_x1b
        wf2_x1b = u2*ut_x1b + d2*dt_x1b + t2*tt_x1b + x2*xt_x1b
        wf1_a1b = u1*ut_a1b + d1*dt_a1b + t1*tt_a1b + x1*xt_a1b
        wf2_a1b = u2*ut_a1b + d2*dt_a1b + t2*tt_a1b + x2*xt_a1b
        wf2b = ut_u2b + dt_d2b + tt_t2b + xt_x2b
        wf1b = ut_u1b + dt_d1b + tt_t1b + xt_x1b
      END IF
      xt_reb = 0.0_8
      xt_t1b = 0.0_8
      xt_t2b = 0.0_8
      xt_d1b = 0.0_8
      xt_d2b = 0.0_8
      xt_a1b = 0.0_8
      xt_x1b = 0.0_8
      xt_x2b = 0.0_8
      xt_u1b = 0.0_8
      xt_u2b = 0.0_8
      xt_msb = 0.0_8
    END IF
    CALL POPBOOLEAN(tran)
    CALL POPCONTROL2B(branch)
 130 CALL POPINTEGER4(ad_count)
    DO 150 i=1,ad_count
      IF (i .EQ. 1) THEN
        CALL POPCONTROL2B(branch)
        IF (branch .EQ. 0) THEN
          GOTO 150
        ELSE IF (branch .EQ. 1) THEN
          GOTO 140
        ELSE
          rlxb = 0.0_8
          da2b = 0.0_8
        END IF
      ELSE
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          rlxb = da2*ampl2b
          da2b = rlx*ampl2b
        ELSE
          amcritb = amcritb + ampl2b
          ampl2b = 0.0_8
          rlxb = 0.0_8
          da2b = 0.0_8
        END IF
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .NE. 0) THEN
        abs3b = rlxb
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          da2b = da2b - abs3b/da2**2
        ELSE
          da2b = da2b + abs3b/da2**2
        END IF
        rlxb = 0.0_8
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        dxtb = 0.0_8
      ELSE
        abs1b = 0.05*rlxb
        dxt = xt_a2*da2
        CALL POPCONTROL1B(branch)
        IF (branch .EQ. 0) THEN
          tempb0 = abs1b/dxt
          x2b = x2b + tempb0
          x1b = x1b - tempb0
          dxtb = -((x2-x1)*tempb0/dxt)
        ELSE
          tempb0 = -(abs1b/dxt)
          x2b = x2b + tempb0
          x1b = x1b - tempb0
          dxtb = -((x2-x1)*tempb0/dxt)
        END IF
      END IF
      xt_a2b = xt_a2b + da2*dxtb
      da2b = da2b + xt_a2*dxtb
      CALL POPREAL8(rlx)
      CALL POPREAL8(da2)
      resb = -(da2b/res_a2)
      res_a2b = res*da2b/res_a2**2
      CALL POPREAL8(res_a2)
      ax_a2b = -((x2-x1)*res_a2b)
      x2b = x2b - ax_a2*res_a2b - ax*resb
      x1b = x1b + ax_a2*res_a2b + ax*resb
      CALL POPREAL8(res)
      ampl2b = ampl2b + resb
      ampl1b = ampl1b - resb
      axb = axb - (x2-x1)*resb
      CALL POPREAL8(ax_a2)
      tempb0 = tt_a2*ax_a2b
      tt_a2b = tt_a2b + (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*ax_a2b
      hkt_dtb = hkt_dtb + ax_hkt*dt_a2*ax_a2b
      dt_a2b = dt_a2b + ax_hkt*hkt_dt*ax_a2b
      tempb = ut_a2*ax_a2b
      ax_hktb = ax_hktb + hkt_dt*dt_a2*ax_a2b + hkt_ut*tempb + hkt_tt*&
&       tempb0
      ut_a2b = ut_a2b + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ax_a2b
      ax_atb = ax_atb + amplt_a2*ax_a2b
      hkt_utb = hkt_utb + ax_hkt*tempb
      ax_rttb = ax_rttb + rtt_ut*tempb + rtt_tt*tempb0
      rtt_utb = rtt_utb + ax_rtt*tempb
      hkt_ttb = hkt_ttb + ax_hkt*tempb0
      ax_ttb = ax_ttb + tempb0
      rtt_ttb = rtt_ttb + ax_rtt*tempb0
 140  hktb = 0.0_8
      ttb = 0.0_8
      rttb = 0.0_8
      ampltb = 0.0_8
      CALL AXSET_BWD(hk1, hk1b, t1, t1b, rt1, rt1b, ampl1, ampl1b, hkt, &
&              hktb, tt, ttb, rtt, rttb, amplt, ampltb, amcrit, amcritb&
&              , idampv, ax, axb, ax_hk1, ax_hk1b, ax_t1, ax_t1b, ax_rt1&
&              , ax_rt1b, ax_a1, ax_a1b, ax_hkt, ax_hktb, ax_tt, ax_ttb&
&              , ax_rtt, ax_rttb, ax_at, ax_atb)
      amsaveb = ampl2b
      CALL POPREAL8(t2)
      CALL POPREAL8(d2)
      CALL POPREAL8(cf2)
      CALL POPREAL8(x2)
      CALL POPREAL8(u2)
      CALL POPREAL8(ampl2)
      ampl2b = 0.0_8
      CALL BLC_RESTORE2_B()
      ampl2b = amsaveb
      rt2_reb = rtt_reb
      rt2_msb = rtt_msb
      CALL POPREAL8(rtt_ut)
      rt2_u2b = rtt_utb
      CALL POPREAL8(rtt_tt)
      rt2_t2b = rtt_ttb
      CALL POPREAL8(rtt)
      rt2b = rttb
      hk2_msb = hkt_msb
      CALL POPREAL8(hkt_ut)
      hk2_u2b = hkt_utb
      CALL POPREAL8(hkt_dt)
      hk2_d2b = hkt_dtb
      CALL POPREAL8(hkt_tt)
      hk2_t2b = hkt_ttb
      CALL POPREAL8(hkt)
      hk2b = hktb
      CALL POPREAL8(rt2)
      CALL POPREAL8(hk2)
      r2b = 0.0_8
      h2_d2b = 0.0_8
      u2b = 0.0_8
      h2_t2b = 0.0_8
      h2b = 0.0_8
      v2_reb = 0.0_8
      d2b = 0.0_8
      t2b = 0.0_8
      r2_msb = 0.0_8
      m2b = 0.0_8
      m2_msb = 0.0_8
      v2_msb = 0.0_8
      r2_u2b = 0.0_8
      m2_u2b = 0.0_8
      v2b = 0.0_8
      v2_u2b = 0.0_8
      CALL BLKIN_B()
      CALL POPREAL8(u2)
      utb = u2b
      CALL POPREAL8(d2)
      dtb = d2b
      CALL POPREAL8(t2)
      ttb = ttb + t2b
      CALL POPREAL8(ut_a2)
      u1b = u1b + wf1_a2*ut_a2b + wf1*utb
      wf1_a2b = u1*ut_a2b + d1*dt_a2b + t1*tt_a2b + x1*xt_a2b
      u2b = wf2_a2*ut_a2b + wf2*utb
      wf2_a2b = u2*ut_a2b + d2*dt_a2b + t2*tt_a2b + x2*xt_a2b - wf1_a2b
      CALL POPREAL8(dt_a2)
      d1b = d1b + wf1_a2*dt_a2b + wf1*dtb
      d2b = wf2_a2*dt_a2b + wf2*dtb
      CALL POPREAL8(tt_a2)
      t1b = t1b + wf1_a2*tt_a2b + wf1*ttb
      t2b = wf2_a2*tt_a2b + wf2*ttb
      CALL POPREAL8(xt_a2)
      x1b = x1b + wf1_a2*xt_a2b + wf1*xtb
      x2b = wf2_a2*xt_a2b + wf2*xtb
      wf1b = wf1b + u1*utb + d1*dtb + t1*ttb + x1*xtb
      wf2b = wf2b + u2*utb + d2*dtb + t2*ttb + x2*xtb - wf1b
      CALL POPREAL8(tt)
      CALL POPREAL8(xt)
      wf2_x2b = wf2_x2b - wf1_x2b
      wf2_x1b = wf2_x1b - wf1_x1b
      CALL POPREAL8(wf1_a2)
      wf2_a1b = wf2_a1b - wf1_a1b
      CALL POPREAL8(wf1)
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(wf2_a2)
        sfa_a2b = wf2_a2b
        sfa_a1b = wf2_a1b
        CALL POPREAL8(wf2)
        sfab = wf2b
        sfx_x1b = 0.0_8
        sfx_x2b = 0.0_8
        sfxb = 0.0_8
      ELSE
        sfx_x2b = wf2_x2b
        sfx_x1b = wf2_x1b
        CALL POPREAL8(wf2_a2)
        CALL POPREAL8(wf2)
        sfxb = wf2b
        sfab = 0.0_8
        sfa_a1b = 0.0_8
        sfa_a2b = 0.0_8
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        tempb0 = -(sfx_x2b/(x2-x1))
        sfxb = sfxb + tempb0
        tempb = -(sfx*tempb0/(x2-x1))
        x2b = x2b + tempb
        x1b = x1b - tempb
        tempb0 = sfx_x1b/(x2-x1)
        sfxb = sfxb + tempb0
        tempb = -((sfx-1.0)*tempb0/(x2-x1))
        x2b = x2b + tempb
        x1b = x1b - tempb
        CALL POPREAL8(sfx)
        tempb0 = sfxb/(x2-x1)
        xiforcb = xiforcb + tempb0
        tempb = -((xiforc-x1)*tempb0/(x2-x1))
        x1b = x1b - tempb0 - tempb
        x2b = x2b + tempb
      ELSE
        CALL POPREAL8(sfx)
      END IF
      CALL POPCONTROL1B(branch)
      IF (branch .EQ. 0) THEN
        CALL POPREAL8(sfa)
        CALL POPREAL8(amplt_a2)
        CALL POPREAL8(amplt)
        ampl2b = ampl2b + ampltb
      ELSE
        tempb0 = -(sfa_a2b/(ampl2-ampl1))
        sfab = sfab + tempb0
        tempb = -(sfa*tempb0/(ampl2-ampl1))
        ampl2b = ampl2b + tempb
        ampl1b = ampl1b - tempb
        tempb0 = sfa_a1b/(ampl2-ampl1)
        sfab = sfab + tempb0
        tempb = -((sfa-1.0)*tempb0/(ampl2-ampl1))
        ampl2b = ampl2b + tempb
        ampl1b = ampl1b - tempb
        CALL POPREAL8(sfa)
        tempb = sfab/(ampl2-ampl1)
        ampltb = ampltb + tempb
        tempb0 = -((amplt-ampl1)*tempb/(ampl2-ampl1))
        ampl1b = ampl1b - tempb - tempb0
        ampl2b = ampl2b + tempb0
        CALL POPREAL8(amplt_a2)
        CALL POPREAL8(amplt)
        amcritb = amcritb + ampltb
      END IF
      di2_t2b = 0.0_8
      rt2b = 0.0_8
      v2_u2b = 0.0_8
      hs2_reb = 0.0_8
      di2_d2b = 0.0_8
      di2b = 0.0_8
      cq2_reb = 0.0_8
      us2_u2b = 0.0_8
      v2b = 0.0_8
      hc2_u2b = 0.0_8
      hk2b = 0.0_8
      m2_u2b = 0.0_8
      hs2_t2b = 0.0_8
      s2b = 0.0_8
      de2_t2b = 0.0_8
      r2_u2b = 0.0_8
      cf2_u2b = 0.0_8
      cq2_t2b = 0.0_8
      v2_msb = 0.0_8
      hs2_d2b = 0.0_8
      de2_d2b = 0.0_8
      cq2_d2b = 0.0_8
      us2_msb = 0.0_8
      hc2_msb = 0.0_8
      m2_msb = 0.0_8
      m2b = 0.0_8
      di2_u2b = 0.0_8
      r2_msb = 0.0_8
      cf2_msb = 0.0_8
      rt2_reb = 0.0_8
      xtb = 0.0_8
      dw2b = 0.0_8
      u2_ueib = 0.0_8
      hs2_u2b = 0.0_8
      rt2_t2b = 0.0_8
      hk2_t2b = 0.0_8
      de2_u2b = 0.0_8
      cq2_u2b = 0.0_8
      di2_msb = 0.0_8
      hk2_d2b = 0.0_8
      cf2b = 0.0_8
      us2b = 0.0_8
      v2_reb = 0.0_8
      hs2b = 0.0_8
      hs2_msb = 0.0_8
      hc2b = 0.0_8
      de2_msb = 0.0_8
      cq2_msb = 0.0_8
      us2_reb = 0.0_8
      di2_s2b = 0.0_8
      h2b = 0.0_8
      cf2_reb = 0.0_8
      h2_t2b = 0.0_8
      rt2_u2b = 0.0_8
      hk2_u2b = 0.0_8
      us2_t2b = 0.0_8
      hc2_t2b = 0.0_8
      h2_d2b = 0.0_8
      de2b = 0.0_8
      us2_d2b = 0.0_8
      hc2_d2b = 0.0_8
      r2b = 0.0_8
      cf2_t2b = 0.0_8
      di2_reb = 0.0_8
      cf2_d2b = 0.0_8
      cq2b = 0.0_8
      rt2_msb = 0.0_8
      hk2_msb = 0.0_8
      u2_msb = 0.0_8
      hkt_msb = 0.0_8
      dt_a2b = 0.0_8
      ax_a1b = 0.0_8
      ax_rt1b = 0.0_8
      wf2_a1b = 0.0_8
      rtt_ttb = 0.0_8
      hkt_ttb = 0.0_8
      hkt_dtb = 0.0_8
      wf1_a1b = 0.0_8
      ax_hk1b = 0.0_8
      axb = 0.0_8
      xt_a2b = 0.0_8
      wf2_x1b = 0.0_8
      wf2_x2b = 0.0_8
      wf1_x1b = 0.0_8
      wf1_x2b = 0.0_8
      rtt_reb = 0.0_8
      tt_a2b = 0.0_8
      rtt_utb = 0.0_8
      hkt_utb = 0.0_8
      ax_ttb = 0.0_8
      ut_a2b = 0.0_8
      wf1b = 0.0_8
      wf2b = 0.0_8
      ax_atb = 0.0_8
      ax_rttb = 0.0_8
      ax_hktb = 0.0_8
      ax_t1b = 0.0_8
      rtt_msb = 0.0_8
 150 CONTINUE
    CALL POPREAL8(ampl2)
    ampl1b = ampl1b + ampl2b
    axb = axb + (x2-x1)*ampl2b
    x2b = x2b + ax*ampl2b
    x1b = x1b - ax*ampl2b
    ampl2b = 0.0_8
    ax_hk2b = 0.0_8
    ax_t2b = 0.0_8
    ax_rt2b = 0.0_8
    ax_a2b = 0.0_8
    CALL AXSET_BWD(hk1, hk1b, t1, t1b, rt1, rt1b, ampl1, ampl1b, hk2, &
&            hk2b, t2, t2b, rt2, rt2b, ampl2, ampl2b, amcrit, amcritb, &
&            idampv, ax, axb, ax_hk1, ax_hk1b, ax_t1, ax_t1b, ax_rt1, &
&            ax_rt1b, ax_a1, ax_a1b, ax_hk2, ax_hk2b, ax_t2, ax_t2b, &
&            ax_rt2, ax_rt2b, ax_a2, ax_a2b)
    CALL BLC_SAVE2_B()
99001 FORMAT(1x, 'x:', 3f9.5, '  N:', 3f7.3, '  Nx:', f8.3, '   dN:'&
&          , e10.3)
  END SUBROUTINE TRCHEK2_B

!*==TRCHEK2.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
!      SUBROUTINE TRCHEK1
!C-------------------------------------------------
!C     Checks if transition occurs in the current
!C     interval 1..2  (IBL-1...IBL) on side IS.
!C
!C     Old first-order version.
!C
!C     Growth rate is evaluated at the upstream
!C     point "1". The discrete amplification
!C     equation is
!C
!C       Ncrit - N(X1)
!C       -------------  =  N'(X1)
!C          XT - X1
!C
!C     which can be immediately solved for
!C     the transition location XT.
!C-------------------------------------------------
!      INCLUDE 'XBL.INC'
!C
!C---- calculate AMPL2 value
!      CALL AXSET( HK1,    T1,    RT1, AMPL1,
!     &            HK2,    T2,    RT2, AMPL2,  AMCRIT, IDAMPV,
!     &     AX, AX_HK1, AX_T1, AX_RT1, AX_A1,
!     &         AX_HK2, AX_T2, AX_RT2, AX_A2 )
!      AMPL2 = AMPL1 + AX*(X2-X1)
!C
!C---- test for free or forced transition
!      TRFREE = AMPL2.GE.AMCRIT
!      TRFORC = XIFORC.GT.X1 .AND. XIFORC.LE.X2
!C
!C---- set transition interval flag
!      TRAN = TRFORC .OR. TRFREE
!C
!C---- if no transition yet, just return
!      IF(.NOT.TRAN) RETURN
!C
!C---- resolve if both forced and free transition
!      IF(TRFREE .AND. TRFORC) THEN
!       XT = (AMCRIT-AMPL1)/AX  +  X1
!       TRFORC = XIFORC .LT. XT
!       TRFREE = XIFORC .GE. XT
!      ENDIF
!C
!      IF(TRFORC) THEN
!C----- if forced transition, then XT is prescribed
!       XT = XIFORC
!       XT_A1 = 0.
!       XT_X1 = 0.
!       XT_T1 = 0.
!       XT_D1 = 0.
!       XT_U1 = 0.
!       XT_X2 = 0.
!       XT_T2 = 0.
!       XT_D2 = 0.
!       XT_U2 = 0.
!       XT_MS = 0.
!       XT_RE = 0.
!       XT_XF = 1.0
!      ELSE
!C----- if free transition, XT is related to BL variables
!C-     by the amplification equation
!C
!       XT    =  (AMCRIT-AMPL1)/AX     + X1
!       XT_AX = -(AMCRIT-AMPL1)/AX**2
!C
!       XT_A1 = -1.0/AX - (AMCRIT-AMPL1)/AX**2 * AX_A1
!       XT_X1 = 1.0
!       XT_T1 = XT_AX*(AX_HK1*HK1_T1 + AX_T1 + AX_RT1*RT1_T1)
!       XT_D1 = XT_AX*(AX_HK1*HK1_D1                        )
!       XT_U1 = XT_AX*(AX_HK1*HK1_U1         + AX_RT1*RT1_U1)
!       XT_X2 = 0.
!       XT_T2 = 0.
!       XT_D2 = 0.
!       XT_U2 = 0.
!       XT_MS = XT_AX*(AX_HK1*HK1_MS         + AX_RT1*RT1_MS)
!       XT_RE = XT_AX*(                        AX_RT1*RT1_RE)
!       XT_XF = 0.0
!      ENDIF
!C
!      RETURN
!      END
  FUNCTION TRCHEK2()
    USE I_XFOIL_DIFF, ONLY : show_output, abort_on_nan
    USE I_XBL_DIFF
    IMPLICIT NONE
!
    LOGICAL :: trchek2
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: amplt, amplt_a2, amsave, ax, ax_a1, ax_a2, ax_at, ax_d1, &
&   ax_d2, ax_hk1, ax_hk2, ax_hkt, ax_ms, ax_re, ax_rt1, ax_rt2, ax_rtt&
&   , ax_t1, ax_t2, ax_tt, ax_u1, ax_u2, ax_x1, ax_x2, ax_xf, da2, dt, &
&   dt_a1, dt_a2, dt_d1, dt_d2, dt_x1, dt_x2, dt_xf, dxt, hkt, hkt_dt, &
&   hkt_ms, hkt_tt, hkt_ut, res, res_a2, rlx, rtt, rtt_ms, rtt_re, &
&   rtt_tt, rtt_ut, sfa, sfa_a1, sfa_a2, sfx, sfx_x1, sfx_x2, sfx_xf, tt&
&   , tt_a1, tt_a2, tt_t1, tt_t2, tt_x1, tt_x2, tt_xf, ut, ut_a1, ut_a2&
&   , ut_u1, ut_u2, ut_x1, ut_x2, ut_xf, wf1, wf1_a1, wf1_a2, wf1_x1, &
&   wf1_x2, wf1_xf, wf2
    REAL :: wf2_a1, wf2_a2
    REAL, SAVE :: daeps
    INTEGER :: icom, itam
    REAL :: wf2_x1, wf2_x2, wf2_xf, xt_a2, z_a1, z_a2, z_ax, z_d1, z_d2&
&   , z_ms, z_re, z_t1, z_t2, z_u1, z_u2, z_x1, z_x2, z_xf
    REAL :: ampl2r, amcritr, xiforcr, x1r, x2r
    INTRINSIC ABS
    INTRINSIC EPSILON
    REAL :: abs0
    REAL :: abs1
    REAL :: abs2
    REAL :: abs3
    REAL :: abs4
    REAL :: result1
    REAL :: result2
    REAL :: result3
    REAL :: result4
    REAL :: result5
    REAL :: result6
    REAL :: result7
    REAL :: result8
    REAL :: result9
    REAL :: result10
    REAL :: result11
    REAL :: result12
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!----------------------------------------------------------------
!     New second-order version:  December 1994.
!
!     Checks if transition occurs in the current interval X1..X2.
!     If transition occurs, then set transition location XT, and
!     its sensitivities to "1" and "2" variables.  If no transition,
!     set amplification AMPL2.
!
!
!     Solves the implicit amplification equation for N2:
!
!       N2 - N1     N'(XT,NT) + N'(X1,N1)
!       -------  =  ---------------------
!       X2 - X1               2
!
!     In effect, a 2-point central difference is used between
!     X1..X2 (no transition), or X1..XT (transition).  The switch
!     is done by defining XT,NT in the equation above depending
!     on whether N2 exceeds Ncrit.
!
!  If N2<Ncrit:  NT=N2    , XT=X2                  (no transition)
!
!  If N2>Ncrit:  NT=Ncrit , XT=(Ncrit-N1)/(N2-N1)  (transition)
!
!
!----------------------------------------------------------------
    DATA daeps /5.0e-5/
!CC   DATA DAEPS / 1.0D-12 /
    trchek2 = .true.
!
!---- save variables and sensitivities at IBL ("2") for future restoration
    CALL BLC_SAVE2()
!
!---- calculate average amplification rate AX over X1..X2 interval
    CALL AXSET(hk1, t1, rt1, ampl1, hk2, t2, rt2, ampl2, amcrit, idampv&
&        , ax, ax_hk1, ax_t1, ax_rt1, ax_a1, ax_hk2, ax_t2, ax_rt2, &
&        ax_a2)
!
!---- set initial guess for iterate N2 (AMPL2) at X2
    ampl2 = ampl1 + ax*(x2-x1)
!
!---- solve implicit system for amplification AMPL2
    DO itam=1,30
!
!---- define weighting factors WF1,WF2 for defining "T" quantities from 1,2
!
      ampl2r = ampl2
      amcritr = amcrit
! if (AMPl2<=AMCrit) then
      IF (ampl2r .LE. amcritr) THEN
!------ there is no transition yet,  "T" is the same as "2"
        amplt = ampl2
        amplt_a2 = 1.0
        sfa = 1.0
        sfa_a1 = 0.
        sfa_a2 = 0.
      ELSE
!------ there is transition in X1..X2, "T" is set from N1, N2
        amplt = amcrit
        amplt_a2 = 0.
        sfa = (amplt-ampl1)/(ampl2-ampl1)
        sfa_a1 = (sfa-1.0)/(ampl2-ampl1)
        sfa_a2 = (-sfa)/(ampl2-ampl1)
      END IF
!
      xiforcr = xiforc
      x2r = x2
! if (XIForc<X2) then
      IF (xiforcr .LT. x2r) THEN
        sfx = (xiforc-x1)/(x2-x1)
        sfx_x1 = (sfx-1.0)/(x2-x1)
        sfx_x2 = (-sfx)/(x2-x1)
        sfx_xf = 1.0/(x2-x1)
      ELSE
        sfx = 1.0
        sfx_x1 = 0.
        sfx_x2 = 0.
        sfx_xf = 0.
      END IF
!
!---- set weighting factor from free or forced transition
      IF (sfa .LT. sfx) THEN
        wf2 = sfa
        wf2_a1 = sfa_a1
        wf2_a2 = sfa_a2
        wf2_x1 = 0.
        wf2_x2 = 0.
        wf2_xf = 0.
      ELSE
        wf2 = sfx
        wf2_a1 = 0.
        wf2_a2 = 0.
        wf2_x1 = sfx_x1
        wf2_x2 = sfx_x2
        wf2_xf = sfx_xf
      END IF
!
!
!=====================
!C---- 1st-order (based on "1" quantites only, for testing)
!      WF2    = 0.0
!      WF2_A1 = 0.0
!      WF2_A2 = 0.0
!      WF2_X1 = 0.0
!      WF2_X2 = 0.0
!      WF2_XF = 0.0
!=====================
!
      wf1 = 1.0 - wf2
      wf1_a1 = -wf2_a1
      wf1_a2 = -wf2_a2
      wf1_x1 = -wf2_x1
      wf1_x2 = -wf2_x2
      wf1_xf = -wf2_xf
!
!---- interpolate BL variables to XT
      xt = x1*wf1 + x2*wf2
      tt = t1*wf1 + t2*wf2
      dt = d1*wf1 + d2*wf2
      ut = u1*wf1 + u2*wf2
!
      xt_a2 = x1*wf1_a2 + x2*wf2_a2
      tt_a2 = t1*wf1_a2 + t2*wf2_a2
      dt_a2 = d1*wf1_a2 + d2*wf2_a2
      ut_a2 = u1*wf1_a2 + u2*wf2_a2
!
!---- temporarily set "2" variables from "T" for BLKIN
      x2 = xt
      t2 = tt
      d2 = dt
      u2 = ut
!
!---- calculate laminar secondary "T" variables HKT, RTT
      CALL BLKIN()
!
      hkt = hk2
      hkt_tt = hk2_t2
      hkt_dt = hk2_d2
      hkt_ut = hk2_u2
      hkt_ms = hk2_ms
!
      rtt = rt2
      rtt_tt = rt2_t2
      rtt_ut = rt2_u2
      rtt_ms = rt2_ms
      rtt_re = rt2_re
!
!---- restore clobbered "2" variables, except for AMPL2
      amsave = ampl2
      CALL BLC_RESTORE2()
      ampl2 = amsave
!
!---- calculate amplification rate AX over current X1-XT interval
      CALL AXSET(hk1, t1, rt1, ampl1, hkt, tt, rtt, amplt, amcrit, &
&          idampv, ax, ax_hk1, ax_t1, ax_rt1, ax_a1, ax_hkt, ax_tt, &
&          ax_rtt, ax_at)
!
!---- punch out early if there is no amplification here
      IF (ax .LE. 0.0) THEN
        GOTO 100
      ELSE
!
!---- set sensitivity of AX(A2)
        ax_a2 = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_a2 + ax_hkt*&
&         hkt_dt*dt_a2 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_a2 + ax_at*&
&         amplt_a2
!
!---- residual for implicit AMPL2 definition (amplification equation)
        res = ampl2 - ampl1 - ax*(x2-x1)
        res_a2 = 1.0 - ax_a2*(x2-x1)
!
        da2 = -(res/res_a2)
!
        rlx = 1.0
        dxt = xt_a2*da2
        IF (dxt/(x2-x1) .GE. 0.) THEN
          abs0 = dxt/(x2-x1)
        ELSE
          abs0 = -(dxt/(x2-x1))
        END IF
!
        IF (rlx*abs0 .GT. 0.05) THEN
          IF ((x2-x1)/dxt .GE. 0.) THEN
            abs1 = (x2-x1)/dxt
          ELSE
            abs1 = -((x2-x1)/dxt)
          END IF
          rlx = 0.05*abs1
        END IF
        IF (da2 .GE. 0.) THEN
          abs2 = da2
        ELSE
          abs2 = -da2
        END IF
        IF (rlx*abs2 .GT. 1.0) THEN
          IF (1.0/da2 .GE. 0.) THEN
            abs3 = 1.0/da2
          ELSE
            abs3 = -(1.0/da2)
          END IF
          rlx = 1.0*abs3
        END IF
        IF (da2 .GE. 0.) THEN
          abs4 = da2
        ELSE
          abs4 = -da2
        END IF
!
!---- check if converged
        IF (abs4 .LT. daeps) THEN
          GOTO 100
        ELSE
!
          ampl2r = ampl2
          amcritr = amcrit
! if ((AMPl2>AMCrit .and. AMPl2 + rlx * da2<AMCrit) .or. (AMPl2<AMCrit .and. AMPl2 + rlx * da2>AMCrit)) then
          IF ((ampl2r .GT. amcritr .AND. ampl2r + rlx*da2 .LT. amcritr) &
&             .OR. (ampl2r .LT. amcritr .AND. ampl2r + rlx*da2 .GT. &
&             amcritr)) THEN
!------ limited Newton step so AMPL2 doesn't step across AMCRIT either way
            ampl2 = amcrit
          ELSE
!------ regular Newton step
            ampl2 = ampl2 + rlx*da2
          END IF
        END IF
      END IF
    END DO
!
    IF (show_output) THEN
      WRITE(*, *) 'TRCHEK2: N2 convergence failed.'
      WRITE(*, 99001) x1, xt, x2, ampl1, amplt, ampl2, ax, da2
    END IF
! Check if ANY of these printed variables contain NaN's. If they do, convergence will never be reached.
! if (X1 /= X1 .or. XT /= XT .or. X2 /= X2 .or. AMPl1 /= AMPl1 .or. &
! amplt /= amplt .or. AMPl2 /= AMPl2 .or. ax /= ax .or. da2 /= da2) then
! trchek2 = .false.
! if (abort_on_nan) return
! end if
    x1r = x1
    x2r = x2
    result1 = EPSILON(x1r)
    result2 = EPSILON(x1r)
    result3 = EPSILON(xt)
    result4 = EPSILON(xt)
    result5 = EPSILON(x2r)
    result6 = EPSILON(x2r)
    result7 = EPSILON(amplt)
    result8 = EPSILON(amplt)
    result9 = EPSILON(ax)
    result10 = EPSILON(ax)
    result11 = EPSILON(da2)
    result12 = EPSILON(da2)
    IF ((((((((.NOT.(x1r .GE. x1r - result1 .AND. x1r .LE. x1r + result2&
&       )) .OR. (.NOT.(xt .GE. xt - result3 .AND. xt .LE. xt + result4))&
&       ) .OR. (.NOT.(x2r .GE. x2r - result5 .AND. x2r .LE. x2r + &
&       result6))) .OR. ampl1 .NE. ampl1) .OR. (.NOT.(amplt .GE. amplt -&
&       result7 .AND. amplt .LE. amplt + result8))) .OR. ampl2 .NE. &
&       ampl2) .OR. (.NOT.(ax .GE. ax - result9 .AND. ax .LE. ax + &
&       result10))) .OR. (.NOT.(da2 .GE. da2 - result11 .AND. da2 .LE. &
&       da2 + result12))) THEN
! TAPENADE: (TC19) Equality test on reals is not reliable
! TAPENADE: (TC19) Equality test on reals is not reliable
      trchek2 = .false.
      IF (abort_on_nan) RETURN
    END IF
! 
!
!
!
!---- test for free or forced transition
! 100  TRFree = AMPl2>=AMCrit
    ampl2r = ampl2
    amcritr = amcrit
 100 IF (ampl2r .GE. amcritr) THEN
      trfree = .true.
    ELSE
      trfree = .false.
    END IF
    xiforcr = xiforc
    x1r = x1
    x2r = x2
! TRForc = XIForc>X1 .and. XIForc<=X2
    trforc = xiforcr .GT. x1r .AND. xiforcr .LE. x2r
!
!---- set transition interval flag
    tran = trforc .OR. trfree
!
    IF (abort_on_nan .AND. (.NOT.tran)) THEN
      RETURN
    ELSE
!
!---- resolve if both forced and free transition
      IF (trfree .AND. trforc) THEN
        trforc = xiforc .LT. xt
        trfree = xiforc .GE. xt
      END IF
!
      IF (trforc) THEN
!----- if forced transition, then XT is prescribed,
!-     no sense calculating the sensitivities, since we know them...
        xt = xiforc
        xt_a1 = 0.
        xt_x1 = 0.
        xt_t1 = 0.
        xt_d1 = 0.
        xt_u1 = 0.
        xt_x2 = 0.
        xt_t2 = 0.
        xt_d2 = 0.
        xt_u2 = 0.
        xt_ms = 0.
        xt_re = 0.
        xt_xf = 1.0
        RETURN
      ELSE
!
!---- free transition ... set sensitivities of XT
!
!---- XT( X1 X2 A1 A2 XF ),  TT( T1 T2 A1 A2 X1 X2 XF),   DT( ...
!C    XT    = X1*WF1    + X2*WF2
!C    TT    = T1*WF1    + T2*WF2
!C    DT    = D1*WF1    + D2*WF2
!C    UT    = U1*WF1    + U2*WF2
!
        xt_x1 = wf1
        tt_t1 = wf1
        dt_d1 = wf1
        ut_u1 = wf1
!
        xt_x2 = wf2
        tt_t2 = wf2
        dt_d2 = wf2
        ut_u2 = wf2
!
        xt_a1 = x1*wf1_a1 + x2*wf2_a1
        tt_a1 = t1*wf1_a1 + t2*wf2_a1
        dt_a1 = d1*wf1_a1 + d2*wf2_a1
        ut_a1 = u1*wf1_a1 + u2*wf2_a1
!
!C    XT_A2 = X1*WF1_A2 + X2*WF2_A2
!C    TT_A2 = T1*WF1_A2 + T2*WF2_A2
!C    DT_A2 = D1*WF1_A2 + D2*WF2_A2
!C    UT_A2 = U1*WF1_A2 + U2*WF2_A2
!
        xt_x1 = x1*wf1_x1 + x2*wf2_x1 + xt_x1
        tt_x1 = t1*wf1_x1 + t2*wf2_x1
        dt_x1 = d1*wf1_x1 + d2*wf2_x1
        ut_x1 = u1*wf1_x1 + u2*wf2_x1
!
        xt_x2 = x1*wf1_x2 + x2*wf2_x2 + xt_x2
        tt_x2 = t1*wf1_x2 + t2*wf2_x2
        dt_x2 = d1*wf1_x2 + d2*wf2_x2
        ut_x2 = u1*wf1_x2 + u2*wf2_x2
!
        xt_xf = x1*wf1_xf + x2*wf2_xf
        tt_xf = t1*wf1_xf + t2*wf2_xf
        dt_xf = d1*wf1_xf + d2*wf2_xf
        ut_xf = u1*wf1_xf + u2*wf2_xf
!
!---- at this point, AX = AX( HK1, T1, RT1, A1, HKT, TT, RTT, AT )
!
!---- set sensitivities of AX( T1 D1 U1 A1 T2 D2 U2 A2 MS RE )
        ax_t1 = ax_hk1*hk1_t1 + ax_t1 + ax_rt1*rt1_t1 + (ax_hkt*hkt_tt+&
&         ax_tt+ax_rtt*rtt_tt)*tt_t1
        ax_d1 = ax_hk1*hk1_d1 + ax_hkt*hkt_dt*dt_d1
        ax_u1 = ax_hk1*hk1_u1 + ax_rt1*rt1_u1 + (ax_hkt*hkt_ut+ax_rtt*&
&         rtt_ut)*ut_u1
        ax_a1 = ax_a1 + (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_a1 + &
&         ax_hkt*hkt_dt*dt_a1 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_a1
        ax_x1 = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_x1 + ax_hkt*&
&         hkt_dt*dt_x1 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_x1
!
        ax_t2 = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_t2
        ax_d2 = ax_hkt*hkt_dt*dt_d2
        ax_u2 = (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_u2
        ax_a2 = ax_at*amplt_a2 + (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*&
&         tt_a2 + ax_hkt*hkt_dt*dt_a2 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*&
&         ut_a2
        ax_x2 = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_x2 + ax_hkt*&
&         hkt_dt*dt_x2 + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_x2
!
        ax_xf = (ax_hkt*hkt_tt+ax_tt+ax_rtt*rtt_tt)*tt_xf + ax_hkt*&
&         hkt_dt*dt_xf + (ax_hkt*hkt_ut+ax_rtt*rtt_ut)*ut_xf
!
        ax_ms = ax_hkt*hkt_ms + ax_rtt*rtt_ms + ax_hk1*hk1_ms + ax_rt1*&
&         rt1_ms
        ax_re = ax_rtt*rtt_re + ax_rt1*rt1_re
!
!
!---- set sensitivities of residual RES
!CC   RES  = AMPL2 - AMPL1 - AX*(X2-X1)
        z_ax = -(x2-x1)
!
        z_a1 = z_ax*ax_a1 - 1.0
        z_t1 = z_ax*ax_t1
        z_d1 = z_ax*ax_d1
        z_u1 = z_ax*ax_u1
        z_x1 = z_ax*ax_x1 + ax
!
        z_a2 = z_ax*ax_a2 + 1.0
        z_t2 = z_ax*ax_t2
        z_d2 = z_ax*ax_d2
        z_u2 = z_ax*ax_u2
        z_x2 = z_ax*ax_x2 - ax
!
        z_xf = z_ax*ax_xf
        z_ms = z_ax*ax_ms
        z_re = z_ax*ax_re
!
!---- set sensitivities of XT, with RES being stationary for A2 constraint
        xt_a1 = xt_a1 - xt_a2/z_a2*z_a1
        xt_t1 = -(xt_a2/z_a2*z_t1)
        xt_d1 = -(xt_a2/z_a2*z_d1)
        xt_u1 = -(xt_a2/z_a2*z_u1)
        xt_x1 = xt_x1 - xt_a2/z_a2*z_x1
        xt_t2 = -(xt_a2/z_a2*z_t2)
        xt_d2 = -(xt_a2/z_a2*z_d2)
        xt_u2 = -(xt_a2/z_a2*z_u2)
        xt_x2 = xt_x2 - xt_a2/z_a2*z_x2
        xt_ms = -(xt_a2/z_a2*z_ms)
        xt_re = -(xt_a2/z_a2*z_re)
        xt_xf = 0.0
      END IF
    END IF
99001 FORMAT(1x, 'x:', 3f9.5, '  N:', 3f7.3, '  Nx:', f8.3, '   dN:'&
&          , e10.3)
  END FUNCTION TRCHEK2

!  Differentiation of blsys in reverse (adjoint) mode (with options split(ABCOPY APCALC GGCALC NCALC PSILIN PSILIN_XW PSWLIN QDCA
!LC QWCALC SCALC SEGSPL XYWAKE TECALC SPLIND SEVAL DEVAL D2VAL SINVRT LEFIND VISCAL SPECAL SPECCL MRCL COMSET CLCALC CDCALC CPCAL
!C QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFile):
!   gradient     of useful results: di2_t2 rt2 v2_u2 rt1_ms hk1_ms
!                hs2_re di1 di2_d2 di2 u1_ms xt_re cq2_re v1 di1_t1
!                us2_u2 v1_u1 v2 hc2_u2 hk1 hk2 m2_u2 hstinv reybl
!                di1_d1 hs1_re vs1 vs2 hs2_t2 s1 cq1_re s2 xt_t1
!                de2_t2 r2_u2 us1_u1 xt_t2 cf2_u2 cq2_t2 hc1_u1
!                v2_ms hs2_d2 u1_uei m1_u1 xt_d1 de2_d2 xt_d2 cq2_d2
!                hs1_t1 de1_t1 r1_u1 cf1_u1 cq1_t1 us2_ms hc2_ms
!                hs1_d1 v1_ms xt_a1 de1_d1 m1 m2_ms cq1_d1 m2 reybl_re
!                di2_u2 r2_ms cf2_ms rt2_re us1_ms hc1_ms xt m1_ms
!                dw1 di1_u1 dw2 u2_uei xt_x1 xt_x2 r1_ms cf1_ms
!                rt1_re hs2_u2 rt2_t2 t1 hk2_t2 t2 xt_u1 de2_u2
!                xt_u2 cq2_u2 di2_ms d1 cf1 d2 hk2_d2 vsrez cf2
!                us1 us2 hs1_u1 rt1_t1 hk1_t1 de1_u1 cq1_u1 di1_ms
!                hk1_d1 hs1 v2_re hs2 hc1 hs2_ms hc2 de2_ms xt_ms
!                cq2_ms us2_re v1_re di2_s2 c2sav x1 x2 hs1_ms
!                vsm hstinv_ms de1_ms h1 amcrit cq1_ms h2 cf2_re
!                h2_t2 us1_re rt2_u2 u1 di1_s1 hk2_u2 u2 us2_t2
!                vsr hc2_t2 c1sav h2_d2 rstbl_ms de1 rstbl de2
!                us2_d2 hc2_d2 h1_t1 r1 vsx cf1_re r2 rt1_u1 ampl1
!                hk1_u1 us1_t1 ampl2 cf2_t2 hc1_t1 h1_d1 reybl_ms
!                di2_re us1_d1 cf2_d2 hc1_d1 cq1 cq2 rt2_ms cf1_t1
!                hk2_ms u2_ms cf1_d1 di1_re rt1
