!C QISET QVFUE GAMQV STFIND STMOVE UICALC XICALC AXSET ATANC SETEXP TRISOL GAUSS BLSOLV BAKSUB) r8 messagesInFile):
!   gradient     of useful results: rt2 v2_u2 v2 hk2 m2_u2 hstinv
!                reybl r2_u2 v2_ms m2_ms m2 reybl_re r2_ms rt2_re
!                rt2_t2 hk2_t2 t2 d2 hk2_d2 v2_re hstinv_ms h2
!                h2_t2 rt2_u2 hk2_u2 u2 h2_d2 rstbl_ms rstbl r2
!                reybl_ms rt2_ms hk2_ms
!   with respect to varying inputs: hstinv reybl reybl_re t2 d2
!                hstinv_ms u2 rstbl_ms rstbl reybl_ms
!*==BLKIN.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
! BLPRV
  SUBROUTINE BLKIN_B()
!----------------------------------------------------------
!     Calculates turbulence-independent secondary "2"
!     variables from the primary "2" variables.
!----------------------------------------------------------
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: herat, he_ms, he_u2, hk2_h2, hk2_m2, tr2, v2_he
    REAL :: heratb, he_msb, he_u2b, hk2_h2b, hk2_m2b, tr2b, v2_heb
    INTRINSIC SQRT
    REAL :: temp
    REAL :: temp0
    REAL :: tempb
    REAL :: temp1
    REAL :: tempb0
    REAL :: tempb1
    REAL :: temp2
    REAL :: tempb2
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
!---- set edge Mach number ** 2
    CALL PUSHREAL8(m2)
    m2 = u2*u2*hstinv/(gm1bl*(1.0-0.5*u2*u2*hstinv))
    tr2 = 1.0 + 0.5*gm1bl*m2
    CALL PUSHREAL8(m2_u2)
    m2_u2 = 2.0*m2*tr2/u2
    CALL PUSHREAL8(m2_ms)
    m2_ms = u2*u2*tr2/(gm1bl*(1.0-0.5*u2*u2*hstinv))*hstinv_ms
!
!---- set edge static density (isentropic relation)
    CALL PUSHREAL8(r2)
    r2 = rstbl*tr2**(-(1.0/gm1bl))
    r2_u2 = -(r2/tr2*0.5*m2_u2)
    r2_ms = -(r2/tr2*0.5*m2_ms) + rstbl_ms*tr2**(-(1.0/gm1bl))
!
!---- set shape parameter
    CALL PUSHREAL8(h2)
    h2 = d2/t2
    CALL PUSHREAL8(h2_d2)
    h2_d2 = 1.0/t2
    CALL PUSHREAL8(h2_t2)
    h2_t2 = -(h2/t2)
!
!---- set edge static/stagnation enthalpy
    herat = 1.0 - 0.5*u2*u2*hstinv
    he_u2 = -(u2*hstinv)
    he_ms = -(0.5*u2*u2*hstinv_ms)
!
!---- set molecular viscosity
    v2 = SQRT(herat**3)*(1.0+hvrat)/(herat+hvrat)/reybl
    v2_he = v2*(1.5/herat-1.0/(herat+hvrat))
!
    v2_u2 = v2_he*he_u2
    v2_ms = -(v2/reybl*reybl_ms) + v2_he*he_ms
    v2_re = -(v2/reybl*reybl_re)
!
!---- set kinematic shape parameter
    CALL PUSHREAL8(hk2)
    CALL HKIN(h2, m2, hk2, hk2_h2, hk2_m2)
!
!
!---- set momentum thickness Reynolds number
    CALL PUSHREAL8(rt2)
    rt2 = r2*u2*t2/v2
    temp2 = t2/v2
    tempb2 = -(rt2_reb/v2)
    rt2b = rt2b + v2_re*tempb2 + (r2_ms/r2-v2_ms/v2)*rt2_msb + rt2_t2b/&
&     t2 + (1.0/u2+r2_u2/r2-v2_u2/v2)*rt2_u2b
    v2_reb = v2_reb + rt2*tempb2
    v2b = v2b - rt2*v2_re*tempb2/v2
    tempb2 = rt2*rt2_msb
    r2_msb = r2_msb + tempb2/r2
    r2b = r2b - r2_ms*tempb2/r2**2
    v2_msb = v2_msb - tempb2/v2
    v2b = v2b + v2_ms*tempb2/v2**2
    tempb2 = rt2*rt2_u2b
    u2b = u2b + r2*temp2*rt2b - tempb2/u2**2
    r2_u2b = r2_u2b + tempb2/r2
    r2b = r2b + u2*temp2*rt2b - r2_u2*tempb2/r2**2
    v2_u2b = v2_u2b - tempb2/v2
    v2b = v2b + v2_u2*tempb2/v2**2
    tempb2 = r2*u2*rt2b/v2
    t2b = t2b + tempb2 - rt2*rt2_t2b/t2**2
    CALL POPREAL8(rt2)
    v2b = v2b - temp2*tempb2
    hk2_m2b = m2_ms*hk2_msb + m2_u2*hk2_u2b
    hk2_h2b = h2_d2*hk2_d2b + h2_t2*hk2_t2b
    h2_d2b = h2_d2b + hk2_h2*hk2_d2b
    h2_t2b = h2_t2b + hk2_h2*hk2_t2b
    CALL POPREAL8(hk2)
    tempb2 = -(v2_reb/reybl)
    v2b = v2b + reybl_re*tempb2
    reybl_reb = reybl_reb + v2*tempb2
    reyblb = reyblb - v2*reybl_re*tempb2/reybl
    v2_heb = he_ms*v2_msb + he_u2*v2_u2b
    he_msb = v2_he*v2_msb
    tempb2 = -(v2_msb/reybl)
    reybl_msb = reybl_msb + v2*tempb2
    reyblb = reyblb - v2*reybl_ms*tempb2/reybl
    he_u2b = v2_he*v2_u2b
    temp2 = 1.0/(hvrat+herat)
    v2b = v2b + reybl_ms*tempb2 + (1.5/herat-temp2)*v2_heb
    temp1 = herat*herat*herat
    temp0 = SQRT(temp1)
    tempb2 = (hvrat+1.0)*v2b/((hvrat+herat)*reybl)
    tempb1 = -(temp0*tempb2/((hvrat+herat)*reybl))
    IF (temp1 .EQ. 0.0_8) THEN
      heratb = (temp2*v2/(hvrat+herat)-1.5*v2/herat**2)*v2_heb + reybl*&
&       tempb1
    ELSE
      heratb = (temp2*v2/(hvrat+herat)-1.5*v2/herat**2)*v2_heb + 3*herat&
&       **2*tempb2/(2.0*temp0) + reybl*tempb1
    END IF
    reyblb = reyblb + (hvrat+herat)*tempb1
    temp2 = -(1.0/gm1bl)
    rstbl_msb = rstbl_msb + tr2**temp2*r2_msb
    tempb0 = -(0.5*r2_msb/tr2)
    m2_msb = m2_msb + hk2_m2*hk2_msb + r2*tempb0
    IF (tr2 .LE. 0.0_8 .AND. (temp2 .EQ. 0.0_8 .OR. temp2 .NE. INT(temp2&
&       ))) THEN
      tr2b = -(r2*m2_ms*tempb0/tr2)
    ELSE
      tr2b = temp2*tr2**(temp2-1)*rstbl_ms*r2_msb - r2*m2_ms*tempb0/tr2
    END IF
    tempb2 = -(0.5*r2_u2b/tr2)
    m2_u2b = m2_u2b + hk2_m2*hk2_u2b + r2*tempb2
    CALL HKIN_B(h2, h2b, m2, m2b, hk2, hk2b, hk2_h2, hk2_h2b, hk2_m2, &
&         hk2_m2b)
    CALL POPREAL8(h2_t2)
    h2b = h2b - h2_t2b/t2
    t2b = t2b + h2*h2_t2b/t2**2 - h2_d2b/t2**2 - d2*h2b/t2**2
    CALL POPREAL8(h2_d2)
    CALL POPREAL8(h2)
    d2b = d2b + h2b/t2
    r2b = r2b + m2_ms*tempb0 + m2_u2*tempb2
    temp2 = -(1.0/gm1bl)
    rstblb = rstblb + tr2**temp2*r2b
    temp1 = gm1bl*(-(0.5*(u2*u2)*hstinv)+1.0)
    tempb = m2_msb/temp1
    tempb1 = u2**2*tempb
    hstinv_msb = hstinv_msb + tr2*tempb1 - u2**2*0.5*he_msb
    tempb0 = 2.0*m2_u2b/u2
    IF (tr2 .LE. 0.0_8 .AND. (temp2 .EQ. 0.0_8 .OR. temp2 .NE. INT(temp2&
&       ))) THEN
      tr2b = tr2b + hstinv_ms*tempb1 - r2*m2_u2*tempb2/tr2 + m2*tempb0
    ELSE
      tr2b = tr2b + temp2*tr2**(temp2-1)*rstbl*r2b - r2*m2_u2*tempb2/tr2&
&       + hstinv_ms*tempb1 + m2*tempb0
    END IF
    CALL POPREAL8(r2)
    CALL POPREAL8(m2_ms)
    tempb2 = 0.5*gm1bl*u2**2*tr2*hstinv_ms*tempb/temp1
    u2b = u2b + 2*u2*tr2*hstinv_ms*tempb - 2*u2*hstinv_ms*0.5*he_msb - &
&     hstinv*he_u2b - 2*u2*hstinv*0.5*heratb + 2*u2*hstinv*tempb2 - m2*&
&     tr2*tempb0/u2
    CALL POPREAL8(m2_u2)
    m2b = m2b + tr2*tempb0 + gm1bl*0.5*tr2b
    CALL POPREAL8(m2)
    temp = gm1bl*(-(0.5*(u2*u2)*hstinv)+1.0)
    tempb = m2b/temp
    tempb0 = 0.5*gm1bl*u2**2*hstinv*tempb/temp
    hstinvb = hstinvb + u2**2*tempb2 - u2*he_u2b - u2**2*0.5*heratb + u2&
&     **2*tempb + u2**2*tempb0
    u2b = u2b + 2*u2*hstinv*tempb + 2*u2*hstinv*tempb0
  END SUBROUTINE BLKIN_B

!*==BLKIN.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
! BLPRV
  SUBROUTINE BLKIN()
!----------------------------------------------------------
!     Calculates turbulence-independent secondary "2"
!     variables from the primary "2" variables.
!----------------------------------------------------------
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
    REAL :: herat, he_ms, he_u2, hk2_h2, hk2_m2, tr2, v2_he
    INTRINSIC SQRT
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
!---- set edge Mach number ** 2
    m2 = u2*u2*hstinv/(gm1bl*(1.0-0.5*u2*u2*hstinv))
    tr2 = 1.0 + 0.5*gm1bl*m2
    m2_u2 = 2.0*m2*tr2/u2
    m2_ms = u2*u2*tr2/(gm1bl*(1.0-0.5*u2*u2*hstinv))*hstinv_ms
!
!---- set edge static density (isentropic relation)
    r2 = rstbl*tr2**(-(1.0/gm1bl))
    r2_u2 = -(r2/tr2*0.5*m2_u2)
    r2_ms = -(r2/tr2*0.5*m2_ms) + rstbl_ms*tr2**(-(1.0/gm1bl))
!
!---- set shape parameter
    h2 = d2/t2
    h2_d2 = 1.0/t2
    h2_t2 = -(h2/t2)
!
!---- set edge static/stagnation enthalpy
    herat = 1.0 - 0.5*u2*u2*hstinv
    he_u2 = -(u2*hstinv)
    he_ms = -(0.5*u2*u2*hstinv_ms)
!
!---- set molecular viscosity
    v2 = SQRT(herat**3)*(1.0+hvrat)/(herat+hvrat)/reybl
    v2_he = v2*(1.5/herat-1.0/(herat+hvrat))
!
    v2_u2 = v2_he*he_u2
    v2_ms = -(v2/reybl*reybl_ms) + v2_he*he_ms
    v2_re = -(v2/reybl*reybl_re)
!
!---- set kinematic shape parameter
    CALL HKIN(h2, m2, hk2, hk2_h2, hk2_m2)
!
    hk2_u2 = hk2_m2*m2_u2
    hk2_t2 = hk2_h2*h2_t2
    hk2_d2 = hk2_h2*h2_d2
    hk2_ms = hk2_m2*m2_ms
!
!---- set momentum thickness Reynolds number
    rt2 = r2*u2*t2/v2
    rt2_u2 = rt2*(1.0/u2+r2_u2/r2-v2_u2/v2)
    rt2_t2 = rt2/t2
    rt2_ms = rt2*(r2_ms/r2-v2_ms/v2)
    rt2_re = rt2*(-(v2_re/v2))
  END SUBROUTINE BLKIN

