!*==BLVAR.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
! BLKIN
  SUBROUTINE BLVAR_B(ityp)
!----------------------------------------------------
!     Calculates all secondary "2" variables from
!     the primary "2" variables X2, U2, T2, D2, S2.
!     Also calculates the sensitivities of the
!     secondary variables wrt the primary variables.
!
!      ITYP = 1 :  laminar
!      ITYP = 2 :  turbulent
!      ITYP = 3 :  turbulent wake
!----------------------------------------------------
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    INTEGER :: ityp
! intent (in) Ityp
!
! Local variables
!
    REAL :: cf2l, cf2l_hk2, cf2l_m2, cf2l_rt2, cf2t, cf2t_d2, cf2t_hk2, &
&   cf2t_m2, cf2t_ms, cf2t_re, cf2t_rt2, cf2t_t2, cf2t_u2, cf2_hk2, &
&   cf2_m2, cf2_rt2, cq2_h2, cq2_hk2, cq2_hs2, cq2_rt2, cq2_us2, dd, &
&   dd_hs2, dd_rt2, dd_s2, dd_us2, de2_hk2, dfac, df_fl, df_hk2, df_rt2&
&   , di2l, di2l_hk2, di2l_rt2, di2_cf2t, di2_hk2, di2_hs2, di2_rt2, &
&   di2_us2, fl, fl_hk2, fl_rt2, gcc, grt, hc2_hk2, hc2_m2, hdmax, hkb, &
&   hkc, hkc_hk2, hkc_rt2, hmin, hm_rt2, hs2_hk2, hs2_m2, hs2_rt2, tfl, &
&   us2_h2, us2_hk2, us2_hs2, usb
    REAL :: cf2lb, cf2l_hk2b, cf2l_rt2b, cf2tb, cf2t_d2b, cf2t_hk2b, &
&   cf2t_m2b, cf2t_msb, cf2t_reb, cf2t_rt2b, cf2t_t2b, cf2t_u2b, &
&   cf2_hk2b, cf2_m2b, cf2_rt2b, cq2_h2b, cq2_hk2b, cq2_hs2b, cq2_rt2b, &
&   cq2_us2b, ddb, dd_hs2b, dd_rt2b, dd_s2b, dd_us2b, de2_hk2b, dfacb, &
&   df_flb, df_hk2b, df_rt2b, di2lb, di2l_hk2b, di2l_rt2b, di2_cf2tb, &
&   di2_hk2b, di2_hs2b, di2_rt2b, di2_us2b, flb, fl_hk2b, fl_rt2b, grtb&
&   , hc2_hk2b, hc2_m2b, hkbb, hkcb, hkc_rt2b, hminb, hm_rt2b, hs2_hk2b&
&   , hs2_m2b, hs2_rt2b, tflb, us2_h2b, us2_hk2b, us2_hs2b, usbb
    REAL :: us2r, cf2r, di2r, de2r, t2r
    INTRINSIC MAX
    INTRINSIC SQRT
    INTRINSIC LOG
    INTRINSIC TANH
    REAL :: temp
    REAL :: tempb
    REAL :: temp0
    REAL :: tempb0
    REAL :: temp1
    REAL :: tempb1
    REAL :: temp2
    REAL :: tempb2
    REAL :: temp3
    REAL :: tempb3
    REAL :: temp4
    REAL :: tempb4
    REAL :: tempb5
    REAL :: tempb6
    REAL :: tempb7
    REAL :: temp5
    REAL :: temp6
    REAL :: temp7
    REAL :: tempb8
    REAL :: temp8
    REAL :: tempb9
    REAL :: tempb10
    REAL :: tempb11
    INTEGER :: branch
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
    IF (ityp .EQ. 3) THEN
      IF (hk2 .LT. 1.00005) THEN
        CALL PUSHREAL8(hk2)
        hk2 = 1.00005
        CALL PUSHCONTROL2B(2)
      ELSE
        CALL PUSHREAL8(hk2)
        hk2 = hk2
        CALL PUSHCONTROL2B(1)
      END IF
    ELSE
      CALL PUSHCONTROL2B(0)
    END IF
    IF (ityp .NE. 3) THEN
      IF (hk2 .LT. 1.05000) THEN
        CALL PUSHREAL8(hk2)
        hk2 = 1.05000
        CALL PUSHCONTROL2B(2)
      ELSE
        CALL PUSHREAL8(hk2)
        hk2 = hk2
        CALL PUSHCONTROL2B(1)
      END IF
    ELSE
      CALL PUSHCONTROL2B(0)
    END IF
!
!---- density thickness shape parameter     ( H** )
    CALL PUSHREAL8(hc2)
    CALL HCT(hk2, m2, hc2, hc2_hk2, hc2_m2)
!
!---- set KE thickness shape parameter from  H - H*  correlations
    IF (ityp .EQ. 1) THEN
      CALL PUSHREAL8(hs2)
      CALL HSL(hk2, rt2, m2, hs2, hs2_hk2, hs2_rt2, hs2_m2)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHREAL8(hs2)
! TAPENADE: (AD14) Checkpointing this call to hst needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to hst needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
      CALL HST(hk2, rt2, m2, hs2, hs2_hk2, hs2_rt2, hs2_m2)
      CALL PUSHCONTROL1B(1)
    END IF
!
    CALL PUSHREAL8(hs2_u2)
    hs2_u2 = hs2_hk2*hk2_u2 + hs2_rt2*rt2_u2 + hs2_m2*m2_u2
    CALL PUSHREAL8(hs2_t2)
    hs2_t2 = hs2_hk2*hk2_t2 + hs2_rt2*rt2_t2
    CALL PUSHREAL8(hs2_d2)
    hs2_d2 = hs2_hk2*hk2_d2
    CALL PUSHREAL8(hs2_ms)
    hs2_ms = hs2_hk2*hk2_ms + hs2_rt2*rt2_ms + hs2_m2*m2_ms
    CALL PUSHREAL8(hs2_re)
    hs2_re = hs2_rt2*rt2_re
!
!---- normalized slip velocity  Us
    CALL PUSHREAL8(us2)
    us2 = 0.5*hs2*(1.0-(hk2-1.0)/(gbcon*h2))
    us2_hs2 = 0.5*(1.0-(hk2-1.0)/(gbcon*h2))
    us2_hk2 = 0.5*hs2*(-(1.0/(gbcon*h2)))
    us2_h2 = 0.5*hs2*(hk2-1.0)/(gbcon*h2**2)
!
    CALL PUSHREAL8(us2_u2)
    us2_u2 = us2_hs2*hs2_u2 + us2_hk2*hk2_u2
    CALL PUSHREAL8(us2_t2)
    us2_t2 = us2_hs2*hs2_t2 + us2_hk2*hk2_t2 + us2_h2*h2_t2
    CALL PUSHREAL8(us2_d2)
    us2_d2 = us2_hs2*hs2_d2 + us2_hk2*hk2_d2 + us2_h2*h2_d2
    CALL PUSHREAL8(us2_ms)
    us2_ms = us2_hs2*hs2_ms + us2_hk2*hk2_ms
    us2_re = us2_hs2*hs2_re
!
! if (Ityp<=2 .and. US2>0.95) then
    us2r = us2
    IF (ityp .LE. 2 .AND. us2r .GT. 0.95) THEN
!CC       WRITE(*,*) 'BLVAR: Us clamped:', US2
      us2 = 0.98
      us2_u2 = 0.
      us2_t2 = 0.
      us2_d2 = 0.
      us2_ms = 0.
      us2_re = 0.
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
!
! if (Ityp==3 .and. US2>0.99995) then
    IF (ityp .EQ. 3 .AND. us2r .GT. 0.99995) THEN
!CC       WRITE(*,*) 'BLVAR: Wake Us clamped:', US2
      us2 = 0.99995
      us2_u2 = 0.
      us2_t2 = 0.
      us2_d2 = 0.
      us2_ms = 0.
      us2_re = 0.
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
!
!---- equilibrium wake layer shear coefficient (Ctau)EQ ** 1/2
!   ...  NEW  12 Oct 94
    hkc = hk2 - 1.0
    hkc_hk2 = 1.0
    hkc_rt2 = 0.0
    IF (ityp .EQ. 2) THEN
      gcc = gccon
      hkc = hk2 - 1.0 - gcc/rt2
      hkc_hk2 = 1.0
      hkc_rt2 = gcc/rt2**2
      IF (hkc .LT. 0.01) THEN
        hkc = 0.01
        hkc_hk2 = 0.0
        hkc_rt2 = 0.0
        CALL PUSHCONTROL2B(0)
      ELSE
        CALL PUSHCONTROL2B(1)
      END IF
    ELSE
      CALL PUSHCONTROL2B(2)
    END IF
!
    hkb = hk2 - 1.0
    usb = 1.0 - us2
    CALL PUSHREAL8(cq2)
    cq2 = SQRT(ctcon*hs2*hkb*hkc**2/(usb*h2*hk2**2))
    cq2_hs2 = ctcon*hkb*hkc**2/(usb*h2*hk2**2)*0.5/cq2
    cq2_us2 = ctcon*hs2*hkb*hkc**2/(usb*h2*hk2**2)/usb*0.5/cq2
    cq2_hk2 = ctcon*hs2*hkc**2/(usb*h2*hk2**2)*0.5/cq2 - ctcon*hs2*hkb*&
&     hkc**2/(usb*h2*hk2**3)*2.0*0.5/cq2 + ctcon*hs2*hkb*hkc/(usb*h2*hk2&
&     **2)*2.0*0.5/cq2*hkc_hk2
    cq2_rt2 = ctcon*hs2*hkb*hkc/(usb*h2*hk2**2)*2.0*0.5/cq2*hkc_rt2
    cq2_h2 = -(ctcon*hs2*hkb*hkc**2/(usb*h2*hk2**2)/h2*0.5/cq2)
!
!
!
!
!---- set skin friction coefficient
    IF (ityp .EQ. 3) THEN
      CALL PUSHCONTROL2B(0)
!----- wake
      cf2_hk2 = 0.
      cf2_rt2 = 0.
      cf2_m2 = 0.
    ELSE IF (ityp .EQ. 1) THEN
!----- laminar
      CALL PUSHREAL8(cf2)
      CALL CFL(hk2, rt2, m2, cf2, cf2_hk2, cf2_rt2, cf2_m2)
      CALL PUSHCONTROL2B(1)
    ELSE
!----- turbulent
      CALL PUSHREAL8(cf2)
! TAPENADE: (AD14) Checkpointing this call to cft needs to save an undeclared side-effect variable: (gam SAVEd by cft)
      CALL CFT(hk2, rt2, m2, cf2, cf2_hk2, cf2_rt2, cf2_m2)
      CALL CFL(hk2, rt2, m2, cf2l, cf2l_hk2, cf2l_rt2, cf2l_m2)
      cf2r = cf2
! if (cf2l>CF2) then
      IF (cf2l .GT. cf2r) THEN
!------- laminar Cf is greater than turbulent Cf -- use laminar
!-       (this will only occur for unreasonably small Rtheta)
!cc      write(*,*) 'Cft Cfl Rt Hk:', CF2, CF2L, RT2, HK2, X2
        cf2_hk2 = cf2l_hk2
        cf2_rt2 = cf2l_rt2
        cf2_m2 = cf2l_m2
        CALL PUSHCONTROL2B(2)
      ELSE
        CALL PUSHCONTROL2B(3)
      END IF
    END IF
!
!
!---- dissipation function    2 CD / H*
    IF (ityp .EQ. 1) THEN
!
!----- laminar
      CALL PUSHREAL8(di2)
      CALL DIL(hk2, rt2, di2, di2_hk2, di2_rt2)
!
!
      CALL PUSHCONTROL2B(0)
    ELSE IF (ityp .EQ. 2) THEN
! TAPENADE: (AD14) Checkpointing this call to cft needs to save an undeclared side-effect variable: (gam SAVEd by cft)
!
!CC       CALL DIT(     HS2,     US2,     CF2,     S2, DI2,
!CC     &           DI2_HS2, DI2_US2, DI2_CF2, DI2_S2      )
!
!----- turbulent wall contribution
      CALL CFT(hk2, rt2, m2, cf2t, cf2t_hk2, cf2t_rt2, cf2t_m2)
      cf2t_u2 = cf2t_hk2*hk2_u2 + cf2t_rt2*rt2_u2 + cf2t_m2*m2_u2
      cf2t_t2 = cf2t_hk2*hk2_t2 + cf2t_rt2*rt2_t2
      cf2t_d2 = cf2t_hk2*hk2_d2
      cf2t_ms = cf2t_hk2*hk2_ms + cf2t_rt2*rt2_ms + cf2t_m2*m2_ms
      cf2t_re = cf2t_rt2*rt2_re
!
      CALL PUSHREAL8(di2)
      di2 = 0.5*cf2t*us2*2.0/hs2
      di2_hs2 = -(0.5*cf2t*us2*2.0/hs2**2)
      di2_us2 = 0.5*cf2t*2.0/hs2
      di2_cf2t = 0.5*us2*2.0/hs2
!
      CALL PUSHREAL8(di2_s2)
      di2_s2 = 0.0
      CALL PUSHREAL8(di2_u2)
      di2_u2 = di2_hs2*hs2_u2 + di2_us2*us2_u2 + di2_cf2t*cf2t_u2
      CALL PUSHREAL8(di2_t2)
      di2_t2 = di2_hs2*hs2_t2 + di2_us2*us2_t2 + di2_cf2t*cf2t_t2
      CALL PUSHREAL8(di2_d2)
      di2_d2 = di2_hs2*hs2_d2 + di2_us2*us2_d2 + di2_cf2t*cf2t_d2
      CALL PUSHREAL8(di2_ms)
      di2_ms = di2_hs2*hs2_ms + di2_us2*us2_ms + di2_cf2t*cf2t_ms
      CALL PUSHREAL8(di2_re)
      di2_re = di2_hs2*hs2_re + di2_us2*us2_re + di2_cf2t*cf2t_re
!
!
!----- set minimum Hk for wake layer to still exist
      grt = LOG(rt2)
      hmin = 1.0 + 2.1/grt
      hm_rt2 = -(2.1/grt**2/rt2)
!
!----- set factor DFAC for correcting wall dissipation for very low Hk
      fl = (hk2-1.0)/(hmin-1.0)
      fl_hk2 = 1.0/(hmin-1.0)
      fl_rt2 = (-(fl/(hmin-1.0)))*hm_rt2
!
      tfl = TANH(fl)
      dfac = 0.5 + 0.5*tfl
      df_fl = 0.5*(1.0-tfl**2)
!
      df_hk2 = df_fl*fl_hk2
      df_rt2 = df_fl*fl_rt2
!
      CALL PUSHREAL8(di2)
      di2 = di2*dfac
!
      CALL PUSHCONTROL2B(1)
    ELSE
!
!----- zero wall contribution for wake
      CALL PUSHREAL8(di2)
      di2 = 0.0
!
      CALL PUSHCONTROL2B(2)
    END IF
!
!
!---- Add on turbulent outer layer contribution
    IF (ityp .NE. 1) THEN
!
      dd = s2**2*(0.995-us2)*2.0/hs2
!
      di2 = di2 + dd
!
!----- add laminar stress contribution to outer layer CD
!###
      dd = 0.15*(0.995-us2)**2/rt2*2.0/hs2
      dd_us2 = -(0.15*(0.995-us2)*2./rt2*2.0/hs2)
      dd_hs2 = -(dd/hs2)
      dd_rt2 = -(dd/rt2)
!
      di2 = di2 + dd
!
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
!
!
    di2r = di2
    IF (ityp .EQ. 2) THEN
      CALL DIL(hk2, rt2, di2l, di2l_hk2, di2l_rt2)
!
! if (di2l>DI2) then
      IF (di2l .GT. di2r) THEN
        CALL PUSHCONTROL2B(0)
      ELSE
        CALL PUSHCONTROL2B(1)
      END IF
    ELSE
      CALL PUSHCONTROL2B(2)
    END IF
!
!C----- add on CD contribution of inner shear layer
!       IF(ITYP.EQ.3 .AND. DW2.GT.0.0) THEN
!        DKON = 0.03*0.75**3
!        DDI = DKON*US2**3
!        DDI_US2 = 3.0*DKON*US2**2
!        DI2 = DI2 + DDI * DW2/DWTE
!        DI2_U2 = DI2_U2 + DDI_US2*US2_U2 * DW2/DWTE
!        DI2_T2 = DI2_T2 + DDI_US2*US2_T2 * DW2/DWTE
!        DI2_D2 = DI2_D2 + DDI_US2*US2_D2 * DW2/DWTE
!        DI2_MS = DI2_MS + DDI_US2*US2_MS * DW2/DWTE
!        DI2_RE = DI2_RE + DDI_US2*US2_RE * DW2/DWTE
!       ENDIF
!
    IF (ityp .EQ. 3) THEN
!------ laminar wake CD
      CALL PUSHREAL8(di2l_rt2)
      CALL PUSHREAL8(di2l_hk2)
      CALL DILW(hk2, rt2, di2l, di2l_hk2, di2l_rt2)
! if (di2l>DI2) then
      IF (di2l .GT. di2r) THEN
        CALL PUSHCONTROL2B(0)
      ELSE
        CALL PUSHCONTROL2B(1)
      END IF
    ELSE
      CALL PUSHCONTROL2B(2)
    END IF
!
!
    IF (ityp .EQ. 3) THEN
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
!
!---- BL thickness (Delta) from simplified Green's correlation
    CALL PUSHREAL8(de2)
    de2 = (3.15+1.72/(hk2-1.0))*t2 + d2
    de2_hk2 = (-(1.72/(hk2-1.0)**2))*t2
!
!
!cc      HDMAX = 15.0
    hdmax = 12.0
    de2r = de2
    t2r = t2
! if (DE2>hdmax * T2) then
    IF (de2r .GT. hdmax*t2r) THEN
      t2b = t2b + hdmax*de2b
      de2_t2b = 0.0_8
      de2_d2b = 0.0_8
      de2_u2b = 0.0_8
      de2_msb = 0.0_8
      de2b = 0.0_8
    END IF
    de2_hk2b = hk2_ms*de2_msb + hk2_d2*de2_d2b + hk2_t2*de2_t2b + hk2_u2&
&     *de2_u2b
    hk2_msb = hk2_msb + de2_hk2*de2_msb
    hk2_d2b = hk2_d2b + de2_hk2*de2_d2b
    hk2_t2b = hk2_t2b + de2_hk2*de2_t2b
    hk2_u2b = hk2_u2b + de2_hk2*de2_u2b
    tempb9 = -(1.72*de2_hk2b/(hk2-1.0)**2)
    hk2b = hk2b - 1.72*de2_t2b/(hk2-1.0)**2 - 2*t2*tempb9/(hk2-1.0) - &
&     1.72*t2*de2b/(hk2-1.0)**2
    t2b = t2b + tempb9 + (1.72/(hk2-1.0)+3.15)*de2b
    CALL POPREAL8(de2)
    d2b = d2b + de2b
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      di2_reb = 2.0*di2_reb
      di2_msb = 2.0*di2_msb
      di2_d2b = 2.0*di2_d2b
      di2_t2b = 2.0*di2_t2b
      di2_u2b = 2.0*di2_u2b
      di2_s2b = 2.0*di2_s2b
      di2b = 2.0*di2b
    END IF
    CALL POPCONTROL2B(branch)
    IF (branch .EQ. 0) THEN
      di2l_rt2b = rt2_re*di2_reb + rt2_ms*di2_msb + rt2_t2*di2_t2b + &
&       rt2_u2*di2_u2b
      rt2_reb = rt2_reb + di2l_rt2*di2_reb
      di2l_hk2b = hk2_ms*di2_msb + hk2_d2*di2_d2b + hk2_t2*di2_t2b + &
&       hk2_u2*di2_u2b
      hk2_msb = hk2_msb + di2l_hk2*di2_msb
      rt2_msb = rt2_msb + di2l_rt2*di2_msb
      hk2_d2b = hk2_d2b + di2l_hk2*di2_d2b
      hk2_t2b = hk2_t2b + di2l_hk2*di2_t2b
      rt2_t2b = rt2_t2b + di2l_rt2*di2_t2b
      hk2_u2b = hk2_u2b + di2l_hk2*di2_u2b
      rt2_u2b = rt2_u2b + di2l_rt2*di2_u2b
      di2lb = di2b
      di2_t2b = 0.0_8
      di2_d2b = 0.0_8
      di2b = 0.0_8
      di2_u2b = 0.0_8
      di2_msb = 0.0_8
      di2_s2b = 0.0_8
      di2_reb = 0.0_8
    ELSE IF (branch .EQ. 1) THEN
      di2l_rt2b = 0.0_8
      di2l_hk2b = 0.0_8
      di2lb = 0.0_8
    ELSE
      GOTO 100
    END IF
    CALL POPREAL8(di2l_hk2)
    CALL POPREAL8(di2l_rt2)
    CALL DILW_B(hk2, hk2b, rt2, rt2b, di2l, di2lb, di2l_hk2, di2l_hk2b, &
&         di2l_rt2, di2l_rt2b)
 100 CALL POPCONTROL2B(branch)
    IF (branch .EQ. 0) THEN
      di2l_rt2b = rt2_re*di2_reb + rt2_ms*di2_msb + rt2_t2*di2_t2b + &
&       rt2_u2*di2_u2b
      rt2_reb = rt2_reb + di2l_rt2*di2_reb
      di2l_hk2b = hk2_ms*di2_msb + hk2_d2*di2_d2b + hk2_t2*di2_t2b + &
&       hk2_u2*di2_u2b
      hk2_msb = hk2_msb + di2l_hk2*di2_msb
      rt2_msb = rt2_msb + di2l_rt2*di2_msb
      hk2_d2b = hk2_d2b + di2l_hk2*di2_d2b
      hk2_t2b = hk2_t2b + di2l_hk2*di2_t2b
      rt2_t2b = rt2_t2b + di2l_rt2*di2_t2b
      hk2_u2b = hk2_u2b + di2l_hk2*di2_u2b
      rt2_u2b = rt2_u2b + di2l_rt2*di2_u2b
      di2lb = di2b
      di2_t2b = 0.0_8
      di2_d2b = 0.0_8
      di2b = 0.0_8
      di2_u2b = 0.0_8
      di2_msb = 0.0_8
      di2_s2b = 0.0_8
      di2_reb = 0.0_8
    ELSE IF (branch .EQ. 1) THEN
      di2l_rt2b = 0.0_8
      di2l_hk2b = 0.0_8
      di2lb = 0.0_8
    ELSE
      GOTO 110
    END IF
    CALL DIL_B(hk2, hk2b, rt2, rt2b, di2l, di2lb, di2l_hk2, di2l_hk2b, &
&        di2l_rt2, di2l_rt2b)
 110 CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      temp8 = (-us2+0.995)/hs2
      dd_hs2b = hs2_re*di2_reb + hs2_ms*di2_msb + hs2_d2*di2_d2b + &
&       hs2_t2*di2_t2b + hs2_u2*di2_u2b
      hs2_reb = hs2_reb + dd_hs2*di2_reb
      dd_us2b = us2_re*di2_reb + us2_ms*di2_msb + us2_d2*di2_d2b + &
&       us2_t2*di2_t2b + us2_u2*di2_u2b
      us2_reb = us2_reb + dd_us2*di2_reb
      dd_rt2b = rt2_re*di2_reb + rt2_ms*di2_msb + rt2_t2*di2_t2b + &
&       rt2_u2*di2_u2b
      rt2_reb = rt2_reb + dd_rt2*di2_reb
      hs2_msb = hs2_msb + dd_hs2*di2_msb
      us2_msb = us2_msb + dd_us2*di2_msb
      rt2_msb = rt2_msb + dd_rt2*di2_msb
      hs2_d2b = hs2_d2b + dd_hs2*di2_d2b
      us2_d2b = us2_d2b + dd_us2*di2_d2b
      hs2_t2b = hs2_t2b + dd_hs2*di2_t2b
      us2_t2b = us2_t2b + dd_us2*di2_t2b
      rt2_t2b = rt2_t2b + dd_rt2*di2_t2b
      hs2_u2b = hs2_u2b + dd_hs2*di2_u2b
      us2_u2b = us2_u2b + dd_us2*di2_u2b
      rt2_u2b = rt2_u2b + dd_rt2*di2_u2b
      ddb = di2b - dd_rt2b/rt2 - dd_hs2b/hs2
      tempb9 = -(2.*2.0*0.15*dd_us2b/(rt2*hs2))
      us2b = us2b - tempb9
      tempb8 = -((0.995-us2)*tempb9/(rt2*hs2))
      rt2b = rt2b + dd*dd_rt2b/rt2**2 + hs2*tempb8
      hs2b = hs2b + dd*dd_hs2b/hs2**2 + rt2*tempb8
      tempb9 = 2.0*0.15*ddb/(rt2*hs2)
      us2b = us2b - 2*(0.995-us2)*tempb9
      tempb8 = -((0.995-us2)**2*tempb9/(rt2*hs2))
      rt2b = rt2b + hs2*tempb8
      hs2b = hs2b + rt2*tempb8
      dd_us2 = -(s2**2*2.0/hs2)
      dd_hs2 = -(s2**2*(0.995-us2)*2.0/hs2**2)
      dd_hs2b = hs2_re*di2_reb + hs2_ms*di2_msb + hs2_d2*di2_d2b + &
&       hs2_t2*di2_t2b + hs2_u2*di2_u2b
      hs2_reb = hs2_reb + dd_hs2*di2_reb
      dd_us2b = us2_re*di2_reb + us2_ms*di2_msb + us2_d2*di2_d2b + &
&       us2_t2*di2_t2b + us2_u2*di2_u2b
      us2_reb = us2_reb + dd_us2*di2_reb
      hs2_msb = hs2_msb + dd_hs2*di2_msb
      us2_msb = us2_msb + dd_us2*di2_msb
      hs2_d2b = hs2_d2b + dd_hs2*di2_d2b
      us2_d2b = us2_d2b + dd_us2*di2_d2b
      hs2_t2b = hs2_t2b + dd_hs2*di2_t2b
      us2_t2b = us2_t2b + dd_us2*di2_t2b
      hs2_u2b = hs2_u2b + dd_hs2*di2_u2b
      us2_u2b = us2_u2b + dd_us2*di2_u2b
      dd_s2b = di2_s2b
      ddb = di2b
      tempb9 = 2.0**2*dd_s2b
      us2b = us2b - s2*tempb9/hs2
      tempb8 = (0.995-us2)*tempb9/hs2
      tempb9 = -(2.0*dd_us2b/hs2)
      s2b = s2b + tempb8 + 2*s2*tempb9
      hs2b = hs2b - s2*tempb8/hs2 - s2**2*tempb9/hs2
      tempb9 = -(2.0*dd_hs2b/hs2**2)
      s2b = s2b + 2*s2*(0.995-us2)*tempb9 + 2*s2*temp8*2.0*ddb
      us2b = us2b - s2**2*tempb9
      hs2b = hs2b - 2*s2**2*(0.995-us2)*tempb9/hs2
      tempb9 = s2**2*2.0*ddb/hs2
      us2b = us2b - tempb9
      hs2b = hs2b - temp8*tempb9
      di2_s2b = 0.0_8
    END IF
    CALL POPCONTROL2B(branch)
    IF (branch .EQ. 0) THEN
      di2_rt2b = rt2_re*di2_reb + rt2_ms*di2_msb + rt2_t2*di2_t2b + &
&       rt2_u2*di2_u2b
      rt2_reb = rt2_reb + di2_rt2*di2_reb
      di2_hk2b = hk2_ms*di2_msb + hk2_d2*di2_d2b + hk2_t2*di2_t2b + &
&       hk2_u2*di2_u2b
      hk2_msb = hk2_msb + di2_hk2*di2_msb
      rt2_msb = rt2_msb + di2_rt2*di2_msb
      hk2_d2b = hk2_d2b + di2_hk2*di2_d2b
      hk2_t2b = hk2_t2b + di2_hk2*di2_t2b
      rt2_t2b = rt2_t2b + di2_rt2*di2_t2b
      hk2_u2b = hk2_u2b + di2_hk2*di2_u2b
      rt2_u2b = rt2_u2b + di2_rt2*di2_u2b
      CALL POPREAL8(di2)
      CALL DIL_B(hk2, hk2b, rt2, rt2b, di2, di2b, di2_hk2, di2_hk2b, &
&          di2_rt2, di2_rt2b)
    ELSE IF (branch .EQ. 1) THEN
      CALL POPREAL8(di2)
      dfacb = di2*di2b + di2_re*di2_reb + di2_ms*di2_msb + di2_d2*&
&       di2_d2b + di2_t2*di2_t2b + di2_u2*di2_u2b + di2_s2*di2_s2b
      di2b = dfac*di2b + df_rt2*rt2_re*di2_reb + (df_hk2*hk2_ms+df_rt2*&
&       rt2_ms)*di2_msb + df_hk2*hk2_d2*di2_d2b + (df_hk2*hk2_t2+df_rt2*&
&       rt2_t2)*di2_t2b + (df_hk2*hk2_u2+df_rt2*rt2_u2)*di2_u2b
      rt2_reb = rt2_reb + di2*df_rt2*di2_reb
      tempb9 = di2*di2_msb
      df_rt2b = di2*rt2_re*di2_reb + rt2_ms*tempb9
      di2_reb = dfac*di2_reb
      di2_msb = dfac*di2_msb
      df_hk2b = hk2_ms*tempb9
      hk2_d2b = hk2_d2b + di2*df_hk2*di2_d2b
      temp8 = grt*grt*rt2
      CALL POPREAL8(di2_re)
      hs2_reb = hs2_reb + di2_hs2*di2_reb
      us2_reb = us2_reb + di2_us2*di2_reb
      cf2t_reb = di2_cf2t*di2_reb
      CALL POPREAL8(di2_ms)
      hs2_msb = hs2_msb + di2_hs2*di2_msb
      us2_msb = us2_msb + di2_us2*di2_msb
      cf2t_msb = di2_cf2t*di2_msb
      hk2_msb = hk2_msb + df_hk2*tempb9 + cf2t_hk2*cf2t_msb
      rt2_msb = rt2_msb + df_rt2*tempb9 + cf2t_rt2*cf2t_msb
      tempb9 = di2*di2_t2b
      df_hk2b = df_hk2b + di2*hk2_d2*di2_d2b + hk2_t2*tempb9
      di2_d2b = dfac*di2_d2b
      di2_t2b = dfac*di2_t2b
      df_rt2b = df_rt2b + rt2_t2*tempb9
      CALL POPREAL8(di2_d2)
