!                cfm_re rt2_t2 hk2_t2 hk2_d2 rt1_t1 cfm_t1 hk1_t1
!                cfm_t2 cfm_d1 hk1_d1 cfm_d2 rt2_u2 hk2_u2 rt1_u1
!                cfm_u1 hk1_u1 cfm_u2 rt2_ms hk2_ms rt1
!   with respect to varying inputs: rt2 rt1_ms hk1_ms hk1 hk2 m2_u2
!                m1_u1 m1 m2_ms m2 rt2_re m1_ms rt1_re rt2_t2 hk2_t2
!                hk2_d2 rt1_t1 hk1_t1 hk1_d1 rt2_u2 hk2_u2 rt1_u1
!                hk1_u1 rt2_ms hk2_ms rt1
!*==BLMID.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE BLMID_B(ityp)
!----------------------------------------------------
!     Calculates midpoint skin friction CFM
!
!      ITYP = 1 :  laminar
!      ITYP = 2 :  turbulent
!      ITYP = 3 :  turbulent wake
!----------------------------------------------------
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    INTEGER :: ityp
! intent (in) Ityp
!
! Local variables
!
    REAL :: cfml, cfml_hka, cfml_ma, cfml_rta, cfm_hka, cfm_ma, cfm_rta&
&   , hka, ma, rta
    REAL :: cfmlb, cfml_hkab, cfml_rtab, cfm_hkab, cfm_mab, cfm_rtab, &
&   hkab, mab, rtab
    REAL :: tempb
    INTEGER :: branch
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
!---- set similarity variables if not defined
    IF (simi) THEN
      CALL PUSHREAL8(hk1)
      hk1 = hk2
      CALL PUSHREAL8(hk1_t1)
      hk1_t1 = hk2_t2
      CALL PUSHREAL8(hk1_d1)
      hk1_d1 = hk2_d2
      CALL PUSHREAL8(hk1_u1)
      hk1_u1 = hk2_u2
      CALL PUSHREAL8(hk1_ms)
      hk1_ms = hk2_ms
      CALL PUSHREAL8(rt1)
      rt1 = rt2
      CALL PUSHREAL8(rt1_t1)
      rt1_t1 = rt2_t2
      CALL PUSHREAL8(rt1_u1)
      rt1_u1 = rt2_u2
      CALL PUSHREAL8(rt1_ms)
      rt1_ms = rt2_ms
      CALL PUSHREAL8(rt1_re)
      rt1_re = rt2_re
      m1 = m2
      m1_u1 = m2_u2
      m1_ms = m2_ms
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
!
!---- define stuff for midpoint CF
    hka = 0.5*(hk1+hk2)
    rta = 0.5*(rt1+rt2)
    ma = 0.5*(m1+m2)
!
!---- midpoint skin friction coefficient  (zero in wake)
    IF (ityp .EQ. 3) THEN
      cfm_hka = 0.
      cfm_rta = 0.
      cfm_ma = 0.
      CALL PUSHCONTROL2B(0)
    ELSE IF (ityp .EQ. 1) THEN
      CALL PUSHREAL8(cfm)
      CALL CFL(hka, rta, ma, cfm, cfm_hka, cfm_rta, cfm_ma)
      CALL PUSHCONTROL2B(1)
    ELSE
      CALL PUSHREAL8(cfm)
! TAPENADE: (AD14) Checkpointing this call to cft needs to save an undeclared side-effect variable: (gam SAVEd by cft)
      CALL CFT(hka, rta, ma, cfm, cfm_hka, cfm_rta, cfm_ma)
      CALL CFL(hka, rta, ma, cfml, cfml_hka, cfml_rta, cfml_ma)
      IF (cfml .GT. cfm) THEN
!cc      write(*,*) 'Cft Cfl Rt Hk:', CFM, CFML, RTA, HKA, 0.5*(X1+X2)
        cfm_hka = cfml_hka
        cfm_rta = cfml_rta
        cfm_ma = cfml_ma
        CALL PUSHCONTROL2B(2)
      ELSE
        CALL PUSHCONTROL2B(3)
      END IF
    END IF
    tempb = 0.5*cfm_reb
    cfm_rtab = (rt1_re+rt2_re)*tempb
    rt1_reb = rt1_reb + cfm_rta*tempb
    rt2_reb = rt2_reb + cfm_rta*tempb
    tempb = 0.5*cfm_msb
    cfm_hkab = (hk1_ms+hk2_ms)*tempb
    hk1_msb = hk1_msb + cfm_hka*tempb
    cfm_mab = (m1_ms+m2_ms)*tempb
    m1_msb = m1_msb + cfm_ma*tempb
    cfm_rtab = cfm_rtab + (rt1_ms+rt2_ms)*tempb
    rt1_msb = rt1_msb + cfm_rta*tempb
    hk2_msb = hk2_msb + cfm_hka*tempb
    m2_msb = m2_msb + cfm_ma*tempb
    rt2_msb = rt2_msb + cfm_rta*tempb
    hk2_d2b = hk2_d2b + cfm_hka*0.5*cfm_d2b
    tempb = 0.5*cfm_t2b
    cfm_hkab = cfm_hkab + hk2_d2*0.5*cfm_d2b + hk2_t2*tempb
    hk2_t2b = hk2_t2b + cfm_hka*tempb
    cfm_rtab = cfm_rtab + rt2_t2*tempb
    rt2_t2b = rt2_t2b + cfm_rta*tempb
    tempb = 0.5*cfm_u2b
    cfm_hkab = cfm_hkab + hk2_u2*tempb
    hk2_u2b = hk2_u2b + cfm_hka*tempb
    cfm_mab = cfm_mab + m2_u2*tempb
    m2_u2b = m2_u2b + cfm_ma*tempb
    cfm_rtab = cfm_rtab + rt2_u2*tempb
    rt2_u2b = rt2_u2b + cfm_rta*tempb
    hk1_d1b = hk1_d1b + cfm_hka*0.5*cfm_d1b
    tempb = 0.5*cfm_t1b
    cfm_hkab = cfm_hkab + hk1_d1*0.5*cfm_d1b + hk1_t1*tempb
    hk1_t1b = hk1_t1b + cfm_hka*tempb
    cfm_rtab = cfm_rtab + rt1_t1*tempb
    rt1_t1b = rt1_t1b + cfm_rta*tempb
    tempb = 0.5*cfm_u1b
    cfm_hkab = cfm_hkab + hk1_u1*tempb
    hk1_u1b = hk1_u1b + cfm_hka*tempb
    cfm_mab = cfm_mab + m1_u1*tempb
    m1_u1b = m1_u1b + cfm_ma*tempb
    cfm_rtab = cfm_rtab + rt1_u1*tempb
    rt1_u1b = rt1_u1b + cfm_rta*tempb
    CALL POPCONTROL2B(branch)
    IF (branch .LT. 2) THEN
      IF (branch .EQ. 0) THEN
        rtab = 0.0_8
        hkab = 0.0_8
        mab = 0.0_8
      ELSE
        CALL POPREAL8(cfm)
        hkab = 0.0_8
        rtab = 0.0_8
        CALL CFL_B(hka, hkab, rta, rtab, ma, cfm, cfmb, cfm_hka, &
&            cfm_hkab, cfm_rta, cfm_rtab, cfm_ma)
        mab = 0.0_8
      END IF
    ELSE
      IF (branch .EQ. 2) THEN
        cfml_rtab = cfm_rtab
        cfml_hkab = cfm_hkab
        cfmlb = cfmb
        cfmb = 0.0_8
        cfm_mab = 0.0_8
        cfm_rtab = 0.0_8
        cfm_hkab = 0.0_8
      ELSE
        cfml_hkab = 0.0_8
        cfmlb = 0.0_8
        cfml_rtab = 0.0_8
      END IF
      hkab = 0.0_8
      rtab = 0.0_8
      CALL CFL_B(hka, hkab, rta, rtab, ma, cfml, cfmlb, cfml_hka, &
&          cfml_hkab, cfml_rta, cfml_rtab, cfml_ma)
      CALL POPREAL8(cfm)
      mab = 0.0_8
      CALL CFT_B(hka, hkab, rta, rtab, ma, mab, cfm, cfmb, cfm_hka, &
&          cfm_hkab, cfm_rta, cfm_rtab, cfm_ma, cfm_mab)
    END IF
    m1b = m1b + 0.5*mab
    m2b = m2b + 0.5*mab
    rt1b = rt1b + 0.5*rtab
    rt2b = rt2b + 0.5*rtab
    hk1b = hk1b + 0.5*hkab
    hk2b = hk2b + 0.5*hkab
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      m2_msb = m2_msb + m1_msb
      m2_u2b = m2_u2b + m1_u1b
      m2b = m2b + m1b
      CALL POPREAL8(rt1_re)
      rt2_reb = rt2_reb + rt1_reb
      CALL POPREAL8(rt1_ms)
      rt2_msb = rt2_msb + rt1_msb
      CALL POPREAL8(rt1_u1)
      rt2_u2b = rt2_u2b + rt1_u1b
      CALL POPREAL8(rt1_t1)
      rt2_t2b = rt2_t2b + rt1_t1b
      CALL POPREAL8(rt1)
      rt2b = rt2b + rt1b
      CALL POPREAL8(hk1_ms)
      hk2_msb = hk2_msb + hk1_msb
      CALL POPREAL8(hk1_u1)
      hk2_u2b = hk2_u2b + hk1_u1b
      CALL POPREAL8(hk1_d1)
      hk2_d2b = hk2_d2b + hk1_d1b
      CALL POPREAL8(hk1_t1)
      hk2_t2b = hk2_t2b + hk1_t1b
      CALL POPREAL8(hk1)
      hk2b = hk2b + hk1b
      rt1_msb = 0.0_8
      hk1_msb = 0.0_8
      hk1b = 0.0_8
      m1_u1b = 0.0_8
      m1b = 0.0_8
      m1_msb = 0.0_8
      rt1_reb = 0.0_8
      rt1_t1b = 0.0_8
      hk1_t1b = 0.0_8
      hk1_d1b = 0.0_8
      rt1_u1b = 0.0_8
      hk1_u1b = 0.0_8
      rt1b = 0.0_8
    END IF
  END SUBROUTINE BLMID_B

!*==BLMID.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE BLMID(ityp)
!----------------------------------------------------
!     Calculates midpoint skin friction CFM
!
!      ITYP = 1 :  laminar
!      ITYP = 2 :  turbulent
!      ITYP = 3 :  turbulent wake
!----------------------------------------------------
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    INTEGER :: ityp
! intent (in) Ityp
!
! Local variables
!
    REAL :: cfml, cfml_hka, cfml_ma, cfml_rta, cfm_hka, cfm_ma, cfm_rta&
&   , hka, ma, rta
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
!---- set similarity variables if not defined
    IF (simi) THEN
      hk1 = hk2
      hk1_t1 = hk2_t2
      hk1_d1 = hk2_d2
      hk1_u1 = hk2_u2
      hk1_ms = hk2_ms
      rt1 = rt2
      rt1_t1 = rt2_t2
      rt1_u1 = rt2_u2
      rt1_ms = rt2_ms
      rt1_re = rt2_re
      m1 = m2
      m1_u1 = m2_u2
      m1_ms = m2_ms
    END IF
!
!---- define stuff for midpoint CF
    hka = 0.5*(hk1+hk2)
    rta = 0.5*(rt1+rt2)
    ma = 0.5*(m1+m2)
!
!---- midpoint skin friction coefficient  (zero in wake)
    IF (ityp .EQ. 3) THEN
      cfm = 0.
      cfm_hka = 0.
      cfm_rta = 0.
      cfm_ma = 0.
      cfm_ms = 0.
    ELSE IF (ityp .EQ. 1) THEN
      CALL CFL(hka, rta, ma, cfm, cfm_hka, cfm_rta, cfm_ma)
    ELSE
      CALL CFT(hka, rta, ma, cfm, cfm_hka, cfm_rta, cfm_ma)
      CALL CFL(hka, rta, ma, cfml, cfml_hka, cfml_rta, cfml_ma)
      IF (cfml .GT. cfm) THEN
!cc      write(*,*) 'Cft Cfl Rt Hk:', CFM, CFML, RTA, HKA, 0.5*(X1+X2)
        cfm = cfml
        cfm_hka = cfml_hka
        cfm_rta = cfml_rta
        cfm_ma = cfml_ma
      END IF
    END IF
!
    cfm_u1 = 0.5*(cfm_hka*hk1_u1+cfm_ma*m1_u1+cfm_rta*rt1_u1)
    cfm_t1 = 0.5*(cfm_hka*hk1_t1+cfm_rta*rt1_t1)
    cfm_d1 = 0.5*(cfm_hka*hk1_d1)
!
    cfm_u2 = 0.5*(cfm_hka*hk2_u2+cfm_ma*m2_u2+cfm_rta*rt2_u2)
    cfm_t2 = 0.5*(cfm_hka*hk2_t2+cfm_rta*rt2_t2)
    cfm_d2 = 0.5*(cfm_hka*hk2_d2)
!
    cfm_ms = 0.5*(cfm_hka*hk1_ms+cfm_ma*m1_ms+cfm_rta*rt1_ms+cfm_hka*&
&     hk2_ms+cfm_ma*m2_ms+cfm_rta*rt2_ms)
    cfm_re = 0.5*(cfm_rta*rt1_re+cfm_rta*rt2_re)
  END SUBROUTINE BLMID

