    REAL, DIMENSION(4) :: blmb, blrb, blrezb, blxb, btmb, btrb, btrezb, &
&   btxb
    REAL :: ctr, ctr_hk2, dt, dt_a1, dt_d1, dt_d2, dt_ms, dt_re, dt_t1, &
&   dt_t2, dt_u1, dt_u2, dt_x1, dt_x2, dt_xf, st, st_a1, st_d1, st_d2, &
&   st_dt, st_ms, st_re, st_t1, st_t2, st_tt, st_u1, st_u2, st_ut, st_x1&
&   , st_x2, st_xf, tt, tt_a1, tt_d1, tt_d2, tt_ms, tt_re, tt_t1, tt_t2&
&   , tt_u1, tt_u2, tt_x1, tt_x2, tt_xf, ut, ut_a1, ut_d1, ut_d2, ut_ms&
&   , ut_re, ut_t1, ut_t2, ut_u1, ut_u2, ut_x1, ut_x2, ut_xf, wf1, &
&   wf1_a1, wf1_d1, wf1_d2, wf1_ms, wf1_re, wf1_t1, wf1_t2, wf1_u1, &
&   wf1_u2, wf1_x1, wf1_x2, wf1_xf, wf2, wf2_a1, wf2_d1, wf2_d2, wf2_ms&
&   , wf2_re, wf2_t1, wf2_t2
    REAL :: wf2_u1, wf2_u2
    REAL :: ctrb, ctr_hk2b, dtb, dt_a1b, dt_d1b, dt_d2b, dt_msb, dt_reb&
&   , dt_t1b, dt_t2b, dt_u1b, dt_u2b, dt_x1b, dt_x2b, dt_xfb, stb, &
&   st_a1b, st_d1b, st_d2b, st_dtb, st_msb, st_reb, st_t1b, st_t2b, &
&   st_ttb, st_u1b, st_u2b, st_utb, st_x1b, st_x2b, st_xfb, ttb, tt_a1b&
&   , tt_d1b, tt_d2b, tt_msb, tt_reb, tt_t1b, tt_t2b, tt_u1b, tt_u2b, &
&   tt_x1b, tt_x2b, tt_xfb, utb, ut_a1b, ut_d1b, ut_d2b, ut_msb, ut_reb&
&   , ut_t1b, ut_t2b, ut_u1b, ut_u2b, ut_x1b, ut_x2b, ut_xfb, wf1b, &
&   wf1_a1b, wf1_d1b, wf1_d2b, wf1_msb, wf1_reb, wf1_t1b, wf1_t2b, &
&   wf1_u1b, wf1_u2b, wf1_x1b, wf1_x2b, wf1_xfb, wf2b, wf2_a1b, wf2_d1b&
&   , wf2_d2b, wf2_msb, wf2_reb, wf2_t1b, wf2_t2b
    REAL :: wf2_u1b, wf2_u2b
    INTEGER :: icom, k, l
    REAL :: wf2_x1, wf2_x2, wf2_xf, wf2_xt
    REAL :: wf2_x1b, wf2_x2b, wf2_xfb, wf2_xtb
    INTRINSIC EXP
    REAL :: tempb
    REAL :: temp
    REAL :: tempb0
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
!---- save variables and sensitivities for future restoration
    CALL BLC_SAVE2()
!
!---- weighting factors for linear interpolation to transition point
    wf2 = (xt-x1)/(x2-x1)
    wf2_xt = 1.0/(x2-x1)
!
    wf2_a1 = wf2_xt*xt_a1
    wf2_x1 = wf2_xt*xt_x1 + (wf2-1.0)/(x2-x1)
    wf2_x2 = wf2_xt*xt_x2 - wf2/(x2-x1)
    wf2_t1 = wf2_xt*xt_t1
    wf2_t2 = wf2_xt*xt_t2
    wf2_d1 = wf2_xt*xt_d1
    wf2_d2 = wf2_xt*xt_d2
    wf2_u1 = wf2_xt*xt_u1
    wf2_u2 = wf2_xt*xt_u2
    wf2_ms = wf2_xt*xt_ms
    wf2_re = wf2_xt*xt_re
    wf2_xf = wf2_xt*xt_xf
!
    wf1 = 1.0 - wf2
    wf1_a1 = -wf2_a1
    wf1_x1 = -wf2_x1
    wf1_x2 = -wf2_x2
    wf1_t1 = -wf2_t1
    wf1_t2 = -wf2_t2
    wf1_d1 = -wf2_d1
    wf1_d2 = -wf2_d2
    wf1_u1 = -wf2_u1
    wf1_u2 = -wf2_u2
    wf1_ms = -wf2_ms
    wf1_re = -wf2_re
    wf1_xf = -wf2_xf
!
!
!**** FIRST,  do laminar part between X1 and XT
!
!-----interpolate primary variables to transition point
    tt = t1*wf1 + t2*wf2
    tt_a1 = t1*wf1_a1 + t2*wf2_a1
    tt_x1 = t1*wf1_x1 + t2*wf2_x1
    tt_x2 = t1*wf1_x2 + t2*wf2_x2
    tt_t1 = t1*wf1_t1 + t2*wf2_t1 + wf1
    tt_t2 = t1*wf1_t2 + t2*wf2_t2 + wf2
    tt_d1 = t1*wf1_d1 + t2*wf2_d1
    tt_d2 = t1*wf1_d2 + t2*wf2_d2
    tt_u1 = t1*wf1_u1 + t2*wf2_u1
    tt_u2 = t1*wf1_u2 + t2*wf2_u2
    tt_ms = t1*wf1_ms + t2*wf2_ms
    tt_re = t1*wf1_re + t2*wf2_re
    tt_xf = t1*wf1_xf + t2*wf2_xf
!
    dt = d1*wf1 + d2*wf2
    dt_a1 = d1*wf1_a1 + d2*wf2_a1
    dt_x1 = d1*wf1_x1 + d2*wf2_x1
    dt_x2 = d1*wf1_x2 + d2*wf2_x2
    dt_t1 = d1*wf1_t1 + d2*wf2_t1
    dt_t2 = d1*wf1_t2 + d2*wf2_t2
    dt_d1 = d1*wf1_d1 + d2*wf2_d1 + wf1
    dt_d2 = d1*wf1_d2 + d2*wf2_d2 + wf2
    dt_u1 = d1*wf1_u1 + d2*wf2_u1
    dt_u2 = d1*wf1_u2 + d2*wf2_u2
    dt_ms = d1*wf1_ms + d2*wf2_ms
    dt_re = d1*wf1_re + d2*wf2_re
    dt_xf = d1*wf1_xf + d2*wf2_xf
!
    ut = u1*wf1 + u2*wf2
    ut_a1 = u1*wf1_a1 + u2*wf2_a1
    ut_x1 = u1*wf1_x1 + u2*wf2_x1
    ut_x2 = u1*wf1_x2 + u2*wf2_x2
    ut_t1 = u1*wf1_t1 + u2*wf2_t1
    ut_t2 = u1*wf1_t2 + u2*wf2_t2
    ut_d1 = u1*wf1_d1 + u2*wf2_d1
    ut_d2 = u1*wf1_d2 + u2*wf2_d2
    ut_u1 = u1*wf1_u1 + u2*wf2_u1 + wf1
    ut_u2 = u1*wf1_u2 + u2*wf2_u2 + wf2
    ut_ms = u1*wf1_ms + u2*wf2_ms
    ut_re = u1*wf1_re + u2*wf2_re
    ut_xf = u1*wf1_xf + u2*wf2_xf
!
!---- set primary "T" variables at XT  (really placed into "2" variables)
    CALL PUSHREAL8(x2)
    x2 = xt
    CALL PUSHREAL8(t2)
    t2 = tt
    CALL PUSHREAL8(d2)
    d2 = dt
    CALL PUSHREAL8(u2)
    u2 = ut
!
    ampl2 = amcrit
    CALL PUSHREAL8(s2)
    s2 = 0.
!
!---- calculate laminar secondary "T" variables
    CALL PUSHREAL8(hk2_ms)
    CALL PUSHREAL8(rt2_ms)
    CALL PUSHREAL8(h2_d2)
    CALL PUSHREAL8(hk2_u2)
    CALL PUSHREAL8(rt2_u2)
    CALL PUSHREAL8(h2_t2)
    CALL PUSHREAL8(h2)
    CALL PUSHREAL8(hk2_d2)
    CALL PUSHREAL8(hk2_t2)
    CALL PUSHREAL8(rt2_t2)
    CALL PUSHREAL8(rt2_re)
    CALL PUSHREAL8(m2)
    CALL PUSHREAL8(m2_ms)
    CALL PUSHREAL8(m2_u2)
    CALL PUSHREAL8(hk2)
    CALL PUSHREAL8(rt2)
    CALL BLKIN()
    CALL PUSHREAL8(hk2)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
    CALL BLVAR(1)
!
!---- calculate X1-XT midpoint CFM value
    CALL PUSHREAL8(rt1)
    CALL PUSHREAL8(hk1_u1)
    CALL PUSHREAL8(rt1_u1)
    CALL PUSHREAL8(hk1_d1)
    CALL PUSHREAL8(hk1_t1)
    CALL PUSHREAL8(rt1_t1)
    CALL PUSHREAL8(rt1_re)
    CALL PUSHREAL8(m1_ms)
    CALL PUSHREAL8(m1)
    CALL PUSHREAL8(m1_u1)
    CALL PUSHREAL8(hk1)
    CALL PUSHREAL8(hk1_ms)
    CALL PUSHREAL8(rt1_ms)
! TAPENADE: (AD14) Checkpointing this call to blmid needs to save an undeclared side-effect variable: (gam SAVEd by cft)
    CALL BLMID(1)
!=
!=    at this point, all "2" variables are really "T" variables at XT
!=
!
!---- set up Newton system for dAm, dTh, dDs, dUe, dXi  at  X1 and XT
    CALL PUSHREAL8ARRAY(vsx, 4)
    CALL PUSHREAL8ARRAY(vsr, 4)
    CALL PUSHREAL8ARRAY(vsm, 4)
    CALL PUSHREAL8ARRAY(vsrez, 4)
    CALL PUSHREAL8ARRAY(vs2, 4*5)
    CALL PUSHREAL8ARRAY(vs1, 4*5)
! TAPENADE: (AD14) Checkpointing this call to bldif needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to bldif needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to bldif needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to bldif needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
    CALL BLDIF(1)
!
!
!
!**** SECOND, set up turbulent part between XT and X2  ****
!
!---- calculate equilibrium shear coefficient CQT at transition point
    CALL PUSHREAL8(cq2)
    CALL PUSHREAL8(cf2_d2)
    CALL PUSHREAL8(di2_re)
    CALL PUSHREAL8(cf2_t2)
    CALL PUSHREAL8(hc2_d2)
    CALL PUSHREAL8(us2_d2)
    CALL PUSHREAL8(de2)
    CALL PUSHREAL8(hc2_t2)
    CALL PUSHREAL8(us2_t2)
    CALL PUSHREAL8(cf2_re)
    CALL PUSHREAL8(di2_s2)
    CALL PUSHREAL8(cq2_ms)
    CALL PUSHREAL8(de2_ms)
    CALL PUSHREAL8(hc2)
    CALL PUSHREAL8(hs2_ms)
    CALL PUSHREAL8(hs2)
    CALL PUSHREAL8(us2)
    CALL PUSHREAL8(cf2)
    CALL PUSHREAL8(di2_ms)
    CALL PUSHREAL8(cq2_u2)
    CALL PUSHREAL8(de2_u2)
    CALL PUSHREAL8(hs2_u2)
    CALL PUSHREAL8(cf2_ms)
    CALL PUSHREAL8(di2_u2)
    CALL PUSHREAL8(hc2_ms)
    CALL PUSHREAL8(us2_ms)
    CALL PUSHREAL8(cq2_d2)
    CALL PUSHREAL8(de2_d2)
    CALL PUSHREAL8(hs2_d2)
    CALL PUSHREAL8(cq2_t2)
    CALL PUSHREAL8(cf2_u2)
    CALL PUSHREAL8(de2_t2)
    CALL PUSHREAL8(hs2_t2)
    CALL PUSHREAL8(hk2)
    CALL PUSHREAL8(hc2_u2)
    CALL PUSHREAL8(us2_u2)
    CALL PUSHREAL8(cq2_re)
    CALL PUSHREAL8(di2)
    CALL PUSHREAL8(di2_d2)
    CALL PUSHREAL8(hs2_re)
    CALL PUSHREAL8(di2_t2)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
    CALL BLVAR(2)
!
!---- set initial shear coefficient value ST at transition point
!-    ( note that CQ2, CQ2_T2, etc. are really "CQT", "CQT_TT", etc.)
!
    ctr = ctrcon*EXP(-(ctrcex/(hk2-1.0)))
    ctr_hk2 = ctr*ctrcex/(hk2-1.0)**2
!
!      CTR     = 1.1*EXP(-10.0/HK2**2)
!      CTR_HK2 = CTR * 10.0 * 2.0/HK2**3
!
!CC      CTR = 1.2
!CC      CTR = 0.7
!CC      CTR_HK2 = 0.0
!
    st = ctr*cq2
    st_tt = ctr*cq2_t2 + cq2*ctr_hk2*hk2_t2
    st_dt = ctr*cq2_d2 + cq2*ctr_hk2*hk2_d2
    st_ut = ctr*cq2_u2 + cq2*ctr_hk2*hk2_u2
    st_ms = ctr*cq2_ms + cq2*ctr_hk2*hk2_ms
    st_re = ctr*cq2_re
!
!---- calculate ST sensitivities wrt the actual "1" and "2" variables
    st_a1 = st_tt*tt_a1 + st_dt*dt_a1 + st_ut*ut_a1
    st_x1 = st_tt*tt_x1 + st_dt*dt_x1 + st_ut*ut_x1
    st_x2 = st_tt*tt_x2 + st_dt*dt_x2 + st_ut*ut_x2
    st_t1 = st_tt*tt_t1 + st_dt*dt_t1 + st_ut*ut_t1
    st_t2 = st_tt*tt_t2 + st_dt*dt_t2 + st_ut*ut_t2
    st_d1 = st_tt*tt_d1 + st_dt*dt_d1 + st_ut*ut_d1
    st_d2 = st_tt*tt_d2 + st_dt*dt_d2 + st_ut*ut_d2
    st_u1 = st_tt*tt_u1 + st_dt*dt_u1 + st_ut*ut_u1
    st_u2 = st_tt*tt_u2 + st_dt*dt_u2 + st_ut*ut_u2
    st_ms = st_tt*tt_ms + st_dt*dt_ms + st_ut*ut_ms + st_ms
    st_re = st_tt*tt_re + st_dt*dt_re + st_ut*ut_re + st_re
    st_xf = st_tt*tt_xf + st_dt*dt_xf + st_ut*ut_xf
!
    ampl2 = 0.
    s2 = st
!
!---- recalculate turbulent secondary "T" variables using proper CTI
    CALL PUSHREAL8(cq2)
    CALL PUSHREAL8(cq2_ms)
    CALL PUSHREAL8(cq2_u2)
    CALL PUSHREAL8(cq2_d2)
    CALL PUSHREAL8(cq2_t2)
    CALL PUSHREAL8(hk2)
    CALL PUSHREAL8(cq2_re)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (gam SAVEd by cft)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (hsmin SAVEd by hst)
! TAPENADE: (AD14) Checkpointing this call to blvar needs to save an undeclared side-effect variable: (dhsinf SAVEd by hst)
    CALL BLVAR(2)
!
!---- set "1" variables to "T" variables and reset "2" variables
!-    to their saved turbulent values
    CALL PUSHREAL8(rt1)
    CALL PUSHREAL8(di1_re)
    CALL PUSHREAL8(cf1_d1)
    CALL PUSHREAL8(cf1_t1)
    CALL PUSHREAL8(cq1)
    CALL PUSHREAL8(hc1_d1)
    CALL PUSHREAL8(us1_d1)
    CALL PUSHREAL8(h1_d1)
    CALL PUSHREAL8(hc1_t1)
    CALL PUSHREAL8(us1_t1)
    CALL PUSHREAL8(hk1_u1)
    CALL PUSHREAL8(ampl1)
    CALL PUSHREAL8(rt1_u1)
    CALL PUSHREAL8(cf1_re)
    CALL PUSHREAL8(h1_t1)
    CALL PUSHREAL8(de1)
    CALL PUSHREAL8(di1_s1)
    CALL PUSHREAL8(u1)
    CALL PUSHREAL8(cq1_ms)
    CALL PUSHREAL8(h1)
    CALL PUSHREAL8(de1_ms)
    CALL PUSHREAL8(hs1_ms)
    CALL PUSHREAL8(x1)
    CALL PUSHREAL8(hc1)
    CALL PUSHREAL8(hs1)
    CALL PUSHREAL8(hk1_d1)
    CALL PUSHREAL8(di1_ms)
    CALL PUSHREAL8(cq1_u1)
    CALL PUSHREAL8(de1_u1)
    CALL PUSHREAL8(hk1_t1)
    CALL PUSHREAL8(rt1_t1)
    CALL PUSHREAL8(hs1_u1)
    CALL PUSHREAL8(us1)
    CALL PUSHREAL8(cf1)
    CALL PUSHREAL8(d1)
    CALL PUSHREAL8(t1)
    CALL PUSHREAL8(rt1_re)
    CALL PUSHREAL8(cf1_ms)
    CALL PUSHREAL8(di1_u1)
    CALL PUSHREAL8(dw1)
    CALL PUSHREAL8(m1_ms)
    CALL PUSHREAL8(hc1_ms)
    CALL PUSHREAL8(us1_ms)
    CALL PUSHREAL8(cq1_d1)
    CALL PUSHREAL8(m1)
    CALL PUSHREAL8(de1_d1)
    CALL PUSHREAL8(hs1_d1)
    CALL PUSHREAL8(cq1_t1)
    CALL PUSHREAL8(cf1_u1)
    CALL PUSHREAL8(de1_t1)
    CALL PUSHREAL8(hs1_t1)
    CALL PUSHREAL8(m1_u1)
    CALL PUSHREAL8(hc1_u1)
    CALL PUSHREAL8(us1_u1)
    CALL PUSHREAL8(cq1_re)
    CALL PUSHREAL8(s1)
    CALL PUSHREAL8(hs1_re)
    CALL PUSHREAL8(di1_d1)
    CALL PUSHREAL8(hk1)
    CALL PUSHREAL8(di1_t1)
    CALL PUSHREAL8(di1)
    CALL PUSHREAL8(hk1_ms)
    CALL PUSHREAL8(rt1_ms)
    CALL BLC_1FROM2()
    CALL PUSHREAL8(hk2_ms)
    CALL PUSHREAL8(rt2_ms)
    CALL PUSHREAL8(h2_d2)
    CALL PUSHREAL8(hk2_u2)
    CALL PUSHREAL8(rt2_u2)
    CALL PUSHREAL8(h2_t2)
    CALL PUSHREAL8(h2)
    CALL PUSHREAL8(hk2_d2)
    CALL PUSHREAL8(hk2_t2)
    CALL PUSHREAL8(rt2_t2)
    CALL PUSHREAL8(dw2)
    CALL PUSHREAL8(rt2_re)
    CALL PUSHREAL8(m2)
    CALL PUSHREAL8(m2_ms)
    CALL PUSHREAL8(m2_u2)
    CALL PUSHREAL8(rt2)
    CALL BLC_RESTORE2()
!
!---- calculate XT-X2 midpoint CFM value
    CALL PUSHREAL8(rt1)
    CALL PUSHREAL8(cfm_u2)
    CALL PUSHREAL8(hk1_u1)
    CALL PUSHREAL8(cfm_u1)
    CALL PUSHREAL8(rt1_u1)
    CALL PUSHREAL8(cfm_d2)
    CALL PUSHREAL8(hk1_d1)
    CALL PUSHREAL8(cfm_d1)
    CALL PUSHREAL8(cfm_t2)
    CALL PUSHREAL8(hk1_t1)
    CALL PUSHREAL8(cfm_t1)
    CALL PUSHREAL8(rt1_t1)
    CALL PUSHREAL8(cfm_re)
    CALL PUSHREAL8(rt1_re)
    CALL PUSHREAL8(m1_ms)
    CALL PUSHREAL8(m1)
    CALL PUSHREAL8(m1_u1)
    CALL PUSHREAL8(hk1)
    CALL PUSHREAL8(cfm)
    CALL PUSHREAL8(hk1_ms)
    CALL PUSHREAL8(cfm_ms)
    CALL PUSHREAL8(rt1_ms)
! TAPENADE: (AD14) Checkpointing this call to blmid needs to save an undeclared side-effect variable: (gam SAVEd by cft)
    CALL BLMID(2)
!
!---- set up Newton system for dCt, dTh, dDs, dUe, dXi  at  XT and X2
    CALL PUSHREAL8ARRAY(vs2, 4*5)
! TAPENADE: (AD14) Checkpointing this call to bldif needs to save an undeclared side-effect variable: (dgr SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to bldif needs to save an undeclared side-effect variable: (hk1 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to bldif needs to save an undeclared side-effect variable: (hk2 SAVEd by dampl2)
! TAPENADE: (AD14) Checkpointing this call to bldif needs to save an undeclared side-effect variable: (dgr SAVEd by dampl)
    CALL BLDIF(2)
    CALL BLC_RESTORE1_B()
    bt1b = 0.0_8
    bt2b = 0.0_8
    bl1b = 0.0_8
    bl2b = 0.0_8
    DO l=5,1,-1
      bl2b(3, l) = bl2b(3, l) + vs2b(3, l)
      bt2b(3, l) = bt2b(3, l) + vs2b(3, l)
      vs2b(3, l) = 0.0_8
      bl1b(3, l) = bl1b(3, l) + vs1b(3, l)
      bt1b(3, l) = bt1b(3, l) + vs1b(3, l)
      vs1b(3, l) = 0.0_8
      bl2b(2, l) = bl2b(2, l) + vs2b(2, l)
      bt2b(2, l) = bt2b(2, l) + vs2b(2, l)
      vs2b(2, l) = 0.0_8
      bl1b(2, l) = bl1b(2, l) + vs1b(2, l)
      bt1b(2, l) = bt1b(2, l) + vs1b(2, l)
      vs1b(2, l) = 0.0_8
      bt2b(1, l) = bt2b(1, l) + vs2b(1, l)
      vs2b(1, l) = 0.0_8
      bt1b(1, l) = bt1b(1, l) + vs1b(1, l)
      vs1b(1, l) = 0.0_8
    END DO
    blxb = 0.0_8
    btxb = 0.0_8
    blxb(3) = blxb(3) + vsxb(3)
    btxb(3) = btxb(3) + vsxb(3)
    vsxb(3) = 0.0_8
    blxb(2) = blxb(2) + vsxb(2)
    btxb(2) = btxb(2) + vsxb(2)
    vsxb(2) = 0.0_8
    btxb(1) = btxb(1) + vsxb(1)
    vsxb(1) = 0.0_8
    blrb = 0.0_8
    btrb = 0.0_8
    blrb(3) = blrb(3) + vsrb(3)
    btrb(3) = btrb(3) + vsrb(3)
    vsrb(3) = 0.0_8
    blrb(2) = blrb(2) + vsrb(2)
    btrb(2) = btrb(2) + vsrb(2)
    vsrb(2) = 0.0_8
    btrb(1) = btrb(1) + vsrb(1)
    vsrb(1) = 0.0_8
    blmb = 0.0_8
    btmb = 0.0_8
    blmb(3) = blmb(3) + vsmb(3)
    btmb(3) = btmb(3) + vsmb(3)
    vsmb(3) = 0.0_8
    blmb(2) = blmb(2) + vsmb(2)
    btmb(2) = btmb(2) + vsmb(2)
    vsmb(2) = 0.0_8
    btmb(1) = btmb(1) + vsmb(1)
    vsmb(1) = 0.0_8
    btrezb = 0.0_8
    blrezb = 0.0_8
    blrezb(3) = blrezb(3) + vsrezb(3)
    btrezb(3) = btrezb(3) + vsrezb(3)
    vsrezb(3) = 0.0_8
    blrezb(2) = blrezb(2) + vsrezb(2)
    btrezb(2) = btrezb(2) + vsrezb(2)
    vsrezb(2) = 0.0_8
    btrezb(1) = btrezb(1) + vsrezb(1)
    vsrezb(1) = 0.0_8
    dt_d1b = 0.0_8
    st_reb = 0.0_8
    dt_d2b = 0.0_8
    ut_msb = 0.0_8
    dt_a1b = 0.0_8
    tt_xfb = 0.0_8
    st_t1b = 0.0_8
    st_t2b = 0.0_8
    st_d1b = 0.0_8
    st_d2b = 0.0_8
    dt_x1b = 0.0_8
    dt_x2b = 0.0_8
    tt_reb = 0.0_8
    st_a1b = 0.0_8
    dt_u1b = 0.0_8
    dt_u2b = 0.0_8
    ut_xfb = 0.0_8
    tt_t1b = 0.0_8
    tt_t2b = 0.0_8
    st_x1b = 0.0_8
    tt_d1b = 0.0_8
    st_x2b = 0.0_8
    tt_d2b = 0.0_8
    st_u1b = 0.0_8
    ut_reb = 0.0_8
    tt_a1b = 0.0_8
    st_u2b = 0.0_8
    dt_msb = 0.0_8
    ut_t1b = 0.0_8
    ut_t2b = 0.0_8
    tt_x1b = 0.0_8
    ut_d1b = 0.0_8
    tt_x2b = 0.0_8
    ut_d2b = 0.0_8
    st_msb = 0.0_8
    tt_u1b = 0.0_8
    ut_a1b = 0.0_8
    tt_u2b = 0.0_8
    dt_xfb = 0.0_8
    ut_x1b = 0.0_8
    ut_x2b = 0.0_8
    tt_msb = 0.0_8
    ut_u1b = 0.0_8
    ut_u2b = 0.0_8
    dt_reb = 0.0_8
    st_xfb = 0.0_8
    dt_t1b = 0.0_8
    dt_t2b = 0.0_8
    DO k=3,1,-1
      vs2b(k, 5) = vs2b(k, 5) + bt2b(k, 5)
      vs1b(k, 1) = vs1b(k, 1) + st_x2*bt2b(k, 5) + st_u2*bt2b(k, 4) + &
&       st_d2*bt2b(k, 3) + st_t2*bt2b(k, 2) + st_x1*bt1b(k, 5) + st_u1*&
&       bt1b(k, 4) + st_d1*bt1b(k, 3) + st_t1*bt1b(k, 2) + st_a1*bt1b(k&
&       , 1) + st_xf*btxb(k) + st_re*btrb(k) + st_ms*btmb(k)
      st_x2b = st_x2b + vs1(k, 1)*bt2b(k, 5)
      vs1b(k, 2) = vs1b(k, 2) + tt_x2*bt2b(k, 5) + tt_u2*bt2b(k, 4) + &
&       tt_d2*bt2b(k, 3) + tt_t2*bt2b(k, 2) + tt_x1*bt1b(k, 5) + tt_u1*&
&       bt1b(k, 4) + tt_d1*bt1b(k, 3) + tt_t1*bt1b(k, 2) + tt_a1*bt1b(k&
&       , 1) + tt_xf*btxb(k) + tt_re*btrb(k) + tt_ms*btmb(k)
      tt_x2b = tt_x2b + vs1(k, 2)*bt2b(k, 5)
      vs1b(k, 3) = vs1b(k, 3) + dt_x2*bt2b(k, 5) + dt_u2*bt2b(k, 4) + &
&       dt_d2*bt2b(k, 3) + dt_t2*bt2b(k, 2) + dt_x1*bt1b(k, 5) + dt_u1*&
&       bt1b(k, 4) + dt_d1*bt1b(k, 3) + dt_t1*bt1b(k, 2) + dt_a1*bt1b(k&
&       , 1) + dt_xf*btxb(k) + dt_re*btrb(k) + dt_ms*btmb(k)
      dt_x2b = dt_x2b + vs1(k, 3)*bt2b(k, 5)
      vs1b(k, 4) = vs1b(k, 4) + ut_x2*bt2b(k, 5) + ut_u2*bt2b(k, 4) + &
&       ut_d2*bt2b(k, 3) + ut_t2*bt2b(k, 2) + ut_x1*bt1b(k, 5) + ut_u1*&
&       bt1b(k, 4) + ut_d1*bt1b(k, 3) + ut_t1*bt1b(k, 2) + ut_a1*bt1b(k&
&       , 1) + ut_xf*btxb(k) + ut_re*btrb(k) + ut_ms*btmb(k)
      ut_x2b = ut_x2b + vs1(k, 4)*bt2b(k, 5)
      vs1b(k, 5) = vs1b(k, 5) + xt_x2*bt2b(k, 5) + xt_u2*bt2b(k, 4) + &
&       xt_d2*bt2b(k, 3) + xt_t2*bt2b(k, 2) + xt_x1*bt1b(k, 5) + xt_u1*&
&       bt1b(k, 4) + xt_d1*bt1b(k, 3) + xt_t1*bt1b(k, 2) + xt_a1*bt1b(k&
&       , 1) + xt_xf*btxb(k) + xt_re*btrb(k) + xt_ms*btmb(k)
      xt_x2b = xt_x2b + vs1(k, 5)*bt2b(k, 5)
