    dtb = d2b
    CALL POPREAL8(t2)
    ttb = t2b
    CALL POPREAL8(x2)
    xtb = xtb + x2b
    u1b = u1b + wf1_xf*ut_xfb + wf1_re*ut_reb + wf1_ms*ut_msb + wf1_u2*&
&     ut_u2b + wf1_u1*ut_u1b + wf1_d2*ut_d2b + wf1_d1*ut_d1b + wf1_t2*&
&     ut_t2b + wf1_t1*ut_t1b + wf1_x2*ut_x2b + wf1_x1*ut_x1b + wf1_a1*&
&     ut_a1b + wf1*utb
    wf1_xfb = u1*ut_xfb + d1*dt_xfb + t1*tt_xfb
    u2b = wf2_xf*ut_xfb + wf2_re*ut_reb + wf2_ms*ut_msb + wf2_u2*ut_u2b &
&     + wf2_u1*ut_u1b + wf2_d2*ut_d2b + wf2_d1*ut_d1b + wf2_t2*ut_t2b + &
&     wf2_t1*ut_t1b + wf2_x2*ut_x2b + wf2_x1*ut_x1b + wf2_a1*ut_a1b + &
&     wf2*utb
    wf2_xfb = u2*ut_xfb + d2*dt_xfb + t2*tt_xfb - wf1_xfb
    wf1_reb = u1*ut_reb + d1*dt_reb + t1*tt_reb
    wf2_reb = u2*ut_reb + d2*dt_reb + t2*tt_reb - wf1_reb
    wf1_msb = u1*ut_msb + d1*dt_msb + t1*tt_msb
    wf2_msb = u2*ut_msb + d2*dt_msb + t2*tt_msb - wf1_msb
    wf1_u2b = u1*ut_u2b + d1*dt_u2b + t1*tt_u2b
    wf2_u2b = u2*ut_u2b + d2*dt_u2b + t2*tt_u2b - wf1_u2b
    wf1_u1b = u1*ut_u1b + d1*dt_u1b + t1*tt_u1b
    wf2_u1b = u2*ut_u1b + d2*dt_u1b + t2*tt_u1b - wf1_u1b
    wf1b = ut_u1b + u1*utb + dt_d1b + d1*dtb + tt_t1b + t1*ttb
    wf1_d2b = u1*ut_d2b + d1*dt_d2b + t1*tt_d2b
    wf2_d2b = u2*ut_d2b + d2*dt_d2b + t2*tt_d2b - wf1_d2b
    wf1_d1b = u1*ut_d1b + d1*dt_d1b + t1*tt_d1b
    wf2_d1b = u2*ut_d1b + d2*dt_d1b + t2*tt_d1b - wf1_d1b
    wf1_t2b = u1*ut_t2b + d1*dt_t2b + t1*tt_t2b
    wf2_t2b = u2*ut_t2b + d2*dt_t2b + t2*tt_t2b - wf1_t2b
    wf1_t1b = u1*ut_t1b + d1*dt_t1b + t1*tt_t1b
    wf2_t1b = u2*ut_t1b + d2*dt_t1b + t2*tt_t1b - wf1_t1b
    wf1_x2b = u1*ut_x2b + d1*dt_x2b + t1*tt_x2b
    wf2_x2b = u2*ut_x2b + d2*dt_x2b + t2*tt_x2b - wf1_x2b
    wf1_x1b = u1*ut_x1b + d1*dt_x1b + t1*tt_x1b
    wf2_x1b = u2*ut_x1b + d2*dt_x1b + t2*tt_x1b - wf1_x1b
    wf1_a1b = u1*ut_a1b + d1*dt_a1b + t1*tt_a1b
    wf2_a1b = u2*ut_a1b + d2*dt_a1b + t2*tt_a1b - wf1_a1b
    d1b = d1b + wf1_xf*dt_xfb + wf1_re*dt_reb + wf1_ms*dt_msb + wf1_u2*&
&     dt_u2b + wf1_u1*dt_u1b + wf1_d2*dt_d2b + wf1_d1*dt_d1b + wf1_t2*&
&     dt_t2b + wf1_t1*dt_t1b + wf1_x2*dt_x2b + wf1_x1*dt_x1b + wf1_a1*&
&     dt_a1b + wf1*dtb
    d2b = wf2_xf*dt_xfb + wf2_re*dt_reb + wf2_ms*dt_msb + wf2_u2*dt_u2b &
&     + wf2_u1*dt_u1b + wf2_d2*dt_d2b + wf2_d1*dt_d1b + wf2_t2*dt_t2b + &
&     wf2_t1*dt_t1b + wf2_x2*dt_x2b + wf2_x1*dt_x1b + wf2_a1*dt_a1b + &
&     wf2*dtb
    t1b = t1b + wf1_xf*tt_xfb + wf1_re*tt_reb + wf1_ms*tt_msb + wf1_u2*&
&     tt_u2b + wf1_u1*tt_u1b + wf1_d2*tt_d2b + wf1_d1*tt_d1b + wf1_t2*&
&     tt_t2b + wf1_t1*tt_t1b + wf1_x2*tt_x2b + wf1_x1*tt_x1b + wf1_a1*&
&     tt_a1b + wf1*ttb
    t2b = wf2_xf*tt_xfb + wf2_re*tt_reb + wf2_ms*tt_msb + wf2_u2*tt_u2b &
&     + wf2_u1*tt_u1b + wf2_d2*tt_d2b + wf2_d1*tt_d1b + wf2_t2*tt_t2b + &
&     wf2_t1*tt_t1b + wf2_x2*tt_x2b + wf2_x1*tt_x1b + wf2_a1*tt_a1b + &
&     wf2*ttb
    wf2_xtb = xt_xf*wf2_xfb + xt_re*wf2_reb + xt_ms*wf2_msb + xt_u2*&
&     wf2_u2b + xt_u1*wf2_u1b + xt_d2*wf2_d2b + xt_d1*wf2_d1b + xt_t2*&
&     wf2_t2b + xt_t1*wf2_t1b + xt_x2*wf2_x2b + xt_x1*wf2_x1b + xt_a1*&
&     wf2_a1b
    xt_reb = xt_reb + wf2_xt*wf2_reb
    xt_msb = xt_msb + wf2_xt*wf2_msb
    xt_u2b = xt_u2b + wf2_xt*wf2_u2b
    xt_u1b = xt_u1b + wf2_xt*wf2_u1b
    xt_d2b = xt_d2b + wf2_xt*wf2_d2b
    xt_d1b = xt_d1b + wf2_xt*wf2_d1b
    xt_t2b = xt_t2b + wf2_xt*wf2_t2b
    xt_t1b = xt_t1b + wf2_xt*wf2_t1b
    xt_x2b = xt_x2b + wf2_xt*wf2_x2b
    tempb0 = -(wf2_x2b/(x2-x1))
    wf2b = ut_u2b + u2*utb + dt_d2b + d2*dtb + tt_t2b + t2*ttb + tempb0 &
&     - wf1b
    tempb = -(wf2*tempb0/(x2-x1))
    x2b = tempb
    x1b = x1b - tempb
    xt_x1b = xt_x1b + wf2_xt*wf2_x1b
    tempb0 = wf2_x1b/(x2-x1)
    wf2b = wf2b + tempb0
    tempb = -((wf2-1.0)*tempb0/(x2-x1))
    xt_a1b = xt_a1b + wf2_xt*wf2_a1b
    tempb0 = -(wf2_xtb/(x2-x1)**2)
    x2b = x2b + tempb + tempb0
    x1b = x1b - tempb - tempb0
    tempb = wf2b/(x2-x1)
    xtb = xtb + tempb
    tempb0 = -((xt-x1)*tempb/(x2-x1))
