!                cfm_t2 de1_u1 cq1_u1 di1_ms cfm_d1 hk1_d1 hs1
!                cfm_d2 hs2 hc1 hs2_ms hc2 de2_ms cq2_ms di2_s2
!                x1 x2 hs1_ms vsm de1_ms h1 amcrit cq1_ms h2 cf2_re
!                h2_t2 rt2_u2 u1 di1_s1 hk2_u2 u2 us2_t2 vsr hc2_t2
