!*==BLDIF.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE BLDIF_B(ityp)
!-----------------------------------------------------------
!     Sets up the Newton system coefficients and residuals
!
!        ITYP = 0 :  similarity station
!        ITYP = 1 :  laminar interval
!        ITYP = 2 :  turbulent interval
!        ITYP = 3 :  wake interval
!
!     This routine knows nothing about a transition interval,
!     which is taken care of by TRDIF.
!-----------------------------------------------------------
    USE I_XBL_DIFF
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    INTEGER :: ityp
! intent (in) Ityp
!
! Local variables
!
    REAL :: ald, arg, ax, ax_a1, ax_a2, ax_hk1, ax_hk2, ax_rt1, ax_rt2, &
&   ax_t1, ax_t2, btmp, cfa, cfx, cfx_cf1, cfx_cf2, cfx_cfm, cfx_t1, &
&   cfx_t2, cfx_ta, cfx_upw, cfx_x1, cfx_x2, cfx_xa, cqa, da, ddlog, dea&
&   , dix, dix_upw, dxi, ehh, gcc, ha, hca, hdcon, hd_hk1, hd_hk2, hka, &
&   hkc, hkc_hka, hkc_rta, hl, hlog, hlsq, hl_hk1, hl_hk2, hr, hr_hka, &
&   hr_rta, hsa, hupwt, hwa, ma, rezc, rezh, rezt, rta, sa, scc, scc_us1&
&   , scc_us2, scc_usa, slog, ta, tlog, ulog, upw, upw_d1, upw_d2, &
&   upw_hd, upw_hk1, upw_hk2, upw_hl, upw_ms, upw_t1, upw_t2, upw_u1
    REAL :: upw_u2, uq
    REAL :: argb, axb, ax_a1b, ax_a2b, ax_hk1b, ax_hk2b, ax_rt1b, &
&   ax_rt2b, ax_t1b, ax_t2b, btmpb, cfab, cfxb, cfx_cf1b, cfx_cf2b, &
&   cfx_cfmb, cfx_t1b, cfx_t2b, cfx_tab, cfx_upwb, cfx_x1b, cfx_x2b, &
&   cfx_xab, cqab, dab, deab, dixb, dix_upwb, dxib, ehhb, hab, hcab, &
&   hdconb, hd_hk2b, hkab, hkcb, hlb, hlogb, hlsqb, hl_hk1b, hl_hk2b, &
&   hrb, hr_hkab, hsab, hwab, mab, rezcb, rezhb, reztb, rtab, sab, sccb&
&   , scc_usab, slogb, tab, tlogb, ulogb, upwb, upw_d1b, upw_d2b, &
&   upw_hdb, upw_hk1b, upw_hk2b, upw_hlb, upw_msb, upw_t1b, upw_t2b, &
&   upw_u1b, upw_u2b, uqb
    INTEGER :: k, l
    REAL :: uq_cfa, uq_d1, uq_d2, uq_da, uq_hka, uq_ms, uq_re, uq_rta, &
&   uq_t1, uq_t2, uq_u1, uq_u2, uq_upw, usa, xa, xlog, xot1, xot2, z_ax&
&   , z_cf1, z_cf2, z_cfa, z_cfm, z_cfx, z_cq1, z_cq2, z_cqa, z_d1, z_d2&
&   , z_da, z_de1, z_de2, z_dea, z_di1, z_di2, z_dix, z_dxi, z_ha, z_hca&
&   , z_hk1, z_hk2, z_hka, z_hl, z_hs1, z_hs2, z_hwa, z_ma, z_s1, z_s2, &
&   z_sa, z_sl, z_t1, z_t2, z_tl, z_u1, z_u2, z_ul, z_upw, z_us1, z_us2&
&   , z_usa, z_x1, z_x2, z_xl
    REAL :: uq_cfab, uq_dab, uq_hkab, usab, xab, xlogb, xot1b, xot2b, &
&   z_axb, z_cf1b, z_cf2b, z_cfab, z_cfmb, z_cfxb, z_cq1b, z_cq2b, &
&   z_cqab, z_d1b, z_d2b, z_dab, z_de1b, z_de2b, z_deab, z_di1b, z_di2b&
&   , z_dixb, z_dxib, z_hab, z_hcab, z_hk1b, z_hk2b, z_hkab, z_hs1b, &
&   z_hs2b, z_hwab, z_mab, z_s1b, z_s2b, z_sab, z_slb, z_t1b, z_t2b, &
&   z_u1b, z_u2b, z_ulb, z_upwb, z_us1b, z_us2b, z_usab, z_x1b, z_x2b, &
&   z_xlb
    INTRINSIC LOG
    INTRINSIC ABS
    INTRINSIC MIN
    INTRINSIC EXP
    REAL :: temp
    REAL :: tempb
    REAL :: tempb0
    REAL :: tempb1
    REAL :: temp0
    REAL :: tempb2
    INTEGER :: branch
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
    IF (ityp .EQ. 0) THEN
      CALL PUSHCONTROL1B(1)
!----- similarity logarithmic differences  (prescribed)
      xlog = 1.0
      ulog = bule
      ddlog = 0.
    ELSE
!----- usual logarithmic differences
      xlog = LOG(x2/x1)
      ulog = LOG(u2/u1)
!       XLOG = 2.0*(X2-X1)/(X2+X1)
!       ULOG = 2.0*(U2-U1)/(U2+U1)
!       TLOG = 2.0*(T2-T1)/(T2+T1)
!       HLOG = 2.0*(HS2-HS1)/(HS2+HS1)
      ddlog = 1.0
      CALL PUSHCONTROL1B(0)
    END IF
!
!---- set triggering constant for local upwinding
    hupwt = 1.0
!
!cc      HDCON = 5.0*HUPWT
!cc      HD_HK1 = 0.0
!cc      HD_HK2 = 0.0
!
    hdcon = 5.0*hupwt/hk2**2
    hd_hk1 = 0.0
    hd_hk2 = -(hdcon*2.0/hk2)
!
!---- use less upwinding in the wake
    IF (ityp .EQ. 3) THEN
      hdcon = hupwt/hk2**2
      hd_hk1 = 0.0
      hd_hk2 = -(hdcon*2.0/hk2)
      CALL PUSHCONTROL1B(1)
    ELSE
      CALL PUSHCONTROL1B(0)
    END IF
    IF ((hk2-1.0)/(hk1-1.0) .GE. 0.) THEN
      arg = (hk2-1.0)/(hk1-1.0)
      CALL PUSHCONTROL1B(0)
    ELSE
      arg = -((hk2-1.0)/(hk1-1.0))
      CALL PUSHCONTROL1B(1)
    END IF
    hl = LOG(arg)
    hl_hk1 = -(1.0/(hk1-1.0))
    hl_hk2 = 1.0/(hk2-1.0)
    IF (hl**2 .GT. 15.0) THEN
      CALL PUSHCONTROL1B(0)
      hlsq = 15.0
    ELSE
      hlsq = hl**2
      CALL PUSHCONTROL1B(1)
    END IF
    ehh = EXP(-(hlsq*hdcon))
    upw = 1.0 - 0.5*ehh
    upw_hl = ehh*hl*hdcon
    upw_hd = 0.5*ehh*hlsq
!
    upw_hk1 = upw_hl*hl_hk1 + upw_hd*hd_hk1
    upw_hk2 = upw_hl*hl_hk2 + upw_hd*hd_hk2
!
    upw_u1 = upw_hk1*hk1_u1
    upw_t1 = upw_hk1*hk1_t1
    upw_d1 = upw_hk1*hk1_d1
    upw_u2 = upw_hk2*hk2_u2
    upw_t2 = upw_hk2*hk2_t2
    upw_d2 = upw_hk2*hk2_d2
    upw_ms = upw_hk1*hk1_ms + upw_hk2*hk2_ms
!
!
    IF (ityp .EQ. 0) THEN
      CALL PUSHCONTROL2B(0)
    ELSE IF (ityp .EQ. 1) THEN
!
!***** laminar part -->  set amplification equation
!
!----- set average amplification AX over interval X1..X2
      CALL AXSET_FWD(hk1, t1, rt1, ampl1, hk2, t2, rt2, ampl2, amcrit, &
&              idampv, ax, ax_hk1, ax_t1, ax_rt1, ax_a1, ax_hk2, ax_t2, &
&              ax_rt2, ax_a2)
!
      z_ax = -(x2-x1)
!
!
      CALL PUSHCONTROL2B(1)
    ELSE
!
!***** turbulent part -->  set shear lag equation
!
      sa = (1.0-upw)*s1 + upw*s2
      cqa = (1.0-upw)*cq1 + upw*cq2
      cfa = (1.0-upw)*cf1 + upw*cf2
      hka = (1.0-upw)*hk1 + upw*hk2
!
      usa = 0.5*(us1+us2)
      rta = 0.5*(rt1+rt2)
      dea = 0.5*(de1+de2)
      da = 0.5*(d1+d2)
!
!
      IF (ityp .EQ. 3) THEN
!------ increased dissipation length in wake (decrease its reciprocal)
        ald = dlcon
      ELSE
        ald = 1.0
      END IF
!
!----- set and linearize  equilibrium 1/Ue dUe/dx   ...  NEW  12 Oct 94
      IF (ityp .EQ. 2) THEN
        gcc = gccon
        hkc = hka - 1.0 - gcc/rta
        hkc_hka = 1.0
        IF (hkc .LT. 0.01) THEN
          hkc = 0.01
          hkc_hka = 0.0
          CALL PUSHCONTROL2B(0)
        ELSE
          CALL PUSHCONTROL2B(1)
        END IF
      ELSE
        hkc = hka - 1.0
        hkc_hka = 1.0
        CALL PUSHCONTROL2B(2)
      END IF
!
      hr = hkc/(gacon*ald*hka)
      hr_hka = hkc_hka/(gacon*ald*hka) - hr/hka
!
      uq = (0.5*cfa-hr**2)/(gbcon*da)
      uq_hka = -(2.0*hr*hr_hka/(gbcon*da))
      uq_cfa = 0.5/(gbcon*da)
      uq_da = -(uq/da)
!
!
!
      scc = sccon*1.333/(1.0+usa)
      scc_usa = -(scc/(1.0+usa))
!
!
!
      slog = LOG(s2/s1)
      dxi = x2 - x1
!
!
!        if(  ! (rt2.gt.1.0e3 .and. rt1.le.1.0e3) .or.
!     &     (rt2.gt.1.0e4 .and. rt1.le.1.0e4) .or.
!     &     (rt2.gt.1.0e5 .and. rt1.le.1.0e5)        ) then
!           gga = (HKA-1.0-GCC/RTA)/HKA / sqrt(0.5*CFA)
!           write(*,4455) rta, hka, gga, cfa, cqa, sa, uq, ulog/dxi
! 4455      format(1x,f7.0, 2f9.4,f10.6,2f8.5,2f10.5)
!        endif
      z_cfa = dea*2.0*uq_cfa*dxi*duxcon
      z_hka = dea*2.0*uq_hka*dxi*duxcon
      z_sl = -(dea*2.0)
      z_usa = scc_usa*(cqa-sa*ald)*dxi
      z_cqa = scc*dxi
      z_sa = -(scc*dxi*ald)
      z_dea = 2.0*((uq*dxi-ulog)*duxcon-slog)
!
      z_upw = z_cqa*(cq2-cq1) + z_sa*(s2-s1) + z_cfa*(cf2-cf1) + z_hka*(&
&       hk2-hk1)
      z_de1 = 0.5*z_dea
      z_de2 = 0.5*z_dea
      z_us1 = 0.5*z_usa
      z_us2 = 0.5*z_usa
      z_cq1 = (1.0-upw)*z_cqa
      z_cq2 = upw*z_cqa
      z_hk1 = (1.0-upw)*z_hka
      z_hk2 = upw*z_hka
!
!
!
!
!
      CALL PUSHCONTROL2B(2)
    END IF
!
!**** Set up momentum equation
    ma = 0.5*(m1+m2)
    xa = 0.5*(x1+x2)
    ta = 0.5*(t1+t2)
!
!---- set Cf term, using central value CFM for better accuracy in drag
    cfx = 0.50*cfm*xa/ta + 0.25*(cf1*x1/t1+cf2*x2/t2)
    cfx_xa = 0.50*cfm/ta
    cfx_ta = -(.50*cfm*xa/ta**2)
!
    cfx_x1 = 0.25*cf1/t1 + cfx_xa*0.5
    cfx_x2 = 0.25*cf2/t2 + cfx_xa*0.5
    cfx_t1 = -(.25*cf1*x1/t1**2) + cfx_ta*0.5
    cfx_t2 = -(.25*cf2*x2/t2**2) + cfx_ta*0.5
    cfx_cf1 = 0.25*x1/t1
    cfx_cf2 = 0.25*x2/t2
    cfx_cfm = 0.50*xa/ta
!
!
    z_cfx = -(xlog*0.5)
    z_ma = -ulog
    z_tl = ddlog
!
    z_cfm = z_cfx*cfx_cfm
!
!
!
!
!**** Set up shape parameter equation
!
    xot1 = x1/t1
    xot2 = x2/t2
!
    ha = 0.5*(h1+h2)
    hsa = 0.5*(hs1+hs2)
    hca = 0.5*(hc1+hc2)
    hwa = 0.5*(dw1/t1+dw2/t2)
!
    dix = (1.0-upw)*di1*xot1 + upw*di2*xot2
    CALL PUSHREAL8(cfx)
    cfx = (1.0-upw)*cf1*xot1 + upw*cf2*xot2
    dix_upw = di2*xot2 - di1*xot1
    cfx_upw = cf2*xot2 - cf1*xot1
!
    btmp = 2.0*hca/hsa + 1.0 - ha - hwa
!
    z_cfx = xlog*0.5
    z_dix = -xlog
    z_hca = 2.0*ulog/hsa
    z_ha = -ulog
    z_hwa = -ulog
    z_xl = ddlog*(0.5*cfx-dix)
    z_ul = ddlog*btmp
    z_hl = ddlog
!
    CALL PUSHREAL8(z_upw)
    z_upw = z_cfx*cfx_upw + z_dix*dix_upw
!
    z_hs1 = -(hca*ulog/hsa**2) - z_hl/hs1
    z_hs2 = -(hca*ulog/hsa**2) + z_hl/hs2
!
    z_cf1 = (1.0-upw)*z_cfx*xot1
    z_cf2 = upw*z_cfx*xot2
    z_di1 = (1.0-upw)*z_dix*xot1
    z_di2 = upw*z_dix*xot2
!
!
!
!
!
!
    tempb2 = 0.5*vs2b(3, 3)
    rezhb = -vsrezb(3)
    vsrezb(3) = 0.0_8
    vsxb(3) = 0.0_8
    z_hcab = (hc1_ms*0.5+hc2_ms*0.5)*vsmb(3) + hc2_u2*0.5*vs2b(3, 4) + &
&     hc2_d2*tempb2
    hc1_msb = hc1_msb + z_hca*0.5*vsmb(3)
    z_upwb = upw_ms*vsmb(3) + upw_u2*vs2b(3, 4) + upw_d2*vs2b(3, 3) + &
&     upw_t2*vs2b(3, 2) + upw_u1*vs1b(3, 4) + upw_d1*vs1b(3, 3) + upw_t1&
&     *vs1b(3, 2)
    upw_msb = z_upw*vsmb(3)
    hc2_msb = hc2_msb + z_hca*0.5*vsmb(3)
    hc2_u2b = hc2_u2b + z_hca*0.5*vs2b(3, 4)
    upw_u2b = z_upw*vs2b(3, 4)
    upw_d2b = z_upw*vs2b(3, 3)
    hc2_d2b = hc2_d2b + z_hca*tempb2
    z_hab = h2_d2*tempb2
    h2_d2b = h2_d2b + z_ha*tempb2
    tempb2 = 0.5*vs2b(3, 2)
    upw_t2b = z_upw*vs2b(3, 2)
    z_hcab = z_hcab + hc2_t2*tempb2
    hc2_t2b = hc2_t2b + z_hca*tempb2
    z_hab = z_hab + h2_t2*tempb2
    h2_t2b = h2_t2b + z_ha*tempb2
    hc1_u1b = hc1_u1b + z_hca*0.5*vs1b(3, 4)
    upw_u1b = z_upw*vs1b(3, 4)
    tempb2 = 0.5*vs1b(3, 3)
    z_hcab = z_hcab + hc1_u1*0.5*vs1b(3, 4) + hc1_d1*tempb2
    upw_d1b = z_upw*vs1b(3, 3)
    hc1_d1b = hc1_d1b + z_hca*tempb2
    z_hab = z_hab + h1_d1*tempb2
    h1_d1b = h1_d1b + z_ha*tempb2
    tempb2 = 0.5*vs1b(3, 2)
    upw_t1b = z_upw*vs1b(3, 2)
    z_hcab = z_hcab + hc1_t1*tempb2
    hc1_t1b = hc1_t1b + z_hca*tempb2
    z_hab = z_hab + h1_t1*tempb2
    h1_t1b = h1_t1b + z_ha*tempb2
    z_hs1b = hs1_re*vsrb(3) + hs1_ms*vsmb(3) + hs1_u1*vs1b(3, 4) + &
&     hs1_d1*vs1b(3, 3) + hs1_t1*vs1b(3, 2)
    hs1_reb = hs1_reb + z_hs1*vsrb(3)
    z_cf1b = cf1_re*vsrb(3) + cf1_ms*vsmb(3) + cf1_u1*vs1b(3, 4) + &
&     cf1_d1*vs1b(3, 3) + cf1_t1*vs1b(3, 2)
    cf1_reb = cf1_reb + z_cf1*vsrb(3)
    z_di1b = di1_re*vsrb(3) + di1_ms*vsmb(3) + di1_u1*vs1b(3, 4) + &
&     di1_d1*vs1b(3, 3) + di1_t1*vs1b(3, 2) + di1_s1*vs1b(3, 1)
    di1_reb = di1_reb + z_di1*vsrb(3)
    z_hs2b = hs2_re*vsrb(3) + hs2_ms*vsmb(3) + hs2_u2*vs2b(3, 4) + &
&     hs2_d2*vs2b(3, 3) + hs2_t2*vs2b(3, 2)
    hs2_reb = hs2_reb + z_hs2*vsrb(3)
    z_cf2b = cf2_re*vsrb(3) + cf2_ms*vsmb(3) + cf2_u2*vs2b(3, 4) + &
&     cf2_d2*vs2b(3, 3) + cf2_t2*vs2b(3, 2)
    cf2_reb = cf2_reb + z_cf2*vsrb(3)
    z_di2b = di2_re*vsrb(3) + di2_ms*vsmb(3) + di2_u2*vs2b(3, 4) + &
&     di2_d2*vs2b(3, 3) + di2_t2*vs2b(3, 2) + di2_s2*vs2b(3, 1)
    di2_reb = di2_reb + z_di2*vsrb(3)
    vsrb(3) = 0.0_8
    hs1_msb = hs1_msb + z_hs1*vsmb(3)
    cf1_msb = cf1_msb + z_cf1*vsmb(3)
    di1_msb = di1_msb + z_di1*vsmb(3)
    hs2_msb = hs2_msb + z_hs2*vsmb(3)
    cf2_msb = cf2_msb + z_cf2*vsmb(3)
    di2_msb = di2_msb + z_di2*vsmb(3)
    vsmb(3) = 0.0_8
    z_x2b = vs2b(3, 5)
    vs2b(3, 5) = 0.0_8
    hs2_u2b = hs2_u2b + z_hs2*vs2b(3, 4)
    cf2_u2b = cf2_u2b + z_cf2*vs2b(3, 4)
    di2_u2b = di2_u2b + z_di2*vs2b(3, 4)
    z_u2b = vs2b(3, 4)
    vs2b(3, 4) = 0.0_8
    hs2_d2b = hs2_d2b + z_hs2*vs2b(3, 3)
    cf2_d2b = cf2_d2b + z_cf2*vs2b(3, 3)
    di2_d2b = di2_d2b + z_di2*vs2b(3, 3)
    vs2b(3, 3) = 0.0_8
    hs2_t2b = hs2_t2b + z_hs2*vs2b(3, 2)
    cf2_t2b = cf2_t2b + z_cf2*vs2b(3, 2)
    di2_t2b = di2_t2b + z_di2*vs2b(3, 2)
    z_t2b = vs2b(3, 2)
    vs2b(3, 2) = 0.0_8
    di2_s2b = di2_s2b + z_di2*vs2b(3, 1)
    vs2b(3, 1) = 0.0_8
    z_x1b = vs1b(3, 5)
    vs1b(3, 5) = 0.0_8
    hs1_u1b = hs1_u1b + z_hs1*vs1b(3, 4)
    cf1_u1b = cf1_u1b + z_cf1*vs1b(3, 4)
    di1_u1b = di1_u1b + z_di1*vs1b(3, 4)
    z_u1b = vs1b(3, 4)
    vs1b(3, 4) = 0.0_8
    hs1_d1b = hs1_d1b + z_hs1*vs1b(3, 3)
    cf1_d1b = cf1_d1b + z_cf1*vs1b(3, 3)
    di1_d1b = di1_d1b + z_di1*vs1b(3, 3)
    vs1b(3, 3) = 0.0_8
    hs1_t1b = hs1_t1b + z_hs1*vs1b(3, 2)
    cf1_t1b = cf1_t1b + z_cf1*vs1b(3, 2)
    di1_t1b = di1_t1b + z_di1*vs1b(3, 2)
    z_t1b = vs1b(3, 2)
    vs1b(3, 2) = 0.0_8
    di1_s1b = di1_s1b + z_di1*vs1b(3, 1)
    vs1b(3, 1) = 0.0_8
    tempb2 = -(0.5*z_t2b/t2**2)
    z_hwab = dw2*tempb2
    dw2b = dw2b + z_hwa*tempb2
    z_ulb = z_u2b/u2 - z_u1b/u1
    u2b = u2b - z_ul*z_u2b/u2**2
    u1b = u1b + z_ul*z_u1b/u1**2
    tempb1 = (z_cfx*cf2+z_dix*di2)*z_x2b/t2
    t2b = t2b - 2*z_hwa*dw2*tempb2/t2 - upw*tempb1/t2
    tempb2 = -(0.5*z_t1b/t1**2)
    z_hwab = z_hwab + dw1*tempb2
    dw1b = dw1b + z_hwa*tempb2
    t1b = t1b - 2*z_hwa*dw1*tempb2/t1
    tempb2 = upw*z_x2b/t2
    z_xlb = z_x2b/x2 - z_x1b/x1
    x2b = x2b - z_xl*z_x2b/x2**2
    upwb = tempb1
    cf2b = cf2b + z_cfx*tempb2
    di2b = di2b + z_dix*tempb2
    temp0 = (-upw+1.0)/t1
    tempb1 = temp0*z_x1b
    z_cfxb = cf2*tempb2 + cf1*tempb1
    z_dixb = di2*tempb2 + di1*tempb1
    tempb2 = (z_cfx*cf1+z_dix*di1)*z_x1b/t1
    x1b = x1b + z_xl*z_x1b/x1**2
    cf1b = cf1b + z_cfx*tempb1
    di1b = di1b + z_dix*tempb1
    upwb = upwb - tempb2
    t1b = t1b - temp0*tempb2
    temp0 = upw*xot2/t2
    tempb1 = -(temp0*z_t2b)
    tempb2 = -((z_cfx*cf2+z_dix*di2)*z_t2b/t2)
    t2b = t2b - temp0*tempb2
    z_cfxb = z_cfxb + cf2*tempb1
    cf2b = cf2b + z_cfx*tempb1
    z_dixb = z_dixb + di2*tempb1
    temp0 = xot1/t1
    tempb0 = -((z_cfx*cf1+z_dix*di1)*z_t1b)
    CALL POPREAL8(z_upw)
    cfx_upwb = z_cfx*z_upwb
    dix_upwb = z_dix*z_upwb
    btmpb = ddlog*z_ulb + ulog*rezhb
    cfxb = 0.5*ddlog*z_xlb + 0.5*xlog*rezhb
    dixb = -(ddlog*z_xlb) - xlog*rezhb
    upwb = upwb + xot2*tempb2 + z_dix*xot2*z_di2b - temp0*tempb0 + z_cfx&
&     *xot2*z_cf2b - z_dix*xot1*z_di1b + (cf2*xot2-cf1*xot1)*cfxb - &
&     z_cfx*xot1*z_cf1b + (di2*xot2-di1*xot1)*dixb
    xot2b = upw*tempb2 + upw*z_dix*z_di2b + upw*z_cfx*z_cf2b + cf2*&
&     cfx_upwb + di2*dix_upwb + upw*cf2*cfxb + upw*di2*dixb
    di2b = di2b + z_dix*tempb1 + xot2*dix_upwb + upw*xot2*dixb
    tempb1 = -((1.0-upw)*temp0*z_t1b)
    tempb2 = (1.0-upw)*tempb0/t1
    xot1b = tempb2 + z_dix*(1.0-upw)*z_di1b + z_cfx*(1.0-upw)*z_cf1b + &
&     cf1*(1.0-upw)*cfxb - cf1*cfx_upwb - di1*dix_upwb + di1*(1.0-upw)*&
&     dixb
    t1b = t1b - temp0*tempb2
    z_cfxb = z_cfxb + cf1*tempb1 + upw*xot2*z_cf2b + xot1*(1.0-upw)*&
&     z_cf1b + cfx_upw*z_upwb
    cf1b = cf1b + z_cfx*tempb1
    z_dixb = z_dixb + di1*tempb1 + upw*xot2*z_di2b + xot1*(1.0-upw)*&
&     z_di1b + dix_upw*z_upwb
    di1b = di1b + z_dix*tempb1 + xot1*(1.0-upw)*dixb - xot1*dix_upwb
    tempb2 = -(z_hs2b/hsa**2)
    hcab = ulog*tempb2
    ulogb = hca*tempb2
    hsab = -(2*hca*ulog*tempb2/hsa)
    tempb2 = -(z_hs1b/hsa**2)
    hcab = hcab + ulog*tempb2
    ulogb = ulogb + hca*tempb2
    hsab = hsab - 2*hca*ulog*tempb2/hsa
    tempb2 = 2.0*z_hcab/hsa
    ulogb = ulogb + tempb2 - z_hwab - z_hab + btmp*rezhb
    hsab = hsab - ulog*tempb2/hsa
    xlogb = 0.5*z_cfxb - z_dixb + (0.5*cfx-dix)*rezhb
    z_cfx = -(xlog*0.5)
    hlogb = rezhb
    tempb2 = 2.0*btmpb/hsa
    hab = -btmpb
    hwab = -btmpb
    hcab = hcab + tempb2
    hsab = hsab - hca*tempb2/hsa
    hs2b = hs2b + 0.5*hsab - z_hl*z_hs2b/hs2**2
    hs1b = hs1b + z_hl*z_hs1b/hs1**2 + 0.5*hsab
    CALL POPREAL8(cfx)
    tempb2 = 0.5*hwab
    dw1b = dw1b + tempb2/t1
    t1b = t1b - dw1*tempb2/t1**2
    dw2b = dw2b + tempb2/t2
    t2b = t2b - dw2*tempb2/t2**2
    hc1b = hc1b + 0.5*hcab
    hc2b = hc2b + 0.5*hcab
    h1b = h1b + 0.5*hab
    h2b = h2b + 0.5*hab
    reztb = -vsrezb(2)
    vsrezb(2) = 0.0_8
    vsxb(2) = 0.0_8
    z_cf1 = z_cfx*cfx_cf1
    z_cf2 = z_cfx*cfx_cf2
    z_cfmb = cfm_re*vsrb(2) + cfm_ms*vsmb(2) + cfm_u2*vs2b(2, 4) + &
&     cfm_d2*vs2b(2, 3) + cfm_t2*vs2b(2, 2) + cfm_u1*vs1b(2, 4) + cfm_d1&
&     *vs1b(2, 3) + cfm_t1*vs1b(2, 2)
    cfm_reb = z_cfm*vsrb(2)
    z_cf1b = cf1_re*vsrb(2) + cf1_ms*vsmb(2) + cf1_u1*vs1b(2, 4) + &
&     cf1_d1*vs1b(2, 3) + cf1_t1*vs1b(2, 2)
    cf1_reb = cf1_reb + z_cf1*vsrb(2)
    z_cf2b = cf2_re*vsrb(2) + cf2_ms*vsmb(2) + cf2_u2*vs2b(2, 4) + &
&     cf2_d2*vs2b(2, 3) + cf2_t2*vs2b(2, 2)
    cf2_reb = cf2_reb + z_cf2*vsrb(2)
    vsrb(2) = 0.0_8
    z_mab = (m1_ms*0.5+m2_ms*0.5)*vsmb(2) + m2_u2*0.5*vs2b(2, 4) + m1_u1&
&     *0.5*vs1b(2, 4)
    m1_msb = m1_msb + z_ma*0.5*vsmb(2)
    cfm_msb = z_cfm*vsmb(2)
    cf1_msb = cf1_msb + z_cf1*vsmb(2)
    m2_msb = m2_msb + z_ma*0.5*vsmb(2)
    cf2_msb = cf2_msb + z_cf2*vsmb(2)
    vsmb(2) = 0.0_8
    z_x2b = vs2b(2, 5)
    vs2b(2, 5) = 0.0_8
    m2_u2b = m2_u2b + z_ma*0.5*vs2b(2, 4)
    cfm_u2b = z_cfm*vs2b(2, 4)
    cf2_u2b = cf2_u2b + z_cf2*vs2b(2, 4)
    z_u2b = vs2b(2, 4)
    vs2b(2, 4) = 0.0_8
    z_ha = ulog
    z_hab = h2_d2*0.5*vs2b(2, 3) + h2_t2*0.5*vs2b(2, 2) + h1_d1*0.5*vs1b&
&     (2, 3) + h1_t1*0.5*vs1b(2, 2)
    h2_d2b = h2_d2b + z_ha*0.5*vs2b(2, 3)
    cfm_d2b = z_cfm*vs2b(2, 3)
    cf2_d2b = cf2_d2b + z_cf2*vs2b(2, 3)
    vs2b(2, 3) = 0.0_8
    h2_t2b = h2_t2b + z_ha*0.5*vs2b(2, 2)
    cfm_t2b = z_cfm*vs2b(2, 2)
    cf2_t2b = cf2_t2b + z_cf2*vs2b(2, 2)
    z_t2b = vs2b(2, 2)
    vs2b(2, 2) = 0.0_8
    z_x1b = vs1b(2, 5)
    vs1b(2, 5) = 0.0_8
    m1_u1b = m1_u1b + z_ma*0.5*vs1b(2, 4)
    cfm_u1b = z_cfm*vs1b(2, 4)
    cf1_u1b = cf1_u1b + z_cf1*vs1b(2, 4)
    z_u1b = vs1b(2, 4)
    vs1b(2, 4) = 0.0_8
    h1_d1b = h1_d1b + z_ha*0.5*vs1b(2, 3)
    cfm_d1b = z_cfm*vs1b(2, 3)
    cf1_d1b = cf1_d1b + z_cf1*vs1b(2, 3)
    vs1b(2, 3) = 0.0_8
    h1_t1b = h1_t1b + z_ha*0.5*vs1b(2, 2)
    cfm_t1b = z_cfm*vs1b(2, 2)
    cf1_t1b = cf1_t1b + z_cf1*vs1b(2, 2)
    z_t1b = vs1b(2, 2)
    vs1b(2, 2) = 0.0_8
    ha = 0.5*(h1+h2)
    hwa = 0.5*(dw1/t1+dw2/t2)
    btmp = ha + 2.0 - ma + hwa
    z_ul = ddlog*btmp
    z_ulb = z_u2b/u2 - z_u1b/u1
    u2b = u2b - z_ul*z_u2b/u2**2
    u1b = u1b + z_ul*z_u1b/u1**2
    z_xl = -(ddlog*0.5*cfx)
    z_xlb = z_x2b/x2 - z_x1b/x1
    z_cfxb = cfx_x2*z_x2b + cfx_x1*z_x1b + cfx_t2*z_t2b + cfx_t1*z_t1b +&
&     cfx_cf2*z_cf2b + cfx_cf1*z_cf1b + cfx_cfm*z_cfmb
    cfx_x2b = z_cfx*z_x2b
    cfx_x1b = z_cfx*z_x1b
    z_hwa = ulog
    cfx_t2b = z_cfx*z_t2b
    tempb2 = -(0.5*z_t2b/t2**2)
    t2b = t2b - x2*xot2b/t2**2 - z_tl*z_t2b/t2**2 - 2*z_hwa*dw2*tempb2/&
&     t2
    z_hwab = dw2*tempb2
    dw2b = dw2b + z_hwa*tempb2
    cfx_t1b = z_cfx*z_t1b
    tempb2 = -(0.5*z_t1b/t1**2)
    t1b = t1b + z_tl*z_t1b/t1**2 - x1*xot1b/t1**2 - 2*z_hwa*dw1*tempb2/&
&     t1
    z_hwab = z_hwab + dw1*tempb2
    dw1b = dw1b + z_hwa*tempb2
    cfx_cf2b = z_cfx*z_cf2b
    cfx_cf1b = z_cfx*z_cf1b
    cfx_cfmb = z_cfx*z_cfmb
    btmpb = ddlog*z_ulb + ulog*reztb
    ulogb = ulogb + z_hwab - z_mab + z_hab + btmp*reztb
    xlogb = xlogb - 0.5*z_cfxb - cfx*0.5*reztb
    tlogb = reztb
    hab = btmpb
    mab = -btmpb
    hwab = btmpb
    tempb2 = 0.50*cfx_cfmb/ta
    xab = tempb2
    tab = -(xa*tempb2/ta)
    tempb2 = 0.25*cfx_cf2b/t2
    x2b = x2b + xot2b/t2 + tempb2 - z_xl*z_x2b/x2**2
    t2b = t2b - x2*tempb2/t2
    tempb2 = 0.25*cfx_cf1b/t1
    x1b = x1b + xot1b/t1 + z_xl*z_x1b/x1**2 + tempb2
    t1b = t1b - x1*tempb2/t1
    cfx_tab = 0.5*cfx_t2b + 0.5*cfx_t1b
    tempb2 = -(.25*cfx_t2b/t2**2)
    cf2b = cf2b + xot2*cfx_upwb + upw*xot2*cfxb + x2*tempb2
    x2b = x2b + cf2*tempb2
    t2b = t2b - 2*cf2*x2*tempb2/t2
    tempb2 = -(.25*cfx_t1b/t1**2)
    cf1b = cf1b + xot1*(1.0-upw)*cfxb - xot1*cfx_upwb + x1*tempb2
    cfxb = -(ddlog*0.5*z_xlb) - xlog*0.5*reztb
    x1b = x1b + cf1*tempb2
    t1b = t1b - 2*cf1*x1*tempb2/t1
    tempb2 = 0.25*cfx_x2b/t2
    cfx_xab = 0.5*cfx_x2b + 0.5*cfx_x1b
    t2b = t2b - cf2*tempb2/t2
    tempb1 = 0.25*cfxb/t1
    tempb0 = 0.25*cfxb/t2
    cf2b = cf2b + tempb2 + x2*tempb0
    tempb2 = 0.25*cfx_x1b/t1
    cf1b = cf1b + tempb2 + x1*tempb1
    t1b = t1b - cf1*tempb2/t1
    tempb2 = -(.50*cfx_tab/ta**2)
    cfmb = xa*tempb2
    xab = xab + cfm*tempb2
    tab = tab - 2*cfm*xa*tempb2/ta
    tempb2 = 0.50*cfx_xab/ta
    cfmb = cfmb + tempb2
    tab = tab - cfm*tempb2/ta
    tempb2 = 0.50*cfxb/ta
    cfmb = cfmb + xa*tempb2
    xab = xab + cfm*tempb2
    x2b = x2b + cf2*tempb0 + 0.5*xab
    x1b = x1b + cf1*tempb1 + 0.5*xab
    tab = tab - cfm*xa*tempb2/ta
    tempb2 = 0.5*hwab
    t2b = t2b + 0.5*tab - cf2*x2*tempb0/t2 - dw2*tempb2/t2**2
    t1b = t1b + 0.5*tab - cf1*x1*tempb1/t1 - dw1*tempb2/t1**2
    dw1b = dw1b + tempb2/t1
    dw2b = dw2b + tempb2/t2
    m1b = m1b + 0.5*mab
    m2b = m2b + 0.5*mab
    h1b = h1b + 0.5*hab
    h2b = h2b + 0.5*hab
    CALL POPCONTROL2B(branch)
    IF (branch .EQ. 0) THEN
      ampl2b = ampl2b - vsrezb(1)
      vsrezb(1) = 0.0_8
      vsrb(1) = 0.0_8
      vs2b(1, 1) = 0.0_8
    ELSE IF (branch .EQ. 1) THEN
      rezcb = -vsrezb(1)
      vsrezb(1) = 0.0_8
      vsxb(1) = 0.0_8
      z_axb = (ax_rt1*rt1_re+ax_rt2*rt2_re)*vsrb(1) + (ax_hk1*hk1_ms+&
&       ax_rt1*rt1_ms+ax_hk2*hk2_ms+ax_rt2*rt2_ms)*vsmb(1) + (ax_hk2*&
&       hk2_u2+ax_rt2*rt2_u2)*vs2b(1, 4) + ax_hk2*hk2_d2*vs2b(1, 3) + (&
&       ax_hk2*hk2_t2+ax_t2+ax_rt2*rt2_t2)*vs2b(1, 2) + ax_a2*vs2b(1, 1)&
&       + (ax_hk1*hk1_u1+ax_rt1*rt1_u1)*vs1b(1, 4) + ax_hk1*hk1_d1*vs1b(&
&       1, 3) + (ax_hk1*hk1_t1+ax_t1+ax_rt1*rt1_t1)*vs1b(1, 2) + ax_a1*&
&       vs1b(1, 1)
      tempb = z_ax*vsrb(1)
      vsrb(1) = 0.0_8
      ax_rt1b = rt1_re*tempb
      rt1_reb = rt1_reb + ax_rt1*tempb
      ax_rt2b = rt2_re*tempb
      rt2_reb = rt2_reb + ax_rt2*tempb
      tempb = z_ax*vsmb(1)
      vsmb(1) = 0.0_8
      ax_hk1b = hk1_ms*tempb
      hk1_msb = hk1_msb + ax_hk1*tempb
      ax_rt1b = ax_rt1b + rt1_ms*tempb
      rt1_msb = rt1_msb + ax_rt1*tempb
      ax_hk2b = hk2_ms*tempb
      hk2_msb = hk2_msb + ax_hk2*tempb
      ax_rt2b = ax_rt2b + rt2_ms*tempb
      rt2_msb = rt2_msb + ax_rt2*tempb
      axb = vs1b(1, 5) - vs2b(1, 5) - (x2-x1)*rezcb
      vs2b(1, 5) = 0.0_8
      tempb = z_ax*vs2b(1, 4)
      vs2b(1, 4) = 0.0_8
      ax_hk2b = ax_hk2b + hk2_u2*tempb
      hk2_u2b = hk2_u2b + ax_hk2*tempb
      ax_rt2b = ax_rt2b + rt2_u2*tempb
      rt2_u2b = rt2_u2b + ax_rt2*tempb
      hk2_d2b = hk2_d2b + z_ax*ax_hk2*vs2b(1, 3)
      tempb = z_ax*vs2b(1, 2)
      ax_hk2b = ax_hk2b + z_ax*hk2_d2*vs2b(1, 3) + hk2_t2*tempb
      vs2b(1, 3) = 0.0_8
      vs2b(1, 2) = 0.0_8
      hk2_t2b = hk2_t2b + ax_hk2*tempb
      ax_t2b = tempb
      ax_rt2b = ax_rt2b + rt2_t2*tempb
      rt2_t2b = rt2_t2b + ax_rt2*tempb
      ax_a2b = z_ax*vs2b(1, 1)
      vs2b(1, 1) = 0.0_8
      vs1b(1, 5) = 0.0_8
      tempb = z_ax*vs1b(1, 4)
      vs1b(1, 4) = 0.0_8
      ax_hk1b = ax_hk1b + hk1_u1*tempb
      hk1_u1b = hk1_u1b + ax_hk1*tempb
      ax_rt1b = ax_rt1b + rt1_u1*tempb
      rt1_u1b = rt1_u1b + ax_rt1*tempb
      hk1_d1b = hk1_d1b + z_ax*ax_hk1*vs1b(1, 3)
      tempb = z_ax*vs1b(1, 2)
      ax_hk1b = ax_hk1b + z_ax*hk1_d1*vs1b(1, 3) + hk1_t1*tempb
      vs1b(1, 3) = 0.0_8
      vs1b(1, 2) = 0.0_8
      hk1_t1b = hk1_t1b + ax_hk1*tempb
      ax_t1b = tempb
      ax_rt1b = ax_rt1b + rt1_t1*tempb
      rt1_t1b = rt1_t1b + ax_rt1*tempb
      ax_a1b = z_ax*vs1b(1, 1)
      vs1b(1, 1) = 0.0_8
      x1b = x1b + z_axb + ax*rezcb
      x2b = x2b - z_axb - ax*rezcb
      ampl2b = ampl2b + rezcb
      ampl1b = ampl1b - rezcb
      CALL AXSET_BWD(hk1, hk1b, t1, t1b, rt1, rt1b, ampl1, ampl1b, hk2, &
&              hk2b, t2, t2b, rt2, rt2b, ampl2, ampl2b, amcrit, amcritb&
&              , idampv, ax, axb, ax_hk1, ax_hk1b, ax_t1, ax_t1b, ax_rt1&
&              , ax_rt1b, ax_a1, ax_a1b, ax_hk2, ax_hk2b, ax_t2, ax_t2b&
&              , ax_rt2, ax_rt2b, ax_a2, ax_a2b)
    ELSE
      rezcb = -vsrezb(1)
      vsrezb(1) = 0.0_8
      vsxb(1) = 0.0_8
      z_cf1 = (1.0-upw)*z_cfa
      z_cf2 = upw*z_cfa
      z_cq1b = cq1_re*vsrb(1) + cq1_ms*vsmb(1) + cq1_u1*vs1b(1, 4) + &
&       cq1_d1*vs1b(1, 3) + cq1_t1*vs1b(1, 2)
      cq1_reb = cq1_reb + z_cq1*vsrb(1)
      z_cf1b = cf1_re*vsrb(1) + cf1_ms*vsmb(1) + cf1_u1*vs1b(1, 4) + &
&       cf1_d1*vs1b(1, 3) + cf1_t1*vs1b(1, 2)
      cf1_reb = cf1_reb + z_cf1*vsrb(1)
      z_cq2b = cq2_re*vsrb(1) + cq2_ms*vsmb(1) + cq2_u2*vs2b(1, 4) + &
&       cq2_d2*vs2b(1, 3) + cq2_t2*vs2b(1, 2)
      cq2_reb = cq2_reb + z_cq2*vsrb(1)
      z_cf2b = cf2_re*vsrb(1) + cf2_ms*vsmb(1) + cf2_u2*vs2b(1, 4) + &
&       cf2_d2*vs2b(1, 3) + cf2_t2*vs2b(1, 2)
      cf2_reb = cf2_reb + z_cf2*vsrb(1)
      vsrb(1) = 0.0_8
      cq1_msb = cq1_msb + z_cq1*vsmb(1)
      cf1_msb = cf1_msb + z_cf1*vsmb(1)
      z_hk1b = hk1_ms*vsmb(1) + hk1_u1*vs1b(1, 4) + hk1_d1*vs1b(1, 3) + &
&       hk1_t1*vs1b(1, 2)
      hk1_msb = hk1_msb + z_hk1*vsmb(1)
      cq2_msb = cq2_msb + z_cq2*vsmb(1)
      cf2_msb = cf2_msb + z_cf2*vsmb(1)
