    hk = (h-0.29*msq)/(1.0+0.113*msq)
    hk_h = 1.0/(1.0+0.113*msq)
    hk_msq = (-.29-0.113*hk)/(1.0+0.113*msq)
  END SUBROUTINE HKIN

