    cfo = cffac*0.3*EXP(arg)*(grt/2.3026)**gex
    CALL PUSHREAL8(cf)
    cf = (cfo+1.1e-4*(thk-1.0))/fc
    temp0 = fc*fc*fc
    tempb1 = -(gm1*0.25*cf_msqb/(temp0*grt))
    tempb2 = -(gm1*0.25*cf_msqb/fc**2)
    cfb = cfb + tempb2
    gexb = cfo*tempb1
    cfob = gex*tempb1
    tempb = -(gex*cfo*tempb1/(temp0*grt))
    grtb = temp0*tempb
    temp0 = fc*grt*rt
    tempb1 = cf_rtb/temp0
    tempb0 = -(gex*cfo*tempb1/temp0)
    fcb = 3*fc**2*grt*tempb - 2*cf*tempb2/fc + grt*rt*tempb0
    grtb = grtb + fc*rt*tempb0
    rtb = rtb + fc*grt*tempb0
    temp = LOG(grt/2.3026)
    tempb0 = cf_hkb/fc
    cfob = cfob + gex*tempb1 - (temp*0.31+1.33)*tempb0
    grtb = grtb - cfo*0.31*tempb0/grt
    thkb = 2*thk*1.1e-4*tempb0/0.875
    fcb = fcb - (-(1.33*cfo)-0.31*(temp*cfo)-1.1e-4*((1.0-thk**2)/0.875)&
&     )*tempb0/fc
    CALL POPREAL8(cf)
    tempb0 = cfb/fc
    cfob = cfob + tempb0
    thkb = thkb + 1.1e-4*tempb0
    fcb = fcb - (cfo+1.1e-4*(thk-1.0))*tempb0/fc
    temp = grt/2.3026
    temp0 = temp**gex
    tempb = cffac*0.3*cfob
    argb = EXP(arg)*temp0*tempb
    tempb0 = EXP(arg)*tempb
    IF (temp .LE. 0.0_8) THEN
      gexb = gexb + cfo*tempb1
    ELSE
      gexb = gexb + cfo*tempb1 + temp0*LOG(temp)*tempb0
    END IF
    IF (.NOT.(temp .LE. 0.0_8 .AND. (gex .EQ. 0.0_8 .OR. gex .NE. INT(&
&       gex)))) grtb = grtb + gex*temp**(gex-1)*tempb0/2.3026
    hkb = hkb - (1.0-TANH(4.0-hk/0.875)**2)*thkb/0.875
    CALL POPCONTROL1B(branch)
    IF (branch .NE. 0) argb = 0.0_8
    hkb = hkb - 1.33*argb - 0.31*gexb
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) grtb = 0.0_8
    tempb = grtb/rt
    rtb = rtb + tempb
    fcb = fcb - rt*tempb/fc
    IF (.NOT.gm1*0.5*msq + 1.0 .EQ. 0.0_8) msqb = msqb + gm1*0.5*fcb/(&
&       2.0*SQRT(gm1*0.5*msq+1.0))
  END SUBROUTINE CFT_B

!*==CFT.f90  processed by SPAG 7.21DC at 11:25 on 11 Jan 2019
  SUBROUTINE CFT(hk, rt, msq, cf, cf_hk, cf_rt, cf_msq)
    USE I_BLPAR
    IMPLICIT NONE
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
    REAL :: cf, cf_hk, cf_msq, cf_rt, hk, msq, rt
! intent (in) Hk, Msq, Rt
! intent (out) Cf_hk, Cf_msq, Cf_rt
! intent (inout) Cf
!
! Local variables
!
    REAL :: arg, cfo, fc, gex, gm1, grt, thk
    REAL, SAVE :: gam
    INTRINSIC SQRT
    INTRINSIC LOG
    INTRINSIC MAX
    INTRINSIC TANH
    INTRINSIC EXP
!
!*** End of declarations rewritten by SPAG
!
!
!*** Start of declarations rewritten by SPAG
!
! Dummy arguments
!
!
! Local variables
!
!
!*** End of declarations rewritten by SPAG
!
!
    DATA gam /1.4/
!
!---- Turbulent skin friction function  ( Cf )    (Coles)
    gm1 = gam - 1.0
    fc = SQRT(1.0 + 0.5*gm1*msq)
    grt = LOG(rt/fc)
    IF (grt .LT. 3.0) THEN
      grt = 3.0
    ELSE
      grt = grt
    END IF
!
    gex = -1.74 - 0.31*hk
!
    arg = -(1.33*hk)
    IF (-20.0 .LT. arg) THEN
      arg = arg
    ELSE
      arg = -20.0
    END IF
!
    thk = TANH(4.0 - hk/0.875)
!
    cfo = cffac*0.3*EXP(arg)*(grt/2.3026)**gex
    cf = (cfo+1.1e-4*(thk-1.0))/fc
    cf_hk = (-(1.33*cfo)-0.31*LOG(grt/2.3026)*cfo-1.1e-4*(1.0-thk**2)/&
&     0.875)/fc
    cf_rt = gex*cfo/(fc*grt)/rt
    cf_msq = gex*cfo/(fc*grt)*(-(0.25*gm1/fc**2)) - 0.25*gm1*cf/fc**2
